DECLARE
  v_grn RECORD;
  v_item RECORD;
  v_main_store_id UUID;
  v_target_wh_id UUID;
  v_stock RECORD;
  v_inward_id UUID;
  v_processed_count INT := 0;
BEGIN
  -- 1. Verify user organisation membership
  IF NOT EXISTS (
    SELECT 1 FROM user_organisations
    WHERE organisation_id = p_org_id AND user_id = auth.uid() AND status = 'active'
  ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Not an active member of this organisation');
  END IF;

  -- 2. Lock GRN row FOR UPDATE for thread safety & concurrency protection
  SELECT id, grn_no, status, vendor_name, organisation_id INTO v_grn
  FROM goods_receipt_notes
  WHERE id = p_grn_id
  FOR UPDATE;

  IF v_grn.id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Goods Receipt Note (GRN) not found');
  END IF;

  IF v_grn.organisation_id != p_org_id THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Organisation mismatch');
  END IF;

  -- 3. Idempotency Check: if already accepted, return success without re-processing stock
  IF v_grn.status = 'accepted' THEN
    RETURN jsonb_build_object(
      'ok', true,
      'already_processed', true,
      'message', 'GRN is already accepted and processed.',
      'grn_id', p_grn_id
    );
  END IF;

  -- 4. Fallback Main Store Warehouse resolution (if line item has no warehouse_id)
  SELECT id INTO v_main_store_id
  FROM warehouses
  WHERE organisation_id = p_org_id AND warehouse_purpose = 'main' AND is_active = true
  LIMIT 1;

  IF v_main_store_id IS NULL THEN
    SELECT id INTO v_main_store_id
    FROM warehouses
    WHERE organisation_id = p_org_id AND is_default = true AND is_active = true
    LIMIT 1;
  END IF;

  IF v_main_store_id IS NULL THEN
    SELECT id INTO v_main_store_id
    FROM warehouses
    WHERE organisation_id = p_org_id AND is_active = true
    LIMIT 1;
  END IF;

  IF v_main_store_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'No active warehouse found for organisation');
  END IF;

  -- 5. Create Material Inward Header for Audit Trail
  INSERT INTO material_inward (
    inward_date, vendor_name, remarks, organisation_id, supply_type
  ) VALUES (
    CURRENT_DATE,
    COALESCE(v_grn.vendor_name, 'Supplier GRN'),
    'GRN ' || v_grn.grn_no || ' accepted into inventory',
    p_org_id,
    'PURCHASE'
  )
  RETURNING id INTO v_inward_id;

  -- 6. Iterate through GRN Items & update stock dynamically per line-item warehouse
  FOR v_item IN
    SELECT gi.id, gi.material_id, gi.received_qty, gi.accepted_qty, gi.unit, gi.warehouse_id, m.name AS material_name
    FROM grn_items gi
    JOIN materials m ON m.id = gi.material_id
    WHERE gi.grn_id = p_grn_id
  LOOP
    -- Use line item's specified warehouse_id if set; fallback to main store
    v_target_wh_id := COALESCE(v_item.warehouse_id, v_main_store_id);

    -- Quantity to receive: use accepted_qty if > 0, otherwise received_qty
    DECLARE
      v_qty_to_add NUMERIC := COALESCE(NULLIF(v_item.accepted_qty, 0), v_item.received_qty, 0);
    BEGIN
      IF v_qty_to_add > 0 THEN
        -- Lock item_stock row FOR UPDATE
        SELECT id, current_stock INTO v_stock
        FROM item_stock
        WHERE item_id = v_item.material_id
          AND warehouse_id = v_target_wh_id
          AND organisation_id = p_org_id
        FOR UPDATE;

        IF v_stock.id IS NULL THEN
          INSERT INTO item_stock (item_id, warehouse_id, current_stock, organisation_id, is_active)
          VALUES (v_item.material_id, v_target_wh_id, v_qty_to_add, p_org_id, true)
          RETURNING id INTO v_stock.id;
        ELSE
          UPDATE item_stock
          SET current_stock = current_stock + v_qty_to_add,
              updated_at = NOW()
          WHERE id = v_stock.id;
        END IF;

        -- Create Material Inward Item audit row
        INSERT INTO material_inward_items (
          material_inward_id, material_name, quantity, unit, material_id, warehouse_id, organisation_id
        ) VALUES (
          v_inward_id,
          COALESCE(v_item.material_name, ''),
          v_qty_to_add,
          COALESCE(v_item.unit, 'nos'),
          v_item.material_id,
          v_target_wh_id,
          p_org_id
        );

        -- Update line item status
        UPDATE grn_items
        SET status = 'accepted',
            accepted_qty = v_qty_to_add
        WHERE id = v_item.id;

        v_processed_count := v_processed_count + 1;
      END IF;
    END;
  END LOOP;

  -- 7. Mark GRN as accepted
  UPDATE goods_receipt_notes
  SET status = 'accepted',
      updated_at = NOW()
  WHERE id = p_grn_id;

  -- 8. Log manufacturing activity
  INSERT INTO manufacturing_activity_log (
    entity_type, entity_id, action, action_details, user_id, organisation_id
  ) VALUES (
    'grn', p_grn_id, 'accepted',
    jsonb_build_object(
      'grn_no', v_grn.grn_no,
      'items_processed', v_processed_count,
      'inward_id', v_inward_id
    ),
    auth.uid(), p_org_id
  );

  RETURN jsonb_build_object(
    'ok', true,
    'already_proc

DECLARE
    invitation_record RECORD;
    org_record RECORD;
    membership_record RECORD;
    invitation_valid BOOLEAN := FALSE;
    invitation_expired BOOLEAN := FALSE;
    user_exists BOOLEAN := FALSE;
    
BEGIN
    -- Get invitation details
    SELECT * INTO invitation_record 
    FROM invitations 
    WHERE token = token_param;
    
    -- Check if invitation exists and is valid
    IF invitation_record.id IS NOT NULL THEN
        invitation_valid := TRUE;
        
        -- Check if invitation is expired
        IF invitation_record.expires_at < NOW() THEN
            invitation_expired := TRUE;
        END IF;
        
        -- Check if user already exists in system
        SELECT EXISTS(SELECT 1 FROM user_profiles WHERE id = user_id_param) INTO user_exists;
        
        -- Only proceed if invitation is valid and not expired and user doesn't exist
        IF invitation_valid = TRUE AND invitation_expired = FALSE AND user_exists = FALSE THEN
            -- Get organization details
            SELECT * INTO org_record 
            FROM organisations 
            WHERE id = invitation_record.organisation_id;
            
            -- Create user-organization membership
            INSERT INTO user_organisations (
                user_id,
                organisation_id,
                role,
                status,
                joined_at,
                is_default,
                trial_ends_at
            ) VALUES (
                user_id_param,
                invitation_record.organisation_id,
                invitation_record.role,
                'active',
                NOW(),
                TRUE,
                CASE 
                    WHEN org_record.trial_period_days IS NOT NULL 
                    THEN NOW() + (org_record.trial_period_days || '30 days')::INTERVAL
                    ELSE NULL
                END
            );
            
            -- Update invitation status
            UPDATE invitations 
            SET status = 'accepted', 
                accepted_at = NOW(),
                accepted_by_user_id = user_id_param
            WHERE id = invitation_record.id;
            
            -- Update user profile with organization role
            UPDATE user_profiles 
            SET role = invitation_record.role 
            WHERE id = user_id_param;
            
            RETURN json_build_object(
                'success', TRUE,
                'message', 'Invitation accepted successfully',
                'organisation_id', invitation_record.organisation_id,
                'role', invitation_record.role
            );
        ELSE
            RETURN json_build_object(
                'success', FALSE,
                'message', CASE 
                    WHEN invitation_record.id IS NULL THEN 'Invalid invitation token'
                    WHEN invitation_expired THEN 'Invitation has expired'
                    WHEN user_exists THEN 'User already exists in system'
                    ELSE 'Invalid invitation'
                END
            );
        END IF;
    ELSE
        RETURN json_build_object(
            'success', FALSE,
            'message', 'Invalid invitation token'
        );
    END IF;
END;

DECLARE
  v_proforma RECORD;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF NOT public.user_can_access_org(p_organisation_id) THEN RAISE EXCEPTION 'Unauthorized organization access'; END IF;

  SELECT * INTO v_proforma FROM public.proforma_invoices
  WHERE id = p_proforma_id AND organisation_id = p_organisation_id FOR UPDATE;

  IF v_proforma IS NULL THEN RAISE EXCEPTION 'Proforma invoice not found or unauthorized'; END IF;

  IF LOWER(COALESCE(v_proforma.status, '')) IN ('accepted', 'converted') THEN
    RETURN jsonb_build_object('status', 'already_accepted', 'proforma_id', p_proforma_id);
  END IF;

  UPDATE public.proforma_invoices
  SET status = 'accepted', accepted_at = NOW(), updated_at = NOW()
  WHERE id = p_proforma_id;

  RETURN jsonb_build_object('status', 'success', 'proforma_id', p_proforma_id);
END;

DECLARE
  v_user_id UUID;
  v_org_id UUID;
  v_att project_collaboration_attachments;
  v_path_key TEXT;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;

  SELECT organisation_id INTO v_org_id
  FROM project_collaboration_messages WHERE id = p_message_id;
  IF v_org_id IS NULL THEN RAISE EXCEPTION 'message_not_found'; END IF;
  IF NOT EXISTS (
    SELECT 1 FROM org_members WHERE organisation_id = v_org_id AND user_id = v_user_id
  ) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  -- Path key is a stable, deterministic key per file location so a
  -- retried call after a partial success collapses to one row.
  v_path_key := p_storage_bucket || '/' || p_storage_path;

  INSERT INTO project_collaboration_attachments (
    organisation_id, message_id, storage_bucket, storage_path,
    file_name, file_size, mime_type, width, height, duration_ms,
    upload_status, created_by
  )
  VALUES (
    v_org_id, p_message_id, p_storage_bucket, p_storage_path,
    p_file_name, p_file_size, p_mime_type, p_width, p_height, p_duration_ms,
    'uploaded', v_user_id
  )
  ON CONFLICT (message_id, storage_path) DO UPDATE
    SET file_name = EXCLUDED.file_name,
        file_size = EXCLUDED.file_size,
        mime_type = EXCLUDED.mime_type,
        width = EXCLUDED.width,
        height = EXCLUDED.height,
        duration_ms = EXCLUDED.duration_ms,
        upload_status = 'uploaded'
  RETURNING * INTO v_att;

  -- Keep the v_path_key reference so a future audit/log doesn't lose it.
  PERFORM v_path_key;

  RETURN v_att;
END;

BEGIN
  -- 1. Authentication check
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  -- 2. Input validation
  IF p_organisation_id IS NULL OR p_user_id IS NULL THEN
    RAISE EXCEPTION 'Organisation ID and User ID are required';
  END IF;

  -- 3. Authorization check: caller must be an active admin or have user management permission in target org
  IF NOT (
    public.is_org_admin(p_organisation_id)
    OR public.app_has_org_permission(p_organisation_id, 'org.manage_users')
    OR public.app_has_org_permission(p_organisation_id, 'admin')
  ) THEN
    RAISE EXCEPTION 'Access denied: caller is not authorized to manage members for organisation %', p_organisation_id;
  END IF;

  -- 4. Target user existence check
  IF NOT EXISTS (SELECT 1 FROM public.users WHERE id = p_user_id) AND
     NOT EXISTS (SELECT 1 FROM auth.users WHERE id = p_user_id) THEN
    RAISE EXCEPTION 'Target user % does not exist', p_user_id;
  END IF;

  -- 5. Execute membership insertion with status = active
  INSERT INTO public.org_members (organisation_id, user_id, role, status)
  VALUES (p_organisation_id, p_user_id, COALESCE(p_role, 'Employee'), 'active')
  ON CONFLICT (organisation_id, user_id)
  DO UPDATE SET
    role = COALESCE(EXCLUDED.role, org_members.role),
    status = 'active';
END;

DECLARE
  v_rcm_id UUID;
  v_tax_rate DECIMAL(5,2);
  v_total_rcm DECIMAL(15,2);
  v_result JSONB;
BEGIN
  -- Validate period format
  IF NOT validate_gst_period(p_period_month) THEN
    RAISE EXCEPTION 'Invalid period format. Expected MM/YYYY';
  END IF;

  -- Get tax rate from master
  SELECT tax_rate INTO v_tax_rate
  FROM rcm_masters
  WHERE id = p_rcm_master_id AND organisation_id = p_organisation_id;

  IF v_tax_rate IS NULL THEN
    v_tax_rate := 18.00;
  END IF;

  -- Calculate RCM amount
  v_total_rcm := p_taxable_value * (v_tax_rate / 100);

  -- Insert RCM data
  INSERT INTO rcm_data (
    organisation_id,
    period_month,
    rcm_master_id,
    supplier_gstin,
    supplier_name,
    invoice_no,
    invoice_date,
    taxable_value,
    total_rcm
  )
  VALUES (
    p_organisation_id,
    p_period_month,
    p_rcm_master_id,
    p_supplier_gstin,
    p_supplier_name,
    p_invoice_no,
    p_invoice_date,
    p_taxable_value,
    v_total_rcm
  )
  RETURNING id INTO v_rcm_id;

  v_result := jsonb_build_object(
    'status', 'success',
    'rcm_id', v_rcm_id,
    'total_rcm', v_total_rcm,
    'message', 'RCM data added successfully'
  );

  RETURN v_result;
END;

DECLARE
  v_user_id UUID;
  v_org_id UUID;
  v_r project_collaboration_reactions;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;

  SELECT m.organisation_id INTO v_org_id
  FROM project_collaboration_messages m WHERE m.id = p_message_id;
  IF v_org_id IS NULL THEN RAISE EXCEPTION 'message_not_found'; END IF;
  IF NOT EXISTS (
    SELECT 1 FROM org_members WHERE organisation_id = v_org_id AND user_id = v_user_id
  ) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  INSERT INTO project_collaboration_reactions (organisation_id, message_id, user_id, emoji)
  VALUES (v_org_id, p_message_id, v_user_id, p_emoji)
  ON CONFLICT (message_id, user_id, emoji) DO UPDATE
    SET created_at = project_collaboration_reactions.created_at
  RETURNING * INTO v_r;
  RETURN v_r;
END;

DECLARE
  v_org_id UUID;
  v_user_id UUID;
  v_header_wh_id UUID;
  v_reason TEXT;
  v_remarks TEXT;
  r_item RECORD;
  v_stock_id UUID;
  v_current_stock NUMERIC;
  v_target_qty NUMERIC;
  v_delta NUMERIC;
  v_new_stock NUMERIC;
  v_item_wh_id UUID;
  v_item_variant_id UUID;
  v_adjusted_count INT := 0;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;

  v_org_id := (NULLIF(p_adjustment_data->>'organisation_id', ''))::UUID;
  IF v_org_id IS NULL THEN RAISE EXCEPTION 'organisation_id is required'; END IF;

  IF NOT public.user_can_access_org(v_org_id) THEN
    RAISE EXCEPTION 'Unauthorized organization access';
  END IF;

  v_header_wh_id := (NULLIF(p_adjustment_data->>'warehouse_id', ''))::UUID;
  v_reason := COALESCE(NULLIF(TRIM(p_adjustment_data->>'reason'), ''), 'Stock Adjustment');
  v_remarks := NULLIF(TRIM(p_adjustment_data->>'remarks'), '');

  IF p_items IS NULL OR jsonb_array_length(p_items) = 0 THEN
    RAISE EXCEPTION 'Adjustment must contain at least one item';
  END IF;

  FOR r_item IN SELECT * FROM jsonb_to_recordset(p_items) AS x(
    item_id uuid,
    variant_id uuid,
    warehouse_id uuid,
    target_qty numeric,
    delta_qty numeric,
    mode text,
    item_name text
  )
  LOOP
    v_item_wh_id := COALESCE(r_item.warehouse_id, v_header_wh_id);
    IF v_item_wh_id IS NULL THEN
      RAISE EXCEPTION 'Warehouse is required for item %', COALESCE(r_item.item_name, r_item.item_id::TEXT);
    END IF;

    v_item_variant_id := r_item.variant_id;

    SELECT id, current_stock INTO v_stock_id, v_current_stock
    FROM public.item_stock
    WHERE item_id = r_item.item_id
      AND warehouse_id = v_item_wh_id
      AND ((v_item_variant_id IS NULL AND company_variant_id IS NULL) OR company_variant_id = v_item_variant_id)
    FOR UPDATE;

    v_current_stock := COALESCE(v_current_stock, 0);

    IF UPPER(COALESCE(r_item.mode, 'ABSOLUTE')) = 'RELATIVE' THEN
      v_delta := COALESCE(r_item.delta_qty, 0);
      v_new_stock := v_current_stock + v_delta;
    ELSE
      v_target_qty := COALESCE(r_item.target_qty, 0);
      v_delta := v_target_qty - v_current_stock;
      v_new_stock := v_target_qty;
    END IF;

    IF v_new_stock < 0 THEN
      RAISE EXCEPTION 'Negative stock balance (%) not allowed for item %', v_new_stock, COALESCE(r_item.item_name, r_item.item_id::TEXT);
    END IF;

    -- Only apply mutation if there is an actual change
    IF v_delta != 0 OR v_stock_id IS NULL THEN
      IF v_stock_id IS NOT NULL THEN
        UPDATE public.item_stock
        SET current_stock = v_new_stock, updated_at = NOW()
        WHERE id = v_stock_id;
      ELSE
        INSERT INTO public.item_stock (
          organisation_id, item_id, warehouse_id, company_variant_id, current_stock
        ) VALUES (
          v_org_id, r_item.item_id, v_item_wh_id, v_item_variant_id, v_new_stock
        );
      END IF;

      INSERT INTO public.material_logs (
        organisation_id, item_id, variant_id,
        qty_received, qty_used, type, invoice_number, received_by, remarks, created_at
      ) VALUES (
        v_org_id, r_item.item_id, v_item_variant_id,
        CASE WHEN v_delta > 0 THEN v_delta ELSE 0 END,
        CASE WHEN v_delta < 0 THEN ABS(v_delta) ELSE 0 END,
        'ADJUSTMENT', 'STOCK_ADJUSTMENT', v_user_id,
        'Stock Adjustment: ' || v_reason || ' (From ' || v_current_stock || ' to ' || v_new_stock || ')' || COALESCE(' - ' || v_remarks, ''), NOW()
      );

      v_adjusted_count := v_adjusted_count + 1;
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'status', 'success',
    'adjusted_items_count', v_adjusted_count
  );
END;

DECLARE
  v_stock_id UUID;
  v_current_stock NUMERIC;
  v_new_stock NUMERIC;
  v_org_id UUID;
  v_user_id UUID;
BEGIN
  v_user_id := auth.uid();

  SELECT organisation_id INTO v_org_id FROM public.warehouses WHERE id = p_warehouse_id;
  IF v_org_id IS NULL THEN
    SELECT organisation_id INTO v_org_id FROM public.materials WHERE id = p_item_id;
  END IF;

  IF v_user_id IS NOT NULL AND v_org_id IS NOT NULL AND NOT public.user_can_access_org(v_org_id) THEN
    RAISE EXCEPTION 'Unauthorized organization access';
  END IF;

  SELECT id, current_stock INTO v_stock_id, v_current_stock
  FROM public.item_stock
  WHERE item_id = p_item_id
    AND warehouse_id = p_warehouse_id
    AND ((p_variant_id IS NULL AND company_variant_id IS NULL) OR company_variant_id = p_variant_id)
  FOR UPDATE;

  v_current_stock := COALESCE(v_current_stock, 0);
  v_new_stock := v_current_stock + p_delta;

  IF v_new_stock < 0 THEN
    RAISE EXCEPTION 'Cannot adjust stock below zero. Current stock: %, Delta: %, Result: %',
      v_current_stock, p_delta, v_new_stock;
  END IF;

  IF v_stock_id IS NOT NULL THEN
    UPDATE public.item_stock
    SET current_stock = v_new_stock, updated_at = NOW()
    WHERE id = v_stock_id;
  ELSE
    INSERT INTO public.item_stock (
      organisation_id, item_id, warehouse_id, company_variant_id, current_stock
    ) VALUES (
      v_org_id, p_item_id, p_warehouse_id, p_variant_id, v_new_stock
    );
  END IF;

  INSERT INTO public.material_logs (
    organisation_id, item_id, variant_id,
    qty_received, qty_used, type, invoice_number, received_by, remarks, created_at
  ) VALUES (
    v_org_id, p_item_id, p_variant_id,
    CASE WHEN p_delta > 0 THEN p_delta ELSE 0 END,
    CASE WHEN p_delta < 0 THEN ABS(p_delta) ELSE 0 END,
    CASE WHEN p_delta > 0 THEN 'IN' ELSE 'OUT' END,
    'ADJ-' || TO_CHAR(NOW(), 'YYYYMMDD-HH24MISS'),
    v_user_id,
    COALESCE(p_reason, 'Stock Adjustment') || COALESCE(': ' || p_notes, ''),
    NOW()
  );

  RETURN jsonb_build_object(
    'status', 'success',
    'item_id', p_item_id,
    'warehouse_id', p_warehouse_id,
    'previous_stock', v_current_stock,
    'delta', p_delta,
    'new_stock', v_new_stock
  );
END;

DECLARE
    v_org_id uuid;
    v_warehouse_org_id uuid;
    v_material_org_id uuid;
    v_current_stock numeric;
    v_new_stock numeric;
    v_stock_id uuid;
    v_qty_received numeric := 0;
    v_qty_used numeric := 0;
BEGIN
    -- 1. Validate warehouse and material ownership
    SELECT organisation_id INTO v_warehouse_org_id FROM public.warehouses WHERE id = p_warehouse_id;
    IF v_warehouse_org_id IS NULL THEN
        RAISE EXCEPTION 'Warehouse % not found', p_warehouse_id;
    END IF;

    SELECT organisation_id INTO v_material_org_id FROM public.materials WHERE id = p_item_id;
    IF v_material_org_id IS NULL THEN
        RAISE EXCEPTION 'Material % not found', p_item_id;
    END IF;

    IF v_warehouse_org_id <> v_material_org_id THEN
        RAISE EXCEPTION 'Cross-tenant mismatch: warehouse org % does not match material org %', v_warehouse_org_id, v_material_org_id;
    END IF;

    v_org_id := v_warehouse_org_id;

    -- 2. Validate caller has active access to this organisation
    IF public.user_can_access_org(v_org_id) IS NOT TRUE THEN
        RAISE EXCEPTION 'Access denied: caller does not have active membership in organisation %', v_org_id;
    END IF;

    -- 3. Lock stock record for update or initialize
    SELECT id, coalesce(current_stock, 0) INTO v_stock_id, v_current_stock
    FROM public.item_stock
    WHERE item_id = p_item_id AND warehouse_id = p_warehouse_id
    FOR UPDATE;

    IF v_stock_id IS NULL THEN
        IF p_quantity_change < 0 THEN
            RAISE EXCEPTION 'Cannot reduce stock for item without existing stock record';
        END IF;
        v_new_stock := p_quantity_change;
        INSERT INTO public.item_stock (organisation_id, item_id, warehouse_id, current_stock)
        VALUES (v_org_id, p_item_id, p_warehouse_id, v_new_stock)
        RETURNING id INTO v_stock_id;
    ELSE
        v_new_stock := v_current_stock + p_quantity_change;
        IF v_new_stock < 0 THEN
            RAISE EXCEPTION 'Insufficient stock: current stock is %, requested change is %', v_current_stock, p_quantity_change;
        END IF;
        UPDATE public.item_stock
        SET current_stock = v_new_stock,
            organisation_id = v_org_id,
            updated_at = now()
        WHERE id = v_stock_id;
    END IF;

    -- 4. Calculate movement quantities
    IF p_quantity_change >= 0 THEN
        v_qty_received := p_quantity_change;
        v_qty_used := 0;
    ELSE
        v_qty_received := 0;
        v_qty_used := abs(p_quantity_change);
    END IF;

    -- 5. Record authoritative movement log in material_logs
    INSERT INTO public.material_logs (
        organisation_id,
        item_id,
        project_id,
        qty_received,
        qty_used,
        type,
        invoice_number,
        remarks,
        received_by,
        created_at
    )
    VALUES (
        v_org_id,
        p_item_id,
        p_project_id,
        v_qty_received,
        v_qty_used,
        coalesce(p_movement_type, 'ADJUSTMENT'),
        p_reference,
        p_remarks,
        auth.uid(),
        now()
    );

    RETURN jsonb_build_object(
        'success', true,
        'stock_id', v_stock_id,
        'organisation_id', v_org_id,
        'item_id', p_item_id,
        'warehouse_id', p_warehouse_id,
        'previous_stock', v_current_stock,
        'new_stock', v_new_stock,
        'change', p_quantity_change
    );
END;

DECLARE
  v_org UUID;
  v_bin UUID;
  v_item UUID;
  v_qty NUMERIC;
  v_max NUMERIC;
  v_next NUMERIC;
  v_applied NUMERIC;
BEGIN
  SELECT organisation_id, bin_id, item_id, quantity
    INTO v_org, v_bin, v_item, v_qty
    FROM warehouse_bin_items
   WHERE id = p_row_id AND deleted_at IS NULL;
  IF v_org IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Bin item row not found');
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM user_organisations
     WHERE organisation_id = v_org AND user_id = auth.uid() AND status = 'active'
  ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Not a member of this organisation');
  END IF;

  -- Defense-in-depth: the row is org-scoped, but the bin it references must
  -- also belong to the org (same hardening as the 006 transfer RPC).
  IF NOT EXISTS (
    SELECT 1 FROM warehouse_bins
     WHERE id = v_bin AND organisation_id = v_org AND deleted_at IS NULL
  ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Bin not found in this organisation');
  END IF;

  IF p_delta = 0 THEN
    RETURN jsonb_build_object('ok', true, 'bin_item_id', p_row_id, 'applied_delta', 0);
  END IF;

  -- Capacity on increases only.
  IF p_delta > 0 THEN
    SELECT max_quantity INTO v_max
      FROM warehouse_bins WHERE id = v_bin AND deleted_at IS NULL;
    IF COALESCE(v_max, 0) > 0 AND v_qty + p_delta > v_max THEN
      RETURN jsonb_build_object('ok', false, 'error',
        'Bin capacity exceeded: ' || v_qty || ' + ' || p_delta || ' > ' || v_max);
    END IF;
  END IF;

  v_next := v_qty + p_delta;

  IF v_next <= 0 THEN
    -- Full removal: audit the quantity that actually leaves the bin.
    v_applied := -v_qty;
    UPDATE warehouse_bin_items
       SET deleted_at = now(), quantity = 0, updated_by = p_operator_id, updated_at = now()
     WHERE id = p_row_id;
  ELSE
    v_applied := p_delta;
    UPDATE warehouse_bin_items
       SET quantity = v_next, updated_by = p_operator_id, updated_at = now()
     WHERE id = p_row_id;
  END IF;

  -- Audit only when stock actually moved (adjusting an already-empty row to
  -- ≤ 0 soft-deletes it but must not create a zero-quantity audit row).
  IF v_applied <> 0 THEN
    INSERT INTO warehouse_movements
      (organisation_id, movement_type, reference_type, reference_id, item_id,
       source_bin_id, destination_bin_id, quantity, operator_id, device, remarks)
    VALUES
      (v_org, 'adjust', 'adjustment', p_row_id::TEXT, v_item,
       CASE WHEN v_applied < 0 THEN v_bin ELSE NULL END,
       CASE WHEN v_applied > 0 THEN v_bin ELSE NULL END,
       v_applied, p_operator_id, p_device,
       COALESCE(p_remarks, 'Quantity adjustment (Movement Engine)'));
  END IF;

  RETURN jsonb_build_object('ok', true, 'bin_item_id', p_row_id, 'applied_delta', v_applied);
END;

DECLARE
    v_caller_is_admin boolean;
BEGIN
    SELECT (lower(coalesce(role, '')) = 'admin' AND coalesce(lower(status), 'active') = 'active')
    INTO v_caller_is_admin
    FROM public.org_members
    WHERE organisation_id = p_organisation_id
      AND user_id = auth.uid();

    IF v_caller_is_admin IS NOT TRUE THEN
        RAISE EXCEPTION 'Access denied: caller is not an active administrator of organisation %', p_organisation_id;
    END IF;

    IF p_action = 'ADD' THEN
        INSERT INTO public.org_members (organisation_id, user_id, role, status)
        VALUES (p_organisation_id, p_target_user_id, p_role, p_status)
        ON CONFLICT (organisation_id, user_id) 
        DO UPDATE SET role = EXCLUDED.role, status = EXCLUDED.status;
        RETURN jsonb_build_object('success', true, 'action', 'ADD');
    ELSIF p_action = 'UPDATE_ROLE' THEN
        UPDATE public.org_members
        SET role = p_role, status = p_status
        WHERE organisation_id = p_organisation_id AND user_id = p_target_user_id;
        RETURN jsonb_build_object('success', true, 'action', 'UPDATE_ROLE');
    ELSIF p_action = 'REMOVE' THEN
        DELETE FROM public.org_members
        WHERE organisation_id = p_organisation_id AND user_id = p_target_user_id;
        RETURN jsonb_build_object('success', true, 'action', 'REMOVE');
    ELSE
        RAISE EXCEPTION 'Invalid action: %', p_action;
    END IF;
END;

declare
  v_req public.org_access_requests%rowtype;
  v_employee_id uuid;
begin
  select * into v_req
  from public.org_access_requests r
  where r.id = p_request_id
  limit 1;

  if not found then
    raise exception 'Access request not found.';
  end if;

  if lower(v_req.status) <> 'pending' then
    raise exception 'Access request is not pending.';
  end if;

  if not public.is_org_admin(v_req.organisation_id) and not public.has_permission(v_req.organisation_id, 'org.manage_users') then
    raise exception 'Not authorized to approve requests.';
  end if;

  select e.id into v_employee_id
  from public.employees e
  where e.organisation_id = v_req.organisation_id
    and lower(trim(e.email)) = lower(trim(v_req.email))
    and lower(e.status) = 'active'
  limit 1;

  if v_employee_id is null then
    raise exception 'Employee record not found or inactive for this email.';
  end if;

  insert into public.org_members(organisation_id, user_id, role, status, employee_id, role_id)
  values (v_req.organisation_id, v_req.user_id, 'member', 'active', v_employee_id, p_role_id)
  on conflict (organisation_id, user_id)
  do update set
    status = 'active',
    employee_id = excluded.employee_id,
    role_id = excluded.role_id;

  update public.org_access_requests
  set status = 'approved',
      reviewed_by = auth.uid(),
      reviewed_at = now()
  where id = v_req.id;
end;

DECLARE
  v_org UUID; v_status TEXT; v_adjusted INTEGER := 0; v_skipped INTEGER := 0;
  v_row RECORD; v_live_qty NUMERIC; v_existing UUID; v_delta NUMERIC;
BEGIN
  SELECT organisation_id, status INTO v_org, v_status
    FROM warehouse_cycle_count_batches WHERE id = p_batch_id;
  IF v_org IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'Batch not found'); END IF;
  IF NOT EXISTS (SELECT 1 FROM user_organisations uo WHERE uo.organisation_id = v_org AND uo.user_id = auth.uid()) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Not a member of this organisation');
  END IF;
  IF v_status <> 'in_progress' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Only in-progress batches can be approved');
  END IF;
  IF EXISTS (SELECT 1 FROM warehouse_cycle_count_items i
             WHERE i.batch_id = p_batch_id AND i.status = 'pending') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'All lines must be counted before approval');
  END IF;

  FOR v_row IN
    SELECT i.id, i.bin_id, i.item_id, i.expected_qty, i.counted_qty, i.variance, i.status
      FROM warehouse_cycle_count_items i
     WHERE i.batch_id = p_batch_id
       AND i.status <> 'adjusted'
     ORDER BY i.id
  LOOP
    IF v_row.status = 'matched' OR v_row.variance = 0 THEN
      UPDATE warehouse_cycle_count_items SET status = 'adjusted', adjusted_at = now(), adjusted_by = p_operator_id, updated_at = now()
       WHERE id = v_row.id;
      v_skipped := v_skipped + 1;
      CONTINUE;
    END IF;

    -- Live qty currently in the bin for this item (movement-engine source of truth).
    SELECT COALESCE(SUM(quantity), 0) INTO v_live_qty
      FROM warehouse_bin_items
     WHERE bin_id = v_row.bin_id AND item_id IS NOT DISTINCT FROM v_row.item_id AND deleted_at IS NULL;

    -- v_delta = counted − live: if counted 30 but live 20, we must ADD 10.
    v_delta := v_row.counted_qty - v_live_qty;

    IF v_delta = 0 THEN
      UPDATE warehouse_cycle_count_items SET status = 'adjusted', adjusted_at = now(), adjusted_by = p_operator_id, updated_at = now()
       WHERE id = v_row.id;
      v_skipped := v_skipped + 1;
      CONTINUE;
    END IF;

    IF v_delta > 0 THEN
      -- Surplus: upsert the live row to counted qty (movement engine handles capacity).
      SELECT id INTO v_existing
        FROM warehouse_bin_items
       WHERE bin_id = v_row.bin_id AND item_id IS NOT DISTINCT FROM v_row.item_id AND deleted_at IS NULL
       LIMIT 1;
      IF v_existing IS NULL THEN
        INSERT INTO warehouse_bin_items
          (organisation_id, bin_id, item_id, quantity, created_by, updated_by)
        VALUES (v_org, v_row.bin_id, v_row.item_id, v_row.counted_qty, p_operator_id, p_operator_id);
      ELSE
        UPDATE warehouse_bin_items
           SET quantity = v_row.counted_qty, updated_by = p_operator_id, updated_at = now()
         WHERE id = v_existing;
      END IF;
      INSERT INTO warehouse_movements
        (organisation_id, movement_type, reference_type, reference_id, item_id,
         destination_bin_id, quantity, operator_id, device, remarks)
      VALUES
        (v_org, 'adjust', 'cycle_count', p_batch_id::TEXT, v_row.item_id,
         v_row.bin_id, v_delta, p_operator_id, 'web',
         'Cycle count surplus correction (' || p_batch_id || ')');
    ELSE
      -- Shortage: decrement the live row, soft-delete when it crosses zero.
      UPDATE warehouse_bin_items
         SET quantity = GREATEST(0, quantity + v_delta),
             updated_by = p_operator_id, updated_at = now(),
             deleted_at = CASE WHEN quantity + v_delta <= 0 THEN now() ELSE deleted_at END
       WHERE bin_id = v_row.bin_id AND item_id IS NOT DISTINCT FROM v_row.item_id AND deleted_at IS NULL;
      INSERT INTO warehouse_movements
        (organisation_id, movement_type, reference_type, reference_id, item_id,
         source_bin_id, quantity, operator_id, device, remarks)
      VALUES
        (v_org, 'adjust', 'cycle_count', p_batch_id::TEXT, v_row.item_id,
         v_row.bin_id, v_delta, p_operator_id, 'web',
         'Cycle count shortage correction (' || p_batch_id || ')');
    END IF;

    UPDATE warehouse_cycle_count_items SET status = 'adjusted', adjusted_at = now(), adjusted_by = p_operator_id, updated_at = now()
     WHERE id = v_row.id;
    v_adjusted := v_adjusted + 1;
  END LOOP;

  UPDATE warehouse_cycle_count_batches
     SET status = 'completed', completed_at = now(), completed_by = p_operator_id,
         approval_status = 'approved', approved_at = now(), approved_by = p_operator_id,
         variance_count = 0, updated_at = now()
   WHERE id = p_batch_id;

  -- Unfreeze the counted bins.
  UPDATE warehouse_bins SET status = 'available', updated_at = now()
   WHERE id IN (SELECT DISTINCT bi.bin_id FROM warehouse_cycle_count_items bi WHERE bi.batch_id = p_batch_id)
     AND status = 'cycle_count';

  RETURN jsonb_build_object('ok', true, 'adjusted', v_adjusted, 'matched', v_skipped);
END;

DECLARE
  v_sheet RECORD;
  v_wo RECORD;
  v_next_amendment_no INT := 1;
  v_amendment_id UUID := NULL;
  v_prev_wo_amount NUMERIC(15,2);
  v_new_wo_amount NUMERIC(15,2);
BEGIN
  SELECT * INTO v_sheet
  FROM public.subcontractor_measurement_sheets
  WHERE id = p_sheet_id
  FOR UPDATE;

  IF v_sheet IS NULL THEN
    RAISE EXCEPTION 'Measurement sheet not found';
  END IF;

  IF auth.uid() IS NOT NULL AND NOT public.user_can_access_org(v_sheet.organisation_id) THEN
    RAISE EXCEPTION 'Unauthorized organization access';
  END IF;

  IF v_sheet.status = 'Approved' THEN
    RETURN jsonb_build_object(
      'status', 'success',
      'already_approved', true,
      'sheet_id', p_sheet_id,
      'amendment_id', v_sheet.amendment_id
    );
  END IF;

  IF v_sheet.status = 'Cancelled' THEN
    RAISE EXCEPTION 'Cannot approve a cancelled measurement sheet';
  END IF;

  SELECT * INTO v_wo
  FROM public.subcontractor_work_orders
  WHERE id = v_sheet.work_order_id
  FOR UPDATE;

  IF v_wo IS NULL THEN
    RAISE EXCEPTION 'Work order not found for measurement sheet';
  END IF;

  v_prev_wo_amount := COALESCE(v_wo.total_amount, 0);

  IF v_sheet.difference > 0 THEN
    SELECT COALESCE(MAX(amendment_no), 0) + 1 INTO v_next_amendment_no
    FROM public.subcontractor_work_order_amendments
    WHERE work_order_id = v_sheet.work_order_id;

    v_new_wo_amount := v_prev_wo_amount + v_sheet.difference;

    INSERT INTO public.subcontractor_work_order_amendments (
      organisation_id, work_order_id, amendment_no, previous_amount,
      new_amount, difference_amount, reason, status, approved_by, approved_at, idempotency_key
    ) VALUES (
      v_sheet.organisation_id, v_sheet.work_order_id, v_next_amendment_no,
      v_prev_wo_amount, v_new_wo_amount, v_sheet.difference,
      COALESCE(p_reason, 'Measurement Sheet ' || v_sheet.sheet_no || ': Actual work exceeded contract quantity'),
      'Approved', COALESCE(auth.uid(), v_sheet.created_by), NOW(), p_idempotency_key
    ) RETURNING id INTO v_amendment_id;

    PERFORM set_config('app.allow_financial_mutation', 'true', true);
    UPDATE public.subcontractor_work_orders
    SET total_amount = v_new_wo_amount,
        updated_at = NOW()
    WHERE id = v_sheet.work_order_id;
    PERFORM set_config('app.allow_financial_mutation', 'false', true);
  ELSE
    v_new_wo_amount := v_prev_wo_amount;
  END IF;

  UPDATE public.subcontractor_measurement_sheets
  SET status = 'Approved',
      approved_by = COALESCE(auth.uid(), v_sheet.created_by),
      approved_at = NOW(),
      amendment_created = (v_amendment_id IS NOT NULL),
      amendment_id = v_amendment_id,
      updated_at = NOW()
  WHERE id = p_sheet_id;

  UPDATE public.subcontractor_work_orders
  SET total_measurements_count = COALESCE(total_measurements_count, 0) + 1,
      updated_at = NOW()
  WHERE id = v_sheet.work_order_id;

  RETURN jsonb_build_object(
    'status', 'success',
    'sheet_id', p_sheet_id,
    'sheet_no', v_sheet.sheet_no,
    'doc_status', 'Approved',
    'amendment_id', v_amendment_id,
    'work_order_id', v_sheet.work_order_id,
    'previous_wo_amount', v_prev_wo_amount,
    'new_wo_amount', v_new_wo_amount,
    'difference', v_sheet.difference
  );
END;

DECLARE
  v_po RECORD;
BEGIN
  SELECT * INTO v_po
  FROM public.purchase_orders
  WHERE id = p_po_id
  FOR UPDATE;

  IF v_po.id IS NULL THEN RAISE EXCEPTION 'Purchase order not found'; END IF;

  IF auth.uid() IS NOT NULL AND NOT public.user_can_access_org(v_po.organisation_id) THEN
    RAISE EXCEPTION 'Unauthorized organization access';
  END IF;

  IF LOWER(COALESCE(v_po.approval_status, '')) = 'approved' THEN
    RETURN jsonb_build_object('status', 'success', 'already_approved', true, 'po_id', p_po_id);
  END IF;

  PERFORM set_config('app.allow_purchase_order_mutation', 'true', true);

  UPDATE public.purchase_orders
  SET approval_status = 'Approved',
      approved_by = auth.uid(),
      approved_at = NOW(),
      status = CASE WHEN status = 'Draft' THEN 'Open' ELSE status END,
      updated_at = NOW()
  WHERE id = p_po_id;

  PERFORM set_config('app.allow_purchase_order_mutation', 'false', true);

  RETURN jsonb_build_object('status', 'success', 'po_id', p_po_id, 'doc_status', 'Approved');
END;

DECLARE
  v_org_id uuid;
  v_line record;
  v_available numeric;
BEGIN
  SELECT organisation_id INTO v_org_id
  FROM public.purchase_requisitions
  WHERE id = p_requisition_id;

  IF v_org_id IS NULL THEN
    RAISE EXCEPTION 'Requisition not found';
  END IF;

  IF auth.uid() IS NOT NULL AND NOT public.user_can_access_org(v_org_id) THEN
    RAISE EXCEPTION 'Unauthorized organization access';
  END IF;

  FOR v_line IN
    SELECT id, item_id, requested_qty
    FROM public.purchase_requisition_lines
    WHERE requisition_id = p_requisition_id
    ORDER BY line_no
  LOOP
    SELECT COALESCE(i.quantity, 0) INTO v_available
    FROM public.inventory i
    WHERE i.organisation_id = v_org_id
      AND i.item_id = v_line.item_id
    LIMIT 1;

    UPDATE public.purchase_requisition_lines
    SET
      available_stock_qty = COALESCE(v_available, 0),
      store_allocated_qty = 0,
      procure_required_qty = COALESCE(v_line.requested_qty, 0),
      source_type = 'PROCURE',
      open_qty = COALESCE(v_line.requested_qty, 0),
      status = 'Open'
    WHERE id = v_line.id;
  END LOOP;

  UPDATE public.purchase_requisitions
  SET status = 'Approved'
  WHERE id = p_requisition_id;
END;

DECLARE
  v_quote RECORD;
BEGIN
  SELECT * INTO v_quote
  FROM public.quotation_header
  WHERE id = p_quotation_id
  FOR UPDATE;

  IF v_quote.id IS NULL THEN
    RAISE EXCEPTION 'Quotation not found';
  END IF;

  IF auth.uid() IS NOT NULL AND NOT public.user_can_access_org(v_quote.organisation_id) THEN
    RAISE EXCEPTION 'Unauthorized organization access';
  END IF;

  IF LOWER(COALESCE(v_quote.status, '')) = 'approved' THEN
    RETURN jsonb_build_object('status', 'success', 'already_approved', true, 'quotation_id', p_quotation_id, 'quotation_no', v_quote.quotation_no);
  END IF;

  IF LOWER(COALESCE(v_quote.status, '')) IN ('cancelled', 'rejected') THEN
    RAISE EXCEPTION 'Cannot approve a cancelled or rejected quotation (Status: %)', v_quote.status;
  END IF;

  UPDATE public.quotation_header
  SET status = 'Approved',
      approval_status = 'Approved',
      approval_completed_at = NOW(),
      updated_at = NOW()
  WHERE id = p_quotation_id;

  RETURN jsonb_build_object(
    'status', 'success',
    'quotation_id', p_quotation_id,
    'quotation_no', v_quote.quotation_no,
    'doc_status', 'Approved'
  );
END;

DECLARE
  v_max NUMERIC;
  v_old NUMERIC;
  v_delta NUMERIC;
  v_row_id UUID;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM user_organisations
     WHERE organisation_id = p_organisation_id AND user_id = auth.uid() AND status = 'active'
  ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Not a member of this organisation');
  END IF;
  IF p_quantity < 0 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Quantity cannot be negative');
  END IF;

  -- Bin must belong to the caller's org. (max_quantity may be NULL — uncapped
  -- — so existence is checked separately.)
  SELECT max_quantity INTO v_max
    FROM warehouse_bins
   WHERE id = p_bin_id AND organisation_id = p_organisation_id AND deleted_at IS NULL;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Bin not found in this organisation');
  END IF;

  -- Old live quantity for this (bin, item) — single source of truth.
  SELECT COALESCE(SUM(quantity), 0) INTO v_old
    FROM warehouse_bin_items
   WHERE bin_id = p_bin_id AND item_id IS NOT DISTINCT FROM p_item_id AND deleted_at IS NULL;

  v_delta := p_quantity - v_old;

  -- Capacity on increases only (TAD §5.10).
  IF v_delta > 0 AND COALESCE(v_max, 0) > 0 AND v_old + v_delta > v_max THEN
    RETURN jsonb_build_object('ok', false, 'error',
      'Bin capacity exceeded: ' || v_old || ' + ' || v_delta || ' > ' || v_max);
  END IF;

  -- Upsert (revives soft-deleted rows, like receive_warehouse_stock).
  INSERT INTO warehouse_bin_items
    (organisation_id, bin_id, item_id, quantity, is_primary, is_reserve,
     batch_no, lot_no, created_by, created_at, updated_by, updated_at)
  VALUES
    (p_organisation_id, p_bin_id, p_item_id, p_quantity, p_is_primary, p_is_reserve,
     p_batch_no, p_lot_no, p_operator_id, now(), p_operator_id, now())
  ON CONFLICT (bin_id, item_id)
  DO UPDATE SET quantity = EXCLUDED.quantity,
                is_primary = EXCLUDED.is_primary,
                is_reserve = EXCLUDED.is_reserve,
                batch_no = EXCLUDED.batch_no,
                lot_no = EXCLUDED.lot_no,
                deleted_at = NULL,
                updated_by = p_operator_id,
                updated_at = now()
  RETURNING id INTO v_row_id;

  -- Audit row only when stock actually changed (flag-only updates are not a
  -- movement). Sign-encoded for TAD §5.12 reversal compatibility.
  IF v_delta <> 0 THEN
    INSERT INTO warehouse_movements
      (organisation_id, movement_type, reference_type, reference_id, item_id,
       source_bin_id, destination_bin_id, quantity, operator_id, device, remarks)
    VALUES
      (p_organisation_id, 'adjust', 'adjustment', v_row_id::TEXT, p_item_id,
       CASE WHEN v_delta < 0 THEN p_bin_id ELSE NULL END,
       CASE WHEN v_delta > 0 THEN p_bin_id ELSE NULL END,
       v_delta, p_operator_id, p_device,
       COALESCE(p_remarks, 'Inventory assignment (Movement Engine)'));
  END IF;

  RETURN jsonb_build_object('ok', true, 'bin_item_id', v_row_id, 'delta', v_delta);
END;

DECLARE
  changes_json JSONB := '{}'::jsonb;
BEGIN
  IF TG_OP = 'UPDATE' THEN
    IF COALESCE(OLD.subject, '') <> COALESCE(NEW.subject, '') THEN
      changes_json := jsonb_set(changes_json, array['subject'], jsonb_build_object('old', OLD.subject, 'new', NEW.subject));
    END IF;

    IF COALESCE(OLD.call_brief, '') <> COALESCE(NEW.call_brief, '') THEN
      changes_json := jsonb_set(changes_json, array['call_brief'], jsonb_build_object('old', OLD.call_brief, 'new', NEW.call_brief));
    END IF;

    IF COALESCE(OLD.next_action, '') <> COALESCE(NEW.next_action, '') THEN
      changes_json := jsonb_set(changes_json, array['next_action'], jsonb_build_object('old', OLD.next_action, 'new', NEW.next_action));
    END IF;

    IF OLD.follow_up_date IS DISTINCT FROM NEW.follow_up_date THEN
      changes_json := jsonb_set(changes_json, array['follow_up_date'], jsonb_build_object('old', OLD.follow_up_date, 'new', NEW.follow_up_date));
    END IF;

    IF OLD.priority IS DISTINCT FROM NEW.priority THEN
      changes_json := jsonb_set(changes_json, array['priority'], jsonb_build_object('old', OLD.priority, 'new', NEW.priority));
    END IF;

    IF OLD.status IS DISTINCT FROM NEW.status THEN
      changes_json := jsonb_set(changes_json, array['status'], jsonb_build_object('old', OLD.status, 'new', NEW.status));
    END IF;

    IF OLD.call_category IS DISTINCT FROM NEW.call_category THEN
      changes_json := jsonb_set(changes_json, array['call_category'], jsonb_build_object('old', OLD.call_category, 'new', NEW.call_category));
    END IF;

    IF OLD.call_regarding IS DISTINCT FROM NEW.call_regarding THEN
      changes_json := jsonb_set(changes_json, array['call_regarding'], jsonb_build_object('old', OLD.call_regarding, 'new', NEW.call_regarding));
    END IF;

    IF changes_json <> '{}'::jsonb THEN
      INSERT INTO audit_log (
        organisation_id,
        user_id,
        action,
        entity_type,
        entity_id,
        changes,
        created_at
      ) VALUES (
        NEW.organisation_id,
        COALESCE(auth.uid(), NEW.assigned_to),
        'UPDATE',
        'client_communication',
        NEW.id,
        changes_json,
        now()
      );
    END IF;
  END IF;

  RETURN NEW;
END;

DECLARE
  v_so_item_id UUID;
  v_item_id UUID;
  v_org_id UUID;
  v_ordered_qty DECIMAL(12,3);
  v_reserved_qty DECIMAL(12,3);
  v_to_reserve DECIMAL(12,3);
  v_fg_wh_id UUID;
BEGIN
  -- 1. Check if production entry corresponds to a job card linked to a sales order item
  SELECT sales_order_item_id, organisation_id
  INTO v_so_item_id, v_org_id
  FROM job_cards
  WHERE id = NEW.job_card_id;

  IF v_so_item_id IS NULL THEN
    RETURN NEW;
  END IF;

  -- 2. Fetch sales order item details
  SELECT item_id, qty, reserved_qty
  INTO v_item_id, v_ordered_qty, v_reserved_qty
  FROM sales_order_items
  WHERE id = v_so_item_id;

  -- 3. Calculate reservation amount with overshoot cap
  v_to_reserve := LEAST(NEW.actual_qty, v_ordered_qty - v_reserved_qty);

  IF v_to_reserve > 0 THEN
    -- Get FG Warehouse for this organization
    SELECT id INTO v_fg_wh_id 
    FROM warehouses 
    WHERE organisation_id = v_org_id 
    AND warehouse_purpose = 'fg' 
    LIMIT 1;

    -- Fallback: lookup by name/code
    IF v_fg_wh_id IS NULL THEN
      SELECT id INTO v_fg_wh_id 
      FROM warehouses 
      WHERE organisation_id = v_org_id 
      AND (warehouse_code = 'FG-001' OR name ILIKE '%Finished%') 
      LIMIT 1;
    END IF;

    -- If warehouse exists, create the reservation row
    IF v_fg_wh_id IS NOT NULL THEN
      INSERT INTO sales_order_reservations (
        sales_order_item_id, item_id, warehouse_id, qty, organisation_id
      ) VALUES (
        v_so_item_id, v_item_id, v_fg_wh_id, v_to_reserve, v_org_id
      );

      -- Update produced_qty in sales_order_items
      UPDATE sales_order_items 
      SET produced_qty = COALESCE(produced_qty, 0) + NEW.actual_qty 
      WHERE id = v_so_item_id;
    END IF;
  END IF;

  RETURN NEW;
END;

DECLARE
  v_itc_data JSONB;
  v_total_itc_available JSONB;
  v_total_itc_utilized JSONB;
  v_itc_carried_forward JSONB;
  v_net_tax_payable JSONB;
  v_result JSONB;
BEGIN
  -- Validate period format
  IF NOT validate_gst_period(p_period_month) THEN
    RAISE EXCEPTION 'Invalid period format. Expected MM/YYYY';
  END IF;

  -- Calculate ITC from invoices (simplified version)
  v_total_itc_available := jsonb_build_object(
    'igst', 0.00,
    'cgst', 0.00,
    'sgst', 0.00,
    'cess', 0.00
  );

  -- Calculate ITC utilization (simplified version)
  v_total_itc_utilized := jsonb_build_object(
    'igst', 0.00,
    'cgst', 0.00,
    'sgst', 0.00,
    'cess', 0.00
  );

  -- Calculate carried forward (simplified version)
  v_itc_carried_forward := jsonb_build_object(
    'igst', 0.00,
    'cgst', 0.00,
    'sgst', 0.00,
    'cess', 0.00
  );

  -- Calculate net tax payable
  v_net_tax_payable := jsonb_build_object(
    'igst', 
    (v_total_itc_available->>'igst')::DECIMAL - (v_total_itc_utilized->>'igst')::DECIMAL,
    'cgst', 
    (v_total_itc_available->>'cgst')::DECIMAL - (v_total_itc_utilized->>'cgst')::DECIMAL,
    'sgst', 
    (v_total_itc_available->>'sgst')::DECIMAL - (v_total_itc_utilized->>'sgst')::DECIMAL,
    'cess', 
    (v_total_itc_available->>'cess')::DECIMAL - (v_total_itc_utilized->>'cess')::DECIMAL
  );

  -- Build complete ITC data structure
  v_itc_data := jsonb_build_object(
    'total_itc_available', v_total_itc_available,
    'itc_utilized', v_total_itc_utilized,
    'itc_carried_forward', v_itc_carried_forward,
    'itc_lapsed', jsonb_build_object('igst', 0.00, 'cgst', 0.00, 'sgst', 0.00, 'cess', 0.00),
    'net_tax_payable', v_net_tax_payable
  );

  -- Upsert ITC summary
  INSERT INTO itc_summaries (
    organisation_id,
    client_id,
    period_month,
    itc_data,
    auto_calculated,
    is_locked
  )
  VALUES (
    p_organisation_id,
    p_client_id,
    p_period_month,
    v_itc_data,
    true,
    false
  )
  ON CONFLICT (organisation_id, client_id, period_month)
  DO UPDATE SET
    itc_data = EXCLUDED.itc_data,
    updated_at = NOW();

  v_result := jsonb_build_object(
    'status', 'success',
    'itc_data', v_itc_data,
    'message', 'ITC summary calculated successfully'
  );

  RETURN v_result;
END;

BEGIN
  -- If percentage is set and no fixed amount, calculate from PO total
  IF NEW.percentage IS NOT NULL AND NEW.fixed_amount IS NULL THEN
    DECLARE
      po_total DECIMAL(15,2);
    BEGIN
      SELECT po_total_value INTO po_total
      FROM client_purchase_orders
      WHERE id = NEW.po_id;
      
      NEW.milestone_amount := (po_total * NEW.percentage) / 100;
    END;
  END IF;
  
  -- Calculate due date if due_days is set
  IF NEW.due_days IS NOT NULL AND NEW.due_date IS NULL THEN
    DECLARE
      base_date DATE;
    BEGIN
      -- Use PO date as base
      SELECT po_date INTO base_date
      FROM client_purchase_orders
      WHERE id = NEW.po_id;
      
      NEW.due_date := base_date + NEW.due_days;
    END;
  END IF;
  
  NEW.updated_at := NOW();
  RETURN NEW;
END;

DECLARE
  v_effective_batch_qty NUMERIC;
  v_op RECORD;
  v_mach_rate NUMERIC;
  v_lab_rate NUMERIC;
  v_setup_mach_cost NUMERIC := 0;
  v_run_mach_cost NUMERIC := 0;
  v_lab_cost NUMERIC := 0;
  v_subcontract_cost NUMERIC := 0;
  v_total_inhouse_op_cost NUMERIC := 0;
  v_total_subcontract_op_cost NUMERIC := 0;
  v_total_op_cost NUMERIC := 0;
  v_op_details JSONB[] := ARRAY[]::JSONB[];
BEGIN
  v_effective_batch_qty := GREATEST(COALESCE(p_batch_qty, 1), 0.0001);

  FOR v_op IN
    SELECT ro.*, wc.machine_rate_per_hour AS wc_mach_rate, wc.labor_rate_per_hour AS wc_lab_rate
    FROM bom_routing_operations ro
    LEFT JOIN work_centers wc ON wc.id = ro.work_center_id
    WHERE ro.bom_id = p_bom_id
    ORDER BY ro.sequence_no ASC
  LOOP
    IF v_op.is_subcontract THEN
      DECLARE
        v_sub_cost NUMERIC := ROUND(COALESCE(v_op.subcontract_rate_per_unit, 0) * v_effective_batch_qty, 2);
      BEGIN
        v_subcontract_cost := v_subcontract_cost + v_sub_cost;
        v_total_subcontract_op_cost := v_total_subcontract_op_cost + v_sub_cost;
        v_op_details := ARRAY_APPEND(v_op_details, jsonb_build_object(
          'id', v_op.id,
          'sequence_no', v_op.sequence_no,
          'operation_name', v_op.operation_name,
          'is_subcontract', true,
          'subcontract_rate_per_unit', v_op.subcontract_rate_per_unit,
          'total_cost', v_sub_cost
        ));
      END;
    ELSE
      v_mach_rate := COALESCE(v_op.machine_rate_per_hour, v_op.wc_mach_rate, 0);
      v_lab_rate  := COALESCE(v_op.labor_rate_per_hour, v_op.wc_lab_rate, 0);

      DECLARE
        v_op_setup_mach NUMERIC := ROUND((COALESCE(v_op.setup_time_minutes, 0) / 60.0) * v_mach_rate, 4);
        v_op_run_mach   NUMERIC := ROUND((COALESCE(v_op.cycle_time_minutes, 0) / 60.0) * v_effective_batch_qty * v_mach_rate, 4);
        v_op_lab        NUMERIC := ROUND(((COALESCE(v_op.setup_time_minutes, 0) + COALESCE(v_op.cycle_time_minutes, 0) * v_effective_batch_qty) / 60.0) * v_lab_rate, 4);
        v_op_total      NUMERIC := ROUND(v_op_setup_mach + v_op_run_mach + v_op_lab, 2);
      BEGIN
        v_setup_mach_cost := v_setup_mach_cost + v_op_setup_mach;
        v_run_mach_cost   := v_run_mach_cost + v_op_run_mach;
        v_lab_cost        := v_lab_cost + v_op_lab;
        v_total_inhouse_op_cost := v_total_inhouse_op_cost + v_op_total;

        v_op_details := ARRAY_APPEND(v_op_details, jsonb_build_object(
          'id', v_op.id,
          'sequence_no', v_op.sequence_no,
          'operation_name', v_op.operation_name,
          'is_subcontract', false,
          'setup_machine_cost', v_op_setup_mach,
          'run_machine_cost', v_op_run_mach,
          'labor_cost', v_op_lab,
          'total_cost', v_op_total
        ));
      END;
    END IF;
  END LOOP;

  v_total_op_cost := v_total_inhouse_op_cost + v_total_subcontract_op_cost;

  RETURN jsonb_build_object(
    'batch_qty', v_effective_batch_qty,
    'setup_machine_cost', ROUND(v_setup_mach_cost, 2),
    'run_machine_cost', ROUND(v_run_mach_cost, 2),
    'total_machine_cost', ROUND(v_setup_mach_cost + v_run_mach_cost, 2),
    'labor_cost', ROUND(v_lab_cost, 2),
    'inhouse_operation_cost', ROUND(v_total_inhouse_op_cost, 2),
    'subcontract_operation_cost', ROUND(v_total_subcontract_op_cost, 2),
    'total_operation_cost', ROUND(v_total_op_cost, 2),
    'operations', to_jsonb(v_op_details)
  );
END;

BEGIN
  IF NEW.shipped_qty >= NEW.qty THEN
    NEW.status := 'shipped';
  ELSIF NEW.shipped_qty > 0 THEN
    NEW.status := 'partially_shipped';
  ELSIF NEW.reserved_qty >= NEW.qty THEN
    NEW.status := 'reserved';
  ELSIF NEW.produced_qty >= NEW.qty THEN
    NEW.status := 'ready_to_ship';
  ELSIF NEW.produced_qty > 0 THEN
    NEW.status := 'in_production';
  ELSE
    NEW.status := 'pending';
  END IF;

  RETURN NEW;
END;

BEGIN
  IF NEW.warranty_start_date IS NOT NULL AND NEW.warranty_duration_months IS NOT NULL THEN
    NEW.warranty_end_date := NEW.warranty_start_date + (NEW.warranty_duration_months * INTERVAL '1 month');
  END IF;
  RETURN NEW;
END;

DECLARE
  outstanding DECIMAL(15,2);
BEGIN
  SELECT COALESCE(SUM(pi.total_amount), 0) - COALESCE(SUM(pp.payment_amount), 0)
  INTO outstanding
  FROM project_invoices pi
  LEFT JOIN project_payments pp ON pp.project_id = pi.project_id
  WHERE pi.project_id = p_id;

  IF outstanding > 0 THEN
    RETURN FALSE;
  END IF;
  
  RETURN TRUE;
END;

DECLARE
  po_count INTEGER;
  invoice_count INTEGER;
  expense_count INTEGER;
  payment_count INTEGER;
BEGIN
  SELECT COUNT(*) INTO po_count FROM client_purchase_orders WHERE project_id = p_id;
  SELECT COUNT(*) INTO invoice_count FROM project_invoices WHERE project_id = p_id;
  SELECT COUNT(*) INTO expense_count FROM project_expenses WHERE project_id = p_id;
  SELECT COUNT(*) INTO payment_count FROM project_payments WHERE project_id = p_id;

  IF po_count > 0 OR invoice_count > 0 OR expense_count > 0 OR payment_count > 0 THEN
    RETURN FALSE;
  END IF;
  
  RETURN TRUE;
END;

DECLARE
  v_ae RECORD;
  v_float RECORD;
  v_expense_account_id UUID;
  v_advance_account_id UUID;
  v_bank_account_id UUID;
  v_petty_cash_account_id UUID;
  v_rev_journal_id UUID := NULL;
  v_creator_id UUID;
BEGIN
  SELECT * INTO v_ae
  FROM public.advances_expenses
  WHERE id = p_ae_id
  FOR UPDATE;

  IF v_ae.id IS NULL THEN
    RAISE EXCEPTION 'Advance/Expense record not found';
  END IF;

  IF auth.uid() IS NOT NULL AND NOT public.user_can_access_org(v_ae.organisation_id) THEN
    RAISE EXCEPTION 'Unauthorized organization access';
  END IF;

  IF v_ae.status = 'CANCELLED' THEN
    RETURN jsonb_build_object(
      'status', 'success',
      'already_cancelled', true,
      'ae_id', p_ae_id,
      'transaction_no', v_ae.transaction_no
    );
  END IF;

  SELECT id INTO v_creator_id
  FROM public.user_profiles WHERE user_id = auth.uid() OR id = auth.uid() LIMIT 1;

  -- If paid and float was used: restore float balance!
  IF v_ae.status = 'PAID' AND v_ae.float_id IS NOT NULL THEN
    SELECT * INTO v_float
    FROM public.petty_cash_floats
    WHERE id = v_ae.float_id
    FOR UPDATE;

    IF v_float.id IS NOT NULL THEN
      UPDATE public.petty_cash_floats
      SET current_balance = current_balance + v_ae.amount,
          updated_at = NOW()
      WHERE id = v_ae.float_id;
    END IF;
  END IF;

  -- If paid, post reversing GL journal entry
  IF v_ae.status = 'PAID' AND v_ae.amount > 0 THEN
    v_bank_account_id := public.ensure_gl_account_exists(v_ae.organisation_id, '1200', 'Bank Account - Primary', 'Asset');
    v_petty_cash_account_id := public.ensure_gl_account_exists(v_ae.organisation_id, '1301', 'Petty Cash Float', 'Asset');
    v_advance_account_id := public.ensure_gl_account_exists(v_ae.organisation_id, '1400', 'Employee Advances', 'Asset');
    v_expense_account_id := public.ensure_gl_account_exists(v_ae.organisation_id, '4100', 'Operational Expenses', 'Expense');

    INSERT INTO public.journal_entries (
      company_id, voucher_no, voucher_date, voucher_type, narration, status, created_by
    ) VALUES (
      v_ae.organisation_id, 'REV-' || v_ae.transaction_no, CURRENT_DATE, 'Payment'::public.voucher_type,
      'Reversal of ' || v_ae.type || ' ' || v_ae.transaction_no || COALESCE(' (' || p_reason || ')', ''),
      'Posted', v_creator_id
    ) RETURNING id INTO v_rev_journal_id;

    IF v_ae.float_id IS NOT NULL THEN
      INSERT INTO public.journal_entry_lines (journal_id, account_id, party_type, party_id, debit, credit, narration)
      VALUES (v_rev_journal_id, v_petty_cash_account_id, 'employee', v_ae.employee_id, v_ae.amount, 0.00, 'Reversal of Petty Cash Outflow');
    ELSE
      INSERT INTO public.journal_entry_lines (journal_id, account_id, party_type, party_id, debit, credit, narration)
      VALUES (v_rev_journal_id, v_bank_account_id, 'employee', v_ae.employee_id, v_ae.amount, 0.00, 'Reversal of Bank Disbursement');
    END IF;

    IF v_ae.type = 'ADVANCE' THEN
      INSERT INTO public.journal_entry_lines (journal_id, account_id, party_type, party_id, debit, credit, narration)
      VALUES (v_rev_journal_id, v_advance_account_id, 'employee', v_ae.employee_id, 0.00, v_ae.amount, 'Reversal of Employee Advance');
    ELSE
      INSERT INTO public.journal_entry_lines (journal_id, account_id, party_type, party_id, debit, credit, narration)
      VALUES (v_rev_journal_id, v_expense_account_id, 'employee', v_ae.employee_id, 0.00, v_ae.amount, 'Reversal of Expense Settlement');
    END IF;
  END IF;

  PERFORM set_config('app.allow_financial_mutation', 'true', true);
  UPDATE public.advances_expenses
  SET status = 'CANCELLED',
      cancellation_reason = p_reason,
      updated_at = NOW()
  WHERE id = p_ae_id;
  PERFORM set_config('app.allow_financial_mutation', 'false', true);

  RETURN jsonb_build_object(
    'status', 'success',
    'ae_id', p_ae_id,
    'transaction_no', v_ae.transaction_no,
    'doc_status', 'CANCELLED',
    'rev_journal_id', v_rev_journal_id
  );
END;

DECLARE
  v_cn RECORD;
  v_ar_account_id UUID;
  v_sales_return_account_id UUID;
  v_journal_id UUID;
BEGIN
  SELECT * INTO v_cn
  FROM public.credit_notes
  WHERE id = p_cn_id
  FOR UPDATE;

  IF v_cn.id IS NULL THEN RAISE EXCEPTION 'Credit note not found'; END IF;

  IF auth.uid() IS NOT NULL AND NOT public.user_can_access_org(v_cn.organisation_id) THEN
    RAISE EXCEPTION 'Unauthorized organization access';
  END IF;

  IF LOWER(COALESCE(v_cn.approval_status, '')) = 'cancelled' THEN
    RETURN jsonb_build_object(
      'status', 'success',
      'already_cancelled', true,
      'cn_id', p_cn_id,
      'cn_number', v_cn.cn_number
    );
  END IF;

  -- Post Reversing GL Entry (Dr Accounts Receivable, Cr Sales Returns)
  SELECT id INTO v_ar_account_id FROM public.accounts WHERE (organisation_id = v_cn.organisation_id OR company_id = v_cn.organisation_id) AND account_code = '1100' LIMIT 1;
  SELECT id INTO v_sales_return_account_id FROM public.accounts WHERE (organisation_id = v_cn.organisation_id OR company_id = v_cn.organisation_id) AND (account_code IN ('4100', '5100', '4000') OR name ILIKE '%Sales Return%' OR name ILIKE '%Revenue%') LIMIT 1;

  IF v_ar_account_id IS NOT NULL AND v_sales_return_account_id IS NOT NULL AND v_cn.total_amount > 0 THEN
    INSERT INTO public.journal_entries (
      company_id, voucher_no, voucher_date, voucher_type,
      narration, status, created_by
    ) VALUES (
      v_cn.organisation_id,
      'REV-' || COALESCE(v_cn.cn_number, v_cn.id::TEXT),
      CURRENT_DATE,
      'Credit Note',
      'Reversal of Credit Note ' || COALESCE(v_cn.cn_number, '') || COALESCE(' (' || p_reason || ')', ''),
      'Posted',
      auth.uid()
    ) RETURNING id INTO v_journal_id;

    INSERT INTO public.journal_entry_lines (journal_id, account_id, party_type, party_id, debit, credit, narration)
    VALUES (v_journal_id, v_ar_account_id, 'client', v_cn.client_id, v_cn.total_amount, 0.00, 'Reversal of CN AR Reduction');

    INSERT INTO public.journal_entry_lines (journal_id, account_id, party_type, party_id, debit, credit, narration)
    VALUES (v_journal_id, v_sales_return_account_id, 'client', v_cn.client_id, 0.00, v_cn.total_amount, 'Reversal of Sales Returns');
  END IF;

  UPDATE public.credit_notes
  SET approval_status = 'Cancelled',
      reason = COALESCE(reason || ' | ', '') || 'Cancelled: ' || COALESCE(p_reason, 'No reason provided'),
      updated_at = NOW()
  WHERE id = p_cn_id;

  RETURN jsonb_build_object(
    'status', 'success',
    'cn_id', p_cn_id,
    'cn_number', v_cn.cn_number,
    'doc_status', 'cancelled',
    'journal_id', v_journal_id
  );
END;

DECLARE
  v_receipt RECORD;
  v_bank_account_id UUID;
  v_ar_account_id UUID;
  v_journal_id UUID;
BEGIN
  SELECT * INTO v_receipt
  FROM public.receipts
  WHERE id = p_receipt_id
  FOR UPDATE;

  IF v_receipt.id IS NULL THEN RAISE EXCEPTION 'Receipt not found'; END IF;

  IF auth.uid() IS NOT NULL AND NOT public.user_can_access_org(v_receipt.org_id) THEN
    RAISE EXCEPTION 'Unauthorized organization access';
  END IF;

  IF LOWER(COALESCE(v_receipt.status, '')) = 'cancelled' THEN
    RETURN jsonb_build_object(
      'status', 'success',
      'already_cancelled', true,
      'receipt_id', p_receipt_id,
      'receipt_no', v_receipt.receipt_no
    );
  END IF;

  -- Post Reversing GL Journal Entry (Dr Accounts Receivable, Cr Bank/Cash)
  IF LOWER(TRIM(COALESCE(v_receipt.payment_mode, ''))) = 'cash' THEN
    SELECT id INTO v_bank_account_id
    FROM public.accounts
    WHERE (organisation_id = v_receipt.org_id OR company_id = v_receipt.org_id)
      AND account_code = '1300'
    LIMIT 1;
  END IF;

  IF v_bank_account_id IS NULL THEN
    SELECT id INTO v_bank_account_id
    FROM public.accounts
    WHERE (organisation_id = v_receipt.org_id OR company_id = v_receipt.org_id)
      AND account_code = '1200'
    LIMIT 1;
  END IF;

  SELECT id INTO v_ar_account_id
  FROM public.accounts
  WHERE (organisation_id = v_receipt.org_id OR company_id = v_receipt.org_id)
    AND account_code = '1100'
  LIMIT 1;

  IF v_bank_account_id IS NOT NULL AND v_ar_account_id IS NOT NULL AND v_receipt.amount > 0 THEN
    INSERT INTO public.journal_entries (
      company_id, voucher_no, voucher_date, voucher_type,
      narration, status, created_by
    ) VALUES (
      v_receipt.org_id,
      'REV-' || COALESCE(v_receipt.receipt_no, v_receipt.id::TEXT),
      CURRENT_DATE,
      'Receipt',
      'Reversal of Receipt ' || COALESCE(v_receipt.receipt_no, '') || COALESCE(' (' || p_reason || ')', ''),
      'Posted',
      auth.uid()
    ) RETURNING id INTO v_journal_id;

    INSERT INTO public.journal_entry_lines (
      journal_id, account_id, party_type, party_id, debit, credit, narration
    ) VALUES (
      v_journal_id, v_ar_account_id, 'client', v_receipt.client_id, v_receipt.amount, 0.00, 'Reversal of AR Settlement'
    );

    INSERT INTO public.journal_entry_lines (
      journal_id, account_id, party_type, party_id, debit, credit, narration
    ) VALUES (
      v_journal_id, v_bank_account_id, 'client', v_receipt.client_id, 0.00, v_receipt.amount, 'Reversal of Bank/Cash Receipt'
    );
  END IF;

  -- Update receipt status (Trigger fn_update_invoice_paid_amount automatically syncs invoices.paid_amount)
  UPDATE public.receipts
  SET status = 'cancelled',
      notes = COALESCE(notes || ' | ', '') || 'Cancelled: ' || COALESCE(p_reason, 'No reason provided')
  WHERE id = p_receipt_id;

  RETURN jsonb_build_object(
    'status', 'success',
    'receipt_id', p_receipt_id,
    'receipt_no', v_receipt.receipt_no,
    'doc_status', 'cancelled',
    'journal_id', v_journal_id
  );
END;

DECLARE v_org UUID; v_status TEXT;
BEGIN
  SELECT organisation_id, status INTO v_org, v_status
    FROM warehouse_cycle_count_batches WHERE id = p_batch_id;
  IF v_org IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'Batch not found'); END IF;
  IF NOT EXISTS (SELECT 1 FROM user_organisations uo WHERE uo.organisation_id = v_org AND uo.user_id = auth.uid()) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Not a member of this organisation');
  END IF;
  IF v_status = 'completed' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Completed batches cannot be cancelled');
  END IF;
  UPDATE warehouse_cycle_count_batches
     SET status = 'cancelled', updated_at = now()
   WHERE id = p_batch_id;
  UPDATE warehouse_bins SET status = 'available', updated_at = now()
   WHERE id IN (SELECT DISTINCT bi.bin_id FROM warehouse_cycle_count_items bi WHERE bi.batch_id = p_batch_id)
     AND status = 'cycle_count';
  RETURN jsonb_build_object('ok', true);
END;

DECLARE
  v_dn RECORD;
  v_ap_account_id UUID;
  v_purchase_return_account_id UUID;
  v_journal_id UUID;
BEGIN
  SELECT * INTO v_dn
  FROM public.debit_notes
  WHERE id = p_dn_id
  FOR UPDATE;

  IF v_dn.id IS NULL THEN RAISE EXCEPTION 'Debit note not found'; END IF;

  IF auth.uid() IS NOT NULL AND NOT public.user_can_access_org(v_dn.organisation_id) THEN
    RAISE EXCEPTION 'Unauthorized organization access';
  END IF;

  IF LOWER(COALESCE(v_dn.approval_status, '')) = 'cancelled' THEN
    RETURN jsonb_build_object(
      'status', 'success',
      'already_cancelled', true,
      'dn_id', p_dn_id,
      'dn_number', v_dn.dn_number
    );
  END IF;

  -- Post Reversing GL Entry (Dr Purchase Returns, Cr Accounts Payable)
  SELECT id INTO v_ap_account_id FROM public.accounts WHERE (organisation_id = v_dn.organisation_id OR company_id = v_dn.organisation_id) AND account_code = '2100' LIMIT 1;
  SELECT id INTO v_purchase_return_account_id FROM public.accounts WHERE (organisation_id = v_dn.organisation_id OR company_id = v_dn.organisation_id) AND (account_code IN ('5000', '1500', '2000') OR name ILIKE '%Purchase Return%' OR name ILIKE '%Inventory%') LIMIT 1;

  IF v_ap_account_id IS NOT NULL AND v_purchase_return_account_id IS NOT NULL AND v_dn.total_amount > 0 THEN
    INSERT INTO public.journal_entries (
      company_id, voucher_no, voucher_date, voucher_type,
      narration, status, created_by
    ) VALUES (
      v_dn.organisation_id,
      'REV-' || COALESCE(v_dn.dn_number, v_dn.id::TEXT),
      CURRENT_DATE,
      'Debit Note',
      'Reversal of Debit Note ' || COALESCE(v_dn.dn_number, '') || COALESCE(' (' || p_reason || ')', ''),
      'Posted',
      auth.uid()
    ) RETURNING id INTO v_journal_id;

    INSERT INTO public.journal_entry_lines (journal_id, account_id, party_type, party_id, debit, credit, narration)
    VALUES (v_journal_id, v_purchase_return_account_id, 'vendor', v_dn.vendor_id, v_dn.total_amount, 0.00, 'Reversal of Purchase Returns');

    INSERT INTO public.journal_entry_lines (journal_id, account_id, party_type, party_id, debit, credit, narration)
    VALUES (v_journal_id, v_ap_account_id, 'vendor', v_dn.vendor_id, 0.00, v_dn.total_amount, 'Reversal of AP Reduction');
  END IF;

  UPDATE public.debit_notes
  SET approval_status = 'Cancelled',
      reason = COALESCE(reason || ' | ', '') || 'Cancelled: ' || COALESCE(p_reason, 'No reason provided'),
      updated_at = NOW()
  WHERE id = p_dn_id;

  PERFORM public.recalc_vendor_balance(v_dn.vendor_id, v_dn.organisation_id);

  RETURN jsonb_build_object(
    'status', 'success',
    'dn_id', p_dn_id,
    'dn_number', v_dn.dn_number,
    'doc_status', 'cancelled',
    'journal_id', v_journal_id
  );
END;

DECLARE
  v_dc RECORD;
  v_org_id UUID;
  v_user_id UUID;
  r_item RECORD;
  v_stock_id UUID;
  v_current_stock NUMERIC;
BEGIN
  v_user_id := auth.uid();

  SELECT * INTO v_dc
  FROM public.delivery_challans
  WHERE id = p_dc_id
  FOR UPDATE;

  IF v_dc.id IS NULL THEN
    RAISE EXCEPTION 'Delivery Challan not found';
  END IF;

  v_org_id := v_dc.organisation_id;
  IF v_user_id IS NOT NULL AND NOT public.user_can_access_org(v_org_id) THEN
    RAISE EXCEPTION 'Unauthorized organization access';
  END IF;

  IF UPPER(COALESCE(v_dc.status, '')) = 'CANCELLED' THEN
    RETURN jsonb_build_object('status', 'success', 'already_processed', true, 'dc_id', p_dc_id);
  END IF;

  -- Check if active invoices are linked to this DC
  IF EXISTS (
    SELECT 1 FROM public.invoices 
    WHERE ((source_type IN ('dc', 'challan', 'delivery_challan') AND source_id = p_dc_id) OR id = v_dc.converted_to_id)
      AND LOWER(COALESCE(status, '')) != 'cancelled'
  ) THEN
    RAISE EXCEPTION 'Cannot cancel Delivery Challan % with active linked Sales Invoice. Cancel the invoice first.', v_dc.dc_number;
  END IF;

  -- Restore stock if previously issued/affecting stock
  IF UPPER(COALESCE(v_dc.status, '')) != 'DRAFT' THEN
    FOR r_item IN SELECT * FROM public.delivery_challan_items WHERE delivery_challan_id = p_dc_id LOOP
      IF r_item.material_id IS NOT NULL AND r_item.warehouse_id IS NOT NULL AND r_item.quantity > 0 THEN
        SELECT id, current_stock INTO v_stock_id, v_current_stock
        FROM public.item_stock
        WHERE item_id = r_item.material_id
          AND warehouse_id = r_item.warehouse_id
          AND ((r_item.variant_id IS NULL AND company_variant_id IS NULL) OR company_variant_id = r_item.variant_id)
        FOR UPDATE;

        IF v_stock_id IS NOT NULL THEN
          UPDATE public.item_stock
          SET current_stock = current_stock + r_item.quantity, updated_at = NOW()
          WHERE id = v_stock_id;
        ELSE
          INSERT INTO public.item_stock (
            organisation_id, item_id, warehouse_id, company_variant_id, current_stock
          ) VALUES (
            v_org_id, r_item.material_id, r_item.warehouse_id, r_item.variant_id, r_item.quantity
          );
        END IF;

        INSERT INTO public.material_logs (
          organisation_id, item_id, variant_id,
          qty_received, qty_used, type, invoice_number, received_by, remarks, created_at
        ) VALUES (
          v_org_id, r_item.material_id, r_item.variant_id,
          r_item.quantity, 0, 'IN', v_dc.dc_number, v_user_id,
          'Delivery Challan Cancellation: ' || COALESCE(v_dc.dc_number, v_dc.id::TEXT) || ' (' || COALESCE(p_reason, '') || ')', NOW()
        );
      END IF;
    END LOOP;
  END IF;

  UPDATE public.delivery_challans
  SET status = 'CANCELLED', updated_at = NOW()
  WHERE id = p_dc_id;

  RETURN jsonb_build_object('status', 'success', 'dc_id', p_dc_id, 'doc_status', 'CANCELLED');
END;

DECLARE
  v_inward RECORD;
  v_org_id UUID;
  v_user_id UUID;
  r_item RECORD;
  v_stock_id UUID;
  v_current_stock NUMERIC;
  v_po_item RECORD;
BEGIN
  v_user_id := auth.uid();

  SELECT * INTO v_inward
  FROM public.material_inward
  WHERE id = p_inward_id
  FOR UPDATE;

  IF v_inward.id IS NULL THEN RAISE EXCEPTION 'Material Inward not found'; END IF;

  v_org_id := v_inward.organisation_id;
  IF v_user_id IS NOT NULL AND NOT public.user_can_access_org(v_org_id) THEN
    RAISE EXCEPTION 'Unauthorized organization access';
  END IF;

  IF UPPER(COALESCE(v_inward.status, '')) = 'CANCELLED' THEN
    RETURN jsonb_build_object(
      'status', 'success',
      'already_cancelled', true,
      'inward_id', p_inward_id,
      'inward_number', v_inward.inward_number
    );
  END IF;

  -- Reverse Stock
  IF UPPER(COALESCE(v_inward.status, 'ACTIVE')) != 'DRAFT' THEN
    FOR r_item IN
      SELECT 
        material_id,
        COALESCE(warehouse_id, v_inward.warehouse_id) AS warehouse_id,
        variant_id,
        material_name,
        SUM(quantity) AS total_qty
      FROM public.material_inward_items
      WHERE inward_id = p_inward_id
        AND COALESCE(supply_type, v_inward.supply_type, 'WAREHOUSE') = 'WAREHOUSE'
        AND material_id IS NOT NULL
      GROUP BY 1, 2, 3, 4
      ORDER BY 1, 2, 3
    LOOP
      IF r_item.warehouse_id IS NOT NULL THEN
        SELECT id, current_stock INTO v_stock_id, v_current_stock
        FROM public.item_stock
        WHERE item_id = r_item.material_id
          AND warehouse_id = r_item.warehouse_id
          AND ((r_item.variant_id IS NULL AND company_variant_id IS NULL) OR company_variant_id = r_item.variant_id)
        FOR UPDATE;

        IF v_stock_id IS NULL OR v_current_stock < r_item.total_qty THEN
          RAISE EXCEPTION 'Cannot cancel Material Inward %: Stock for % has already been consumed downstream. Available stock: %, Required for reversal: %', 
            COALESCE(v_inward.inward_number, v_inward.invoice_no, v_inward.id::TEXT),
            r_item.material_name,
            COALESCE(v_current_stock, 0),
            r_item.total_qty;
        END IF;

        UPDATE public.item_stock
        SET current_stock = current_stock - r_item.total_qty, updated_at = NOW()
        WHERE id = v_stock_id;

        INSERT INTO public.material_logs (
          organisation_id, project_id, item_id, variant_id,
          qty_received, qty_used, type, invoice_number, received_by, remarks, created_at
        ) VALUES (
          v_org_id, v_inward.project_id, r_item.material_id, r_item.variant_id,
          0, r_item.total_qty, 'OUT', v_inward.inward_number, v_user_id,
          'Cancelled Inward ' || COALESCE(v_inward.inward_number, v_inward.invoice_no) || COALESCE(': ' || p_reason, ''), NOW()
        );
      END IF;
    END LOOP;
  END IF;

  -- Reverse PO Item Received Quantities
  FOR r_item IN
    SELECT po_item_id, quantity
    FROM public.material_inward_items
    WHERE inward_id = p_inward_id AND po_item_id IS NOT NULL
  LOOP
    SELECT * INTO v_po_item
    FROM public.purchase_order_items
    WHERE id = r_item.po_item_id
    FOR UPDATE;

    IF v_po_item.id IS NOT NULL THEN
      UPDATE public.purchase_order_items
      SET received_qty = GREATEST(0, COALESCE(received_qty, 0) - r_item.quantity),
          balance_qty = LEAST(quantity, COALESCE(balance_qty, 0) + r_item.quantity)
      WHERE id = r_item.po_item_id;
    END IF;
  END LOOP;

  IF v_inward.po_id IS NOT NULL THEN
    UPDATE public.purchase_orders
    SET status = 'Open',
        updated_at = NOW()
    WHERE id = v_inward.po_id;
  END IF;

  UPDATE public.material_inward
  SET status = 'Cancelled',
      remarks = COALESCE(remarks || ' | ', '') || 'Cancelled: ' || COALESCE(p_reason, 'No reason provided')
  WHERE id = p_inward_id;

  RETURN jsonb_build_object(
    'status', 'success',
    'inward_id', p_inward_id,
    'inward_number', v_inward.inward_number,
    'doc_status', 'Cancelled'
  );
END;

DECLARE
  v_outward RECORD;
  v_org_id UUID;
  v_user_id UUID;
  r_item RECORD;
  v_stock_id UUID;
  v_current_stock NUMERIC;
BEGIN
  v_user_id := auth.uid();

  SELECT * INTO v_outward
  FROM public.material_outward
  WHERE id = p_outward_id
  FOR UPDATE;

  IF v_outward IS NULL THEN RAISE EXCEPTION 'Material Outward not found'; END IF;

  v_org_id := v_outward.organisation_id;
  IF v_user_id IS NOT NULL AND NOT public.user_can_access_org(v_org_id) THEN
    RAISE EXCEPTION 'Unauthorized organization access';
  END IF;

  IF UPPER(COALESCE(v_outward.status, '')) = 'CANCELLED' THEN
