    );
  END IF;

  IF UPPER(COALESCE(v_outward.status, 'ACTIVE')) != 'DRAFT' THEN
    FOR r_item IN
      SELECT 
        material_id,
        COALESCE(warehouse_id, v_outward.warehouse_id) AS warehouse_id,
        variant_id,
        material_name,
        SUM(quantity) AS total_qty
      FROM public.material_outward_items
      WHERE outward_id = p_outward_id
        AND material_id IS NOT NULL
      GROUP BY 1, 2, 3, 4
      ORDER BY 1, 2, 3
    LOOP
      IF r_item.warehouse_id IS NOT NULL THEN
        SELECT id, current_stock INTO v_stock_id, v_current_stock
        FROM public.item_stock
        WHERE item_id = r_item.material_id
          AND warehouse_id = r_item.warehouse_id
          AND ((r_item.variant_id IS NULL AND company_variant_id IS NULL) OR company_variant_id = r_item.variant_id)
        FOR UPDATE;

        IF v_stock_id IS NOT NULL THEN
          UPDATE public.item_stock
          SET current_stock = current_stock + r_item.total_qty, updated_at = NOW()
          WHERE id = v_stock_id;
        ELSE
          INSERT INTO public.item_stock (
            organisation_id, item_id, warehouse_id, company_variant_id, current_stock
          ) VALUES (
            v_org_id, r_item.material_id, r_item.warehouse_id, r_item.variant_id, r_item.total_qty
          );
        END IF;

        INSERT INTO public.material_logs (
          organisation_id, project_id, item_id, variant_id,
          qty_received, qty_used, type, invoice_number, received_by, remarks, created_at
        ) VALUES (
          v_org_id, v_outward.project_id, r_item.material_id, r_item.variant_id,
          r_item.total_qty, 0, 'IN', v_outward.outward_number, v_user_id,
          'Cancelled Outward ' || COALESCE(v_outward.outward_number, v_outward.id::TEXT) || COALESCE(': ' || p_reason, ''), NOW()
        );
      END IF;
    END LOOP;
  END IF;

  UPDATE public.material_outward
  SET status = 'Cancelled',
      remarks = COALESCE(remarks || ' | ', '') || 'Cancelled: ' || COALESCE(p_reason, 'No reason provided')
  WHERE id = p_outward_id;

  RETURN jsonb_build_object(
    'status', 'success',
    'outward_id', p_outward_id,
    'outward_number', v_outward.outward_number,
    'doc_status', 'Cancelled'
  );
END;

DECLARE
  v_sheet RECORD;
  v_wo RECORD;
BEGIN
  SELECT * INTO v_sheet
  FROM public.subcontractor_measurement_sheets
  WHERE id = p_sheet_id
  FOR UPDATE;

  IF v_sheet.id IS NULL THEN
    RAISE EXCEPTION 'Measurement sheet not found';
  END IF;

  IF auth.uid() IS NOT NULL AND NOT public.user_can_access_org(v_sheet.organisation_id) THEN
    RAISE EXCEPTION 'Unauthorized organization access';
  END IF;

  IF v_sheet.status = 'Cancelled' THEN
    RETURN jsonb_build_object(
      'status', 'success',
      'already_cancelled', true,
      'sheet_id', p_sheet_id,
      'sheet_no', v_sheet.sheet_no
    );
  END IF;

  SELECT * INTO v_wo
  FROM public.subcontractor_work_orders
  WHERE id = v_sheet.work_order_id
  FOR UPDATE;

  -- If sheet was previously approved, decrement total_measurements_count
  IF v_sheet.status = 'Approved' AND v_wo.id IS NOT NULL THEN
    UPDATE public.subcontractor_work_orders
    SET total_measurements_count = GREATEST(0, COALESCE(total_measurements_count, 1) - 1),
        updated_at = NOW()
    WHERE id = v_sheet.work_order_id;
  END IF;

  -- If an amendment was created, reverse the amendment effect on the work order
  IF v_sheet.amendment_id IS NOT NULL AND v_wo.id IS NOT NULL THEN
    UPDATE public.subcontractor_work_order_amendments
    SET status = 'Cancelled',
        cancellation_reason = p_reason,
        updated_at = NOW()
    WHERE id = v_sheet.amendment_id;

    PERFORM set_config('app.allow_financial_mutation', 'true', true);
    UPDATE public.subcontractor_work_orders
    SET total_amount = GREATEST(0, total_amount - v_sheet.difference),
        updated_at = NOW()
    WHERE id = v_sheet.work_order_id;
    PERFORM set_config('app.allow_financial_mutation', 'false', true);
  END IF;

  UPDATE public.subcontractor_measurement_sheets
  SET status = 'Cancelled',
      cancellation_reason = p_reason,
      updated_at = NOW()
  WHERE id = p_sheet_id;

  RETURN jsonb_build_object(
    'status', 'success',
    'sheet_id', p_sheet_id,
    'sheet_no', v_sheet.sheet_no,
    'doc_status', 'Cancelled'
  );
END;

DECLARE
  v_payroll RECORD;
  v_salary_exp_id UUID;
  v_pf_payable_id UUID;
  v_esi_payable_id UUID;
  v_tds_payable_id UUID;
  v_adv_recovery_id UUID;
  v_salary_payable_id UUID;
  v_rev_journal_id UUID := NULL;
  v_creator_id UUID;
BEGIN
  IF auth.uid() IS NOT NULL AND NOT public.user_can_access_org(p_organisation_id) THEN
    RAISE EXCEPTION 'Unauthorized organization access';
  END IF;

  SELECT * INTO v_payroll
  FROM public.payroll_runs
  WHERE organisation_id = p_organisation_id AND month = p_month
  FOR UPDATE;

  IF v_payroll IS NULL THEN
    RAISE EXCEPTION 'Payroll run for month % not found', p_month;
  END IF;

  IF v_payroll.status = 'cancelled' THEN
    RETURN jsonb_build_object(
      'status', 'success',
      'already_cancelled', true,
      'month', p_month
    );
  END IF;

  SELECT id INTO v_creator_id
  FROM public.user_profiles WHERE user_id = auth.uid() OR id = auth.uid() LIMIT 1;

  -- Post Reversing GL Journal Entry
  IF v_payroll.gross_salary > 0 THEN
    v_salary_exp_id     := public.ensure_gl_account_exists(p_organisation_id, '5100', 'Salaries & Wages', 'Expense');
    v_pf_payable_id     := public.ensure_gl_account_exists(p_organisation_id, '2210', 'Provident Fund Payable', 'Liability');
    v_esi_payable_id    := public.ensure_gl_account_exists(p_organisation_id, '2220', 'ESI Payable', 'Liability');
    v_tds_payable_id    := public.ensure_gl_account_exists(p_organisation_id, '2200', 'TDS Payable (192B)', 'Liability');
    v_adv_recovery_id   := public.ensure_gl_account_exists(p_organisation_id, '1400', 'Employee Advance Recovery', 'Asset');
    v_salary_payable_id := public.ensure_gl_account_exists(p_organisation_id, '2120', 'Salaries Payable', 'Liability');

    INSERT INTO public.journal_entries (
      company_id, voucher_no, voucher_date, voucher_type, narration, status, created_by
    ) VALUES (
      p_organisation_id, 'REV-PAYROLL-' || p_month, CURRENT_DATE, 'Journal',
      'Reversal of Payroll Accrual for ' || p_month || COALESCE(' (' || p_reason || ')', ''),
      'Posted', v_creator_id
    ) RETURNING id INTO v_rev_journal_id;

    -- Reverse Credit Lines: Debit Liabilities and Recoveries
    IF COALESCE(v_payroll.total_pf, 0) > 0 THEN
      INSERT INTO public.journal_entry_lines (journal_id, account_id, debit, credit, narration)
      VALUES (v_rev_journal_id, v_pf_payable_id, v_payroll.total_pf, 0.00, 'Reversal of PF Deduction Payable');
    END IF;

    IF COALESCE(v_payroll.total_esi, 0) > 0 THEN
      INSERT INTO public.journal_entry_lines (journal_id, account_id, debit, credit, narration)
      VALUES (v_rev_journal_id, v_esi_payable_id, v_payroll.total_esi, 0.00, 'Reversal of ESI Deduction Payable');
    END IF;

    IF COALESCE(v_payroll.total_tds, 0) > 0 THEN
      INSERT INTO public.journal_entry_lines (journal_id, account_id, debit, credit, narration)
      VALUES (v_rev_journal_id, v_tds_payable_id, v_payroll.total_tds, 0.00, 'Reversal of TDS Deduction Payable');
    END IF;

    IF COALESCE(v_payroll.total_advances, 0) > 0 THEN
      INSERT INTO public.journal_entry_lines (journal_id, account_id, debit, credit, narration)
      VALUES (v_rev_journal_id, v_adv_recovery_id, v_payroll.total_advances, 0.00, 'Reversal of Advance Recovery');
    END IF;

    IF COALESCE(v_payroll.net_salary, 0) > 0 THEN
      INSERT INTO public.journal_entry_lines (journal_id, account_id, debit, credit, narration)
      VALUES (v_rev_journal_id, v_salary_payable_id, v_payroll.net_salary, 0.00, 'Reversal of Salaries Payable');
    END IF;

    -- Reverse Debit Line: Credit Salary Expense
    INSERT INTO public.journal_entry_lines (journal_id, account_id, debit, credit, narration)
    VALUES (v_rev_journal_id, v_salary_exp_id, 0.00, v_payroll.gross_salary, 'Reversal of Gross Salaries Expense');
  END IF;

  UPDATE public.payroll_runs
  SET status = 'cancelled',
      cancellation_reason = p_reason,
      updated_at = NOW()
  WHERE id = v_payroll.id;

  RETURN jsonb_build_object(
    'status', 'success',
    'month', p_month,
    'doc_status', 'cancelled',
    'rev_journal_id', v_rev_journal_id
  );
END;

DECLARE
  v_grn RECORD;
  v_org_id UUID;
  v_user_id UUID;
  r_item RECORD;
  v_stock_id UUID;
  v_current_stock NUMERIC;
  v_po_item RECORD;
  v_qty NUMERIC;
BEGIN
  v_user_id := auth.uid();

  SELECT * INTO v_grn
  FROM public.goods_receipt_notes
  WHERE id = p_grn_id
  FOR UPDATE;

  IF v_grn.id IS NULL THEN RAISE EXCEPTION 'GRN not found'; END IF;

  v_org_id := v_grn.organisation_id;
  IF v_user_id IS NOT NULL AND NOT public.user_can_access_org(v_org_id) THEN
    RAISE EXCEPTION 'Unauthorized organization access';
  END IF;

  IF LOWER(COALESCE(v_grn.status, '')) = 'cancelled' THEN
    RETURN jsonb_build_object('status', 'success', 'already_cancelled', true, 'grn_id', p_grn_id);
  END IF;

  IF LOWER(COALESCE(v_grn.status, '')) = 'accepted' THEN
    FOR r_item IN
      SELECT material_id, warehouse_id, accepted_qty, received_qty, purchase_order_item_id
      FROM public.grn_items
      WHERE grn_id = p_grn_id
    LOOP
      v_qty := CASE WHEN r_item.accepted_qty > 0 THEN r_item.accepted_qty ELSE r_item.received_qty END;
      IF r_item.material_id IS NOT NULL AND v_qty > 0 THEN
        SELECT id, current_stock INTO v_stock_id, v_current_stock
        FROM public.item_stock
        WHERE item_id = r_item.material_id
          AND (r_item.warehouse_id IS NULL OR warehouse_id = r_item.warehouse_id)
        FOR UPDATE;

        IF v_stock_id IS NOT NULL THEN
          IF v_current_stock < v_qty THEN
            RAISE EXCEPTION 'Cannot cancel GRN %: stock already consumed downstream', v_grn.grn_no;
          END IF;

          UPDATE public.item_stock
          SET current_stock = current_stock - v_qty, updated_at = NOW()
          WHERE id = v_stock_id;

          INSERT INTO public.material_logs (
            organisation_id, item_id, qty_received, qty_used, type, invoice_number, received_by, remarks, created_at
          ) VALUES (
            v_org_id, r_item.material_id, 0, v_qty, 'OUT', v_grn.grn_no, v_user_id,
            'Cancelled GRN: ' || COALESCE(v_grn.grn_no, v_grn.id::TEXT) || COALESCE(': ' || p_reason, ''), NOW()
          );
        END IF;

        IF r_item.purchase_order_item_id IS NOT NULL THEN
          SELECT * INTO v_po_item
          FROM public.purchase_order_items
          WHERE id = r_item.purchase_order_item_id
          FOR UPDATE;

          IF v_po_item.id IS NOT NULL THEN
            UPDATE public.purchase_order_items
            SET received_qty = GREATEST(0, COALESCE(received_qty, 0) - v_qty),
                balance_qty = LEAST(quantity, COALESCE(balance_qty, 0) + v_qty)
            WHERE id = r_item.purchase_order_item_id;
          END IF;
        END IF;
      END IF;
    END LOOP;
  END IF;

  UPDATE public.goods_receipt_notes
  SET status = 'cancelled',
      remarks = COALESCE(remarks || ' | ', '') || 'Cancelled: ' || COALESCE(p_reason, 'No reason provided'),
      updated_at = NOW()
  WHERE id = p_grn_id;

  RETURN jsonb_build_object(
    'status', 'success',
    'grn_id', p_grn_id,
    'grn_no', v_grn.grn_no,
    'doc_status', 'cancelled'
  );
END;

DECLARE
  v_bill RECORD;
  v_ap_account_id UUID;
  v_expense_account_id UUID;
  v_journal_id UUID;
BEGIN
  SELECT * INTO v_bill
  FROM public.purchase_bills
  WHERE id = p_bill_id
  FOR UPDATE;

  IF v_bill.id IS NULL THEN RAISE EXCEPTION 'Purchase bill not found'; END IF;

  IF auth.uid() IS NOT NULL AND NOT public.user_can_access_org(v_bill.organisation_id) THEN
    RAISE EXCEPTION 'Unauthorized organization access';
  END IF;

  IF LOWER(COALESCE(v_bill.approval_status, '')) = 'cancelled' THEN
    RETURN jsonb_build_object(
      'status', 'success',
      'already_cancelled', true,
      'bill_id', p_bill_id,
      'bill_number', v_bill.bill_number
    );
  END IF;

  IF COALESCE(v_bill.paid_amount, 0) > 0 THEN
    RAISE EXCEPTION 'Cannot cancel purchase bill % with active payment allocations (Paid: ₹%). Cancel payments first.',
      v_bill.bill_number, v_bill.paid_amount;
  END IF;

  -- Post Reversing GL Journal Entry (Dr Accounts Payable, Cr Purchase Expense)
  SELECT id INTO v_ap_account_id FROM public.accounts WHERE (organisation_id = v_bill.organisation_id OR company_id = v_bill.organisation_id) AND account_code = '2100' LIMIT 1;
  SELECT id INTO v_expense_account_id FROM public.accounts WHERE (organisation_id = v_bill.organisation_id OR company_id = v_bill.organisation_id) AND account_code IN ('5000', '1500', '2000') LIMIT 1;

  IF v_ap_account_id IS NOT NULL AND v_bill.total_amount > 0 THEN
    INSERT INTO public.journal_entries (
      company_id, voucher_no, voucher_date, voucher_type,
      narration, status, created_by
    ) VALUES (
      v_bill.organisation_id,
      'REV-' || COALESCE(v_bill.bill_number, v_bill.id::TEXT),
      CURRENT_DATE,
      'Purchase',
      'Reversal of Purchase Bill ' || COALESCE(v_bill.bill_number, '') || COALESCE(' (' || p_reason || ')', ''),
      'Posted',
      auth.uid()
    ) RETURNING id INTO v_journal_id;

    -- Dr Accounts Payable
    INSERT INTO public.journal_entry_lines (journal_id, account_id, party_type, party_id, debit, credit, narration)
    VALUES (v_journal_id, v_ap_account_id, 'vendor', v_bill.vendor_id, v_bill.total_amount, 0.00, 'Reversal of AP Bill');

    -- Cr Purchase Expense
    IF v_expense_account_id IS NOT NULL THEN
      INSERT INTO public.journal_entry_lines (journal_id, account_id, party_type, party_id, debit, credit, narration)
      VALUES (v_journal_id, v_expense_account_id, 'vendor', v_bill.vendor_id, 0.00, v_bill.total_amount, 'Reversal of Purchase Expense');
    END IF;
  END IF;

  UPDATE public.purchase_bills
  SET approval_status = 'Cancelled',
      payment_status = 'Cancelled',
      notes = COALESCE(notes || ' | ', '') || 'Cancelled: ' || COALESCE(p_reason, 'No reason provided'),
      updated_at = NOW()
  WHERE id = p_bill_id;

  PERFORM public.recalc_vendor_balance(v_bill.vendor_id, v_bill.organisation_id);

  RETURN jsonb_build_object(
    'status', 'success',
    'bill_id', p_bill_id,
    'bill_number', v_bill.bill_number,
    'doc_status', 'cancelled',
    'journal_id', v_journal_id
  );
END;

DECLARE
  v_po RECORD;
  v_total_received NUMERIC := 0;
  v_active_bills NUMERIC := 0;
BEGIN
  SELECT * INTO v_po
  FROM public.purchase_orders
  WHERE id = p_po_id
  FOR UPDATE;

  IF v_po.id IS NULL THEN RAISE EXCEPTION 'Purchase order not found'; END IF;

  IF auth.uid() IS NOT NULL AND NOT public.user_can_access_org(v_po.organisation_id) THEN
    RAISE EXCEPTION 'Unauthorized organization access';
  END IF;

  IF LOWER(COALESCE(v_po.status, '')) = 'cancelled' THEN
    RETURN jsonb_build_object('status', 'success', 'already_cancelled', true, 'po_id', p_po_id, 'po_number', v_po.po_number);
  END IF;

  -- Check if received quantity > 0
  SELECT COALESCE(SUM(received_qty), 0) INTO v_total_received
  FROM public.purchase_order_items
  WHERE po_id = p_po_id;

  IF v_total_received > 0 THEN
    RAISE EXCEPTION 'Cannot cancel Purchase Order % with received goods (Received Qty: %). Cancel GRNs/Inward receipts first.',
      v_po.po_number, v_total_received;
  END IF;

  -- Check if active bills exist
  SELECT COUNT(*) INTO v_active_bills
  FROM public.purchase_bills
  WHERE po_id = p_po_id AND LOWER(COALESCE(approval_status, '')) NOT IN ('cancelled', 'rejected');

  IF v_active_bills > 0 THEN
    RAISE EXCEPTION 'Cannot cancel Purchase Order % with active purchase bills. Cancel associated bills first.',
      v_po.po_number;
  END IF;

  PERFORM set_config('app.allow_purchase_order_mutation', 'true', true);

  UPDATE public.purchase_orders
  SET status = 'Cancelled',
      approval_status = 'Cancelled',
      internal_notes = COALESCE(internal_notes || ' | ', '') || 'Cancelled: ' || COALESCE(p_reason, 'No reason provided'),
      updated_at = NOW()
  WHERE id = p_po_id;

  PERFORM set_config('app.allow_purchase_order_mutation', 'false', true);

  RETURN jsonb_build_object(
    'status', 'success',
    'po_id', p_po_id,
    'po_number', v_po.po_number,
    'doc_status', 'Cancelled'
  );
END;

DECLARE
  v_quote RECORD;
  v_active_dcs INT := 0;
  v_active_invoices INT := 0;
BEGIN
  SELECT * INTO v_quote
  FROM public.quotation_header
  WHERE id = p_quotation_id
  FOR UPDATE;

  IF v_quote.id IS NULL THEN
    RAISE EXCEPTION 'Quotation not found';
  END IF;

  IF auth.uid() IS NOT NULL AND NOT public.user_can_access_org(v_quote.organisation_id) THEN
    RAISE EXCEPTION 'Unauthorized organization access';
  END IF;

  IF LOWER(COALESCE(v_quote.status, '')) = 'cancelled' THEN
    RETURN jsonb_build_object('status', 'success', 'already_cancelled', true, 'quotation_id', p_quotation_id, 'quotation_no', v_quote.quotation_no);
  END IF;

  -- Check if converted or linked to active DCs/Invoices
  SELECT COUNT(*) INTO v_active_dcs
  FROM public.delivery_challans
  WHERE quotation_id = p_quotation_id AND UPPER(COALESCE(status, '')) != 'CANCELLED';

  IF v_active_dcs > 0 THEN
    RAISE EXCEPTION 'Cannot cancel Quotation %: Active delivery challans are linked. Cancel associated DCs first.', v_quote.quotation_no;
  END IF;

  SELECT COUNT(*) INTO v_active_invoices
  FROM public.invoices
  WHERE quotation_id = p_quotation_id AND LOWER(COALESCE(status, '')) != 'cancelled';

  IF v_active_invoices > 0 THEN
    RAISE EXCEPTION 'Cannot cancel Quotation %: Active sales invoices are linked. Cancel associated invoices first.', v_quote.quotation_no;
  END IF;

  UPDATE public.quotation_header
  SET status = 'Cancelled',
      remarks = COALESCE(remarks || ' | ', '') || 'Cancelled: ' || COALESCE(p_reason, 'No reason provided'),
      updated_at = NOW()
  WHERE id = p_quotation_id;

  RETURN jsonb_build_object(
    'status', 'success',
    'quotation_id', p_quotation_id,
    'quotation_no', v_quote.quotation_no,
    'doc_status', 'Cancelled'
  );
END;

DECLARE
  v_invoice RECORD;
  v_org_id UUID;
  v_ar_account_id UUID;
  v_sales_account_id UUID;
  v_cgst_account_id UUID;
  v_sgst_account_id UUID;
  v_igst_account_id UUID;
  v_journal_id UUID;
BEGIN
  SELECT * INTO v_invoice
  FROM public.invoices
  WHERE id = p_invoice_id
  FOR UPDATE;

  IF v_invoice.id IS NULL THEN RAISE EXCEPTION 'Invoice not found'; END IF;

  v_org_id := COALESCE(v_invoice.organisation_id, v_invoice.org_id);
  IF auth.uid() IS NOT NULL AND NOT public.user_can_access_org(v_org_id) THEN
    RAISE EXCEPTION 'Unauthorized organization access';
  END IF;

  IF LOWER(COALESCE(v_invoice.status, '')) = 'cancelled' THEN
    RETURN jsonb_build_object(
      'status', 'success',
      'already_cancelled', true,
      'invoice_id', p_invoice_id,
      'invoice_no', v_invoice.invoice_no
    );
  END IF;

  IF COALESCE(v_invoice.paid_amount, 0) > 0 THEN
    RAISE EXCEPTION 'Cannot cancel invoice % with recorded payments (Paid: ₹%). Cancel payments first.',
      v_invoice.invoice_no, v_invoice.paid_amount;
  END IF;

  -- Reverse stock deductions
  PERFORM public.reverse_invoice_stock_deductions(p_invoice_id);

  -- Post Reversing GL Journal Entry
  SELECT id INTO v_ar_account_id FROM public.accounts WHERE (organisation_id = v_org_id OR company_id = v_org_id) AND account_code = '1100' LIMIT 1;
  SELECT id INTO v_sales_account_id FROM public.accounts WHERE (organisation_id = v_org_id OR company_id = v_org_id) AND account_code IN ('3100', '3101') ORDER BY account_code DESC LIMIT 1;
  SELECT id INTO v_cgst_account_id FROM public.accounts WHERE (organisation_id = v_org_id OR company_id = v_org_id) AND account_code = '2201' LIMIT 1;
  SELECT id INTO v_sgst_account_id FROM public.accounts WHERE (organisation_id = v_org_id OR company_id = v_org_id) AND account_code = '2202' LIMIT 1;
  SELECT id INTO v_igst_account_id FROM public.accounts WHERE (organisation_id = v_org_id OR company_id = v_org_id) AND account_code = '2203' LIMIT 1;

  IF v_ar_account_id IS NOT NULL AND v_invoice.total > 0 THEN
    INSERT INTO public.journal_entries (
      company_id, organisation_id, voucher_no, voucher_date, voucher_type,
      narration, status, created_by
    ) VALUES (
      v_org_id, v_org_id,
      'REV-' || COALESCE(v_invoice.invoice_no, v_invoice.id::TEXT),
      CURRENT_DATE,
      'Sales',
      'Reversal of Sales Invoice ' || COALESCE(v_invoice.invoice_no, '') || COALESCE(' (' || p_reason || ')', ''),
      'Posted',
      auth.uid()
    ) RETURNING id INTO v_journal_id;

    -- Dr Sales Revenue
    IF v_sales_account_id IS NOT NULL AND v_invoice.subtotal > 0 THEN
      INSERT INTO public.journal_entry_lines (journal_id, account_id, party_type, party_id, debit, credit, narration)
      VALUES (v_journal_id, v_sales_account_id, 'client', v_invoice.client_id, v_invoice.subtotal, 0.00, 'Reversal of Sales Revenue');
    END IF;

    -- Dr GST
    IF v_cgst_account_id IS NOT NULL AND COALESCE(v_invoice.cgst, 0) > 0 THEN
      INSERT INTO public.journal_entry_lines (journal_id, account_id, party_type, party_id, debit, credit, narration)
      VALUES (v_journal_id, v_cgst_account_id, 'client', v_invoice.client_id, v_invoice.cgst, 0.00, 'Reversal of Output CGST');
    END IF;

    IF v_sgst_account_id IS NOT NULL AND COALESCE(v_invoice.sgst, 0) > 0 THEN
      INSERT INTO public.journal_entry_lines (journal_id, account_id, party_type, party_id, debit, credit, narration)
      VALUES (v_journal_id, v_sgst_account_id, 'client', v_invoice.client_id, v_invoice.sgst, 0.00, 'Reversal of Output SGST');
    END IF;

    IF v_igst_account_id IS NOT NULL AND COALESCE(v_invoice.igst, 0) > 0 THEN
      INSERT INTO public.journal_entry_lines (journal_id, account_id, party_type, party_id, debit, credit, narration)
      VALUES (v_journal_id, v_igst_account_id, 'client', v_invoice.client_id, v_invoice.igst, 0.00, 'Reversal of Output IGST');
    END IF;

    -- Cr Accounts Receivable
    INSERT INTO public.journal_entry_lines (journal_id, account_id, party_type, party_id, debit, credit, narration)
    VALUES (v_journal_id, v_ar_account_id, 'client', v_invoice.client_id, 0.00, v_invoice.total, 'Reversal of AR Invoice');
  END IF;

  UPDATE public.invoices
  SET status = 'cancelled',
      remarks = COALESCE(remarks || ' | ', '') || 'Cancelled: ' || COALESCE(p_reason, 'No reason provided'),
      updated_at = NOW()
  WHERE id = p_invoice_id;

  RETURN jsonb_build_object(
    'status', 'success',
    'invoice_id', p_invoice_id,
    'invoice_no', v_invoice.invoice_no,
    'doc_status', 'cancelled',
    'journal_id', v_journal_id
  );
END;

DECLARE
  v_transfer RECORD;
  v_org_id UUID;
  v_user_id UUID;
  r_item RECORD;
  v_stock_id UUID;
  v_current_stock NUMERIC;
BEGIN
  v_user_id := auth.uid();

  SELECT * INTO v_transfer
  FROM public.stock_transfers
  WHERE id = p_transfer_id
  FOR UPDATE;

  IF v_transfer IS NULL THEN RAISE EXCEPTION 'Stock Transfer not found'; END IF;

  v_org_id := v_transfer.organisation_id;
  IF v_user_id IS NOT NULL AND NOT public.user_can_access_org(v_org_id) THEN
    RAISE EXCEPTION 'Unauthorized organization access';
  END IF;

  IF UPPER(COALESCE(v_transfer.status, '')) = 'CANCELLED' THEN
    RETURN jsonb_build_object(
      'status', 'success',
      'already_cancelled', true,
      'transfer_id', p_transfer_id,
      'transfer_no', v_transfer.transfer_no
    );
  END IF;

  -- If ON_TRANSIT or IN_TRANSIT, restore deducted stock to source warehouse
  IF UPPER(COALESCE(v_transfer.status, '')) IN ('ON_TRANSIT', 'IN_TRANSIT') THEN
    FOR r_item IN
      SELECT item_id, company_variant_id, SUM(quantity) AS total_qty
      FROM public.stock_transfer_items
      WHERE transfer_id = p_transfer_id
      GROUP BY 1, 2
    LOOP
      SELECT id INTO v_stock_id
      FROM public.item_stock
      WHERE item_id = r_item.item_id
        AND warehouse_id = v_transfer.from_warehouse_id
        AND ((r_item.company_variant_id IS NULL AND company_variant_id IS NULL) OR company_variant_id = r_item.company_variant_id)
      FOR UPDATE;

      IF v_stock_id IS NOT NULL THEN
        UPDATE public.item_stock
        SET current_stock = current_stock + r_item.total_qty, updated_at = NOW()
        WHERE id = v_stock_id;
      ELSE
        INSERT INTO public.item_stock (
          organisation_id, item_id, warehouse_id, company_variant_id, current_stock
        ) VALUES (
          v_org_id, r_item.item_id, v_transfer.from_warehouse_id, r_item.company_variant_id, r_item.total_qty
        );
      END IF;

      INSERT INTO public.material_logs (
        organisation_id, item_id, variant_id,
        qty_received, qty_used, type, invoice_number, received_by, remarks, created_at
      ) VALUES (
        v_org_id, r_item.item_id, r_item.company_variant_id,
        r_item.total_qty, 0, 'IN', v_transfer.transfer_no, v_user_id,
        'Cancelled Transit Stock Transfer ' || v_transfer.transfer_no || COALESCE(': ' || p_reason, ''), NOW()
      );
    END LOOP;

  -- If already STOCK_RECEIVED or RECEIVED, reverse destination stock and restore source
  ELSIF UPPER(COALESCE(v_transfer.status, '')) IN ('STOCK_RECEIVED', 'RECEIVED') THEN
    FOR r_item IN
      SELECT item_id, company_variant_id, SUM(COALESCE(received_qty, quantity)) AS total_received_qty, SUM(quantity) AS total_sent_qty
      FROM public.stock_transfer_items
      WHERE transfer_id = p_transfer_id
      GROUP BY 1, 2
    LOOP
      -- Check and deduct from destination
      SELECT id, current_stock INTO v_stock_id, v_current_stock
      FROM public.item_stock
      WHERE item_id = r_item.item_id
        AND warehouse_id = v_transfer.to_warehouse_id
        AND ((r_item.company_variant_id IS NULL AND company_variant_id IS NULL) OR company_variant_id = r_item.company_variant_id)
      FOR UPDATE;

      IF v_stock_id IS NULL OR v_current_stock < r_item.total_received_qty THEN
        RAISE EXCEPTION 'Cannot cancel received Stock Transfer %: Stock at destination warehouse has already been consumed downstream. Available: %, Required for reversal: %',
          v_transfer.transfer_no, COALESCE(v_current_stock, 0), r_item.total_received_qty;
      END IF;

      UPDATE public.item_stock
      SET current_stock = current_stock - r_item.total_received_qty, updated_at = NOW()
      WHERE id = v_stock_id;

      -- Restore to source
      SELECT id INTO v_stock_id
      FROM public.item_stock
      WHERE item_id = r_item.item_id
        AND warehouse_id = v_transfer.from_warehouse_id
        AND ((r_item.company_variant_id IS NULL AND company_variant_id IS NULL) OR company_variant_id = r_item.company_variant_id)
      FOR UPDATE;

      IF v_stock_id IS NOT NULL THEN
        UPDATE public.item_stock
        SET current_stock = current_stock + r_item.total_sent_qty, updated_at = NOW()
        WHERE id = v_stock_id;
      ELSE
        INSERT INTO public.item_stock (
          organisation_id, item_id, warehouse_id, company_variant_id, current_stock
        ) VALUES (
          v_org_id, r_item.item_id, v_transfer.from_warehouse_id, r_item.company_variant_id, r_item.total_sent_qty
        );
      END IF;

      INSERT INTO public.material_logs (
        organisation_id, item_id, variant_id,
        qty_received, qty_used, type, invoice_number, received_by, remarks, created_at
      ) VALUES (
        v_org_id, r_item.item_id, r_item.company_variant_id,
        r_item.total_sent_qty, 0, 'IN', v_transfer.transfer_no, v_user_id,
        'Cancelled Received Stock Transfer ' || v_transfer.transfer_no || COALESCE(': ' || p_reason, ''), NOW()
      );
    END LOOP;
  END IF;

  UPDATE public.stock_t

DECLARE
  v_bill RECORD;
  v_ap_account_id UUID;
  v_expense_account_id UUID;
  v_journal_id UUID;
BEGIN
  SELECT * INTO v_bill
  FROM public.subcontractor_invoices
  WHERE id = p_bill_id
  FOR UPDATE;

  IF v_bill.id IS NULL THEN RAISE EXCEPTION 'Subcontractor bill not found'; END IF;

  IF auth.uid() IS NOT NULL AND NOT public.user_can_access_org(v_bill.organisation_id) THEN
    RAISE EXCEPTION 'Unauthorized organization access';
  END IF;

  IF LOWER(COALESCE(v_bill.status, '')) = 'cancelled' THEN
    RETURN jsonb_build_object(
      'status', 'success',
      'already_cancelled', true,
      'bill_id', p_bill_id,
      'invoice_no', v_bill.invoice_no
    );
  END IF;

  -- Cancel associated retention
  UPDATE public.subcontractor_retention
  SET status = 'Cancelled'
  WHERE work_order_id = v_bill.work_order_id AND status = 'Held';

  -- Post Reversing GL Entry (Dr Accounts Payable, Cr Subcontractor Expense)
  SELECT id INTO v_ap_account_id FROM public.accounts WHERE (organisation_id = v_bill.organisation_id OR company_id = v_bill.organisation_id) AND account_code = '2100' LIMIT 1;
  SELECT id INTO v_expense_account_id FROM public.accounts WHERE (organisation_id = v_bill.organisation_id OR company_id = v_bill.organisation_id) AND account_code IN ('4100', '4101', '4000') ORDER BY account_code DESC LIMIT 1;

  IF v_ap_account_id IS NOT NULL AND v_expense_account_id IS NOT NULL AND v_bill.amount > 0 THEN
    INSERT INTO public.journal_entries (
      company_id, voucher_no, voucher_date, voucher_type,
      narration, status, created_by
    ) VALUES (
      v_bill.organisation_id,
      'REV-' || COALESCE(v_bill.invoice_no, v_bill.id::TEXT),
      CURRENT_DATE,
      'Purchase',
      'Reversal of Subcontractor Bill ' || COALESCE(v_bill.invoice_no, '') || COALESCE(' (' || p_reason || ')', ''),
      'Posted',
      auth.uid()
    ) RETURNING id INTO v_journal_id;

    INSERT INTO public.journal_entry_lines (journal_id, account_id, party_type, party_id, debit, credit, narration)
    VALUES (v_journal_id, v_ap_account_id, 'vendor', v_bill.subcontractor_id, v_bill.amount, 0.00, 'Reversal of Subcontractor AP');

    INSERT INTO public.journal_entry_lines (journal_id, account_id, party_type, party_id, debit, credit, narration)
    VALUES (v_journal_id, v_expense_account_id, 'vendor', v_bill.subcontractor_id, 0.00, v_bill.amount, 'Reversal of Subcontractor Expense');
  END IF;

  UPDATE public.subcontractor_invoices
  SET status = 'Cancelled',
      remarks = COALESCE(remarks || ' | ', '') || 'Cancelled: ' || COALESCE(p_reason, 'No reason provided')
  WHERE id = p_bill_id;

  PERFORM public.recalc_subcontractor_balances(v_bill.subcontractor_id, v_bill.organisation_id);

  RETURN jsonb_build_object(
    'status', 'success',
    'bill_id', p_bill_id,
    'invoice_no', v_bill.invoice_no,
    'doc_status', 'cancelled',
    'journal_id', v_journal_id
  );
END;

DECLARE
  v_payment RECORD;
  v_bank_account_id UUID;
  v_ap_account_id UUID;
  v_tds_account_id UUID;
  v_journal_id UUID;
BEGIN
  SELECT * INTO v_payment
  FROM public.subcontractor_payments
  WHERE id = p_payment_id
  FOR UPDATE;

  IF v_payment.id IS NULL THEN RAISE EXCEPTION 'Subcontractor payment not found'; END IF;

  IF auth.uid() IS NOT NULL AND NOT public.user_can_access_org(v_payment.organisation_id) THEN
    RAISE EXCEPTION 'Unauthorized organization access';
  END IF;

  IF v_payment.is_deleted = true OR LOWER(COALESCE(v_payment.approval_status, '')) = 'cancelled' THEN
    RETURN jsonb_build_object(
      'status', 'success',
      'already_cancelled', true,
      'payment_id', p_payment_id,
      'reference_no', v_payment.reference_no
    );
  END IF;

  -- Post Reversing GL Journal Entry
  SELECT id INTO v_ap_account_id
  FROM public.accounts
  WHERE (organisation_id = v_payment.organisation_id OR company_id = v_payment.organisation_id)
    AND account_code = '2100'
  LIMIT 1;

  IF LOWER(TRIM(COALESCE(v_payment.payment_mode, ''))) LIKE '%cash%' THEN
    SELECT id INTO v_bank_account_id
    FROM public.accounts
    WHERE (organisation_id = v_payment.organisation_id OR company_id = v_payment.organisation_id)
      AND account_code IN ('1300', '1301')
    ORDER BY account_code DESC LIMIT 1;
  ELSE
    SELECT id INTO v_bank_account_id
    FROM public.accounts
    WHERE (organisation_id = v_payment.organisation_id OR company_id = v_payment.organisation_id)
      AND account_code = '1200'
    LIMIT 1;
  END IF;

  SELECT id INTO v_tds_account_id
  FROM public.accounts
  WHERE (organisation_id = v_payment.organisation_id OR company_id = v_payment.organisation_id)
    AND account_code = '2200'
  LIMIT 1;

  IF v_ap_account_id IS NOT NULL AND v_bank_account_id IS NOT NULL AND v_payment.amount > 0 THEN
    INSERT INTO public.journal_entries (
      company_id, voucher_no, voucher_date, voucher_type,
      narration, status, created_by
    ) VALUES (
      v_payment.organisation_id,
      'REV-' || COALESCE(v_payment.reference_no, v_payment.id::TEXT),
      CURRENT_DATE,
      'Payment',
      'Reversal of Subcontractor Payment ' || COALESCE(v_payment.reference_no, '') || COALESCE(' (' || p_reason || ')', ''),
      'Posted',
      auth.uid()
    ) RETURNING id INTO v_journal_id;

    INSERT INTO public.journal_entry_lines (
      journal_id, account_id, party_type, party_id, debit, credit, narration
    ) VALUES (
      v_journal_id, v_bank_account_id, 'vendor', v_payment.subcontractor_id, COALESCE(v_payment.net_amount, v_payment.amount), 0.00, 'Reversal of Bank/Cash Disbursement'
    );

    IF COALESCE(v_payment.tds_amount, 0) > 0 AND v_tds_account_id IS NOT NULL THEN
      INSERT INTO public.journal_entry_lines (
        journal_id, account_id, party_type, party_id, debit, credit, narration
      ) VALUES (
        v_journal_id, v_tds_account_id, 'vendor', v_payment.subcontractor_id, v_payment.tds_amount, 0.00, 'Reversal of TDS Payable'
      );
    END IF;

    INSERT INTO public.journal_entry_lines (
      journal_id, account_id, party_type, party_id, debit, credit, narration
    ) VALUES (
      v_journal_id, v_ap_account_id, 'vendor', v_payment.subcontractor_id, 0.00, COALESCE(v_payment.gross_amount, v_payment.amount), 'Reversal of AP Settlement'
    );
  END IF;

  UPDATE public.subcontractor_tds_payments
  SET status = 'Cancelled'
  WHERE payment_id = p_payment_id;

  UPDATE public.subcontractor_payments
  SET approval_status = 'Cancelled',
      workflow_step = 'cancelled',
      is_deleted = true,
      deletion_reason = p_reason,
      deleted_at = NOW(),
      deleted_by = auth.uid()
  WHERE id = p_payment_id;

  PERFORM public.recalc_subcontractor_balances(v_payment.subcontractor_id, v_payment.organisation_id);

  RETURN jsonb_build_object(
    'status', 'success',
    'payment_id', p_payment_id,
    'reference_no', v_payment.reference_no,
    'doc_status', 'cancelled',
    'journal_id', v_journal_id
  );
END;

DECLARE
  v_payment RECORD;
  v_alloc RECORD;
  v_bill RECORD;
  v_new_paid NUMERIC(15,2);
  v_new_balance NUMERIC(15,2);
  v_new_status TEXT;
  v_bank_account_id UUID;
  v_ap_account_id UUID;
  v_journal_id UUID;
BEGIN
  SELECT * INTO v_payment
  FROM public.purchase_payments
  WHERE id = p_payment_id
  FOR UPDATE;

  IF v_payment.id IS NULL THEN RAISE EXCEPTION 'Purchase payment not found'; END IF;

  IF auth.uid() IS NOT NULL AND NOT public.user_can_access_org(v_payment.organisation_id) THEN
    RAISE EXCEPTION 'Unauthorized organization access';
  END IF;

  IF v_payment.is_deleted = true OR LOWER(COALESCE(v_payment.approval_status, '')) = 'cancelled' THEN
    RETURN jsonb_build_object(
      'status', 'success',
      'already_cancelled', true,
      'payment_id', p_payment_id,
      'voucher_no', v_payment.voucher_no
    );
  END IF;

  -- Restore bill balances from allocations
  FOR v_alloc IN
    SELECT ppb.bill_id, ppb.adjusted_amount
    FROM public.purchase_payment_bills ppb
    WHERE ppb.payment_id = p_payment_id
  LOOP
    SELECT * INTO v_bill
    FROM public.purchase_bills
    WHERE purchase_bills.id = v_alloc.bill_id
    FOR UPDATE;

    IF v_bill.id IS NOT NULL THEN
      v_new_paid := GREATEST(0, COALESCE(v_bill.paid_amount, 0) - v_alloc.adjusted_amount);
      v_new_balance := GREATEST(0, v_bill.total_amount - v_new_paid);
      IF v_new_paid = 0 THEN
        v_new_status := 'Unpaid';
      ELSE
        v_new_status := 'Partially Paid';
      END IF;

      UPDATE public.purchase_bills
      SET paid_amount = v_new_paid,
          balance_amount = v_new_balance,
          payment_status = v_new_status,
          updated_at = NOW()
      WHERE purchase_bills.id = v_alloc.bill_id;
    END IF;
  END LOOP;

  -- Post Reversing GL Journal Entry (Dr Bank/Cash, Cr Accounts Payable)
  SELECT id INTO v_ap_account_id
  FROM public.accounts
  WHERE (organisation_id = v_payment.organisation_id OR company_id = v_payment.organisation_id)
    AND account_code = '2100'
  LIMIT 1;

  IF LOWER(TRIM(COALESCE(v_payment.payment_mode, ''))) = 'cash' THEN
    SELECT id INTO v_bank_account_id
    FROM public.accounts
    WHERE (organisation_id = v_payment.organisation_id OR company_id = v_payment.organisation_id)
      AND account_code = '1300'
    LIMIT 1;
  ELSE
    SELECT id INTO v_bank_account_id
    FROM public.accounts
    WHERE (organisation_id = v_payment.organisation_id OR company_id = v_payment.organisation_id)
      AND account_code = '1200'
    LIMIT 1;
  END IF;

  IF v_ap_account_id IS NOT NULL AND v_bank_account_id IS NOT NULL AND v_payment.amount > 0 THEN
    INSERT INTO public.journal_entries (
      company_id, voucher_no, voucher_date, voucher_type,
      narration, status, created_by
    ) VALUES (
      v_payment.organisation_id,
      'REV-' || COALESCE(v_payment.voucher_no, v_payment.id::TEXT),
      CURRENT_DATE,
      'Payment',
      'Reversal of Vendor Payment ' || COALESCE(v_payment.voucher_no, '') || COALESCE(' (' || p_reason || ')', ''),
      'Posted',
      auth.uid()
    ) RETURNING id INTO v_journal_id;

    INSERT INTO public.journal_entry_lines (
      journal_id, account_id, party_type, party_id, debit, credit, narration
    ) VALUES (
      v_journal_id, v_bank_account_id, 'vendor', v_payment.vendor_id, v_payment.amount, 0.00, 'Reversal of Bank/Cash Disbursement'
    );

    INSERT INTO public.journal_entry_lines (
      journal_id, account_id, party_type, party_id, debit, credit, narration
    ) VALUES (
      v_journal_id, v_ap_account_id, 'vendor', v_payment.vendor_id, 0.00, v_payment.amount, 'Reversal of AP Settlement'
    );
  END IF;

  -- Mark payment cancelled
  UPDATE public.purchase_payments
  SET approval_status = 'Cancelled',
      workflow_step = 'cancelled',
      is_deleted = true,
      deletion_reason = p_reason,
      deleted_at = NOW(),
      deleted_by = auth.uid(),
      updated_at = NOW()
  WHERE id = p_payment_id;

  PERFORM public.recalc_vendor_balance(v_payment.vendor_id, v_payment.organisation_id);

  RETURN jsonb_build_object(
    'status', 'success',
    'payment_id', p_payment_id,
    'voucher_no', v_payment.voucher_no,
    'doc_status', 'cancelled',
    'journal_id', v_journal_id
  );
END;

