DECLARE
  v_res JSONB;
  v_errs JSONB := '{}'::JSONB;
BEGIN
  BEGIN
    v_res := public.run_p0_3_forensic_verification_suite();
    v_errs := v_errs || jsonb_build_object('p0_3', v_res->>'verdict');
  EXCEPTION WHEN OTHERS THEN
    v_errs := v_errs || jsonb_build_object('p0_3_err', SQLERRM);
  END;

  BEGIN
    v_res := public.run_p0_4_forensic_verification_suite();
    v_errs := v_errs || jsonb_build_object('p0_4', v_res->>'verdict');
  EXCEPTION WHEN OTHERS THEN
    v_errs := v_errs || jsonb_build_object('p0_4_err', SQLERRM);
  END;

  BEGIN
    v_res := public.run_p0_5_purchase_forensic_suite();
    v_errs := v_errs || jsonb_build_object('p0_5', v_res->>'verdict');
  EXCEPTION WHEN OTHERS THEN
    v_errs := v_errs || jsonb_build_object('p0_5_err', SQLERRM);
  END;

  BEGIN
    v_res := public.run_p0_6_sales_forensic_suite();
    v_errs := v_errs || jsonb_build_object('p0_6', v_res->>'verdict');
  EXCEPTION WHEN OTHERS THEN
    v_errs := v_errs || jsonb_build_object('p0_6_err', SQLERRM);
  END;

  RETURN v_errs;
END

