DECLARE
  v_org UUID;
  v_status TEXT;
  v_row RECORD;
  v_available NUMERIC;
  v_picked INTEGER := 0;
  v_skipped INTEGER := 0;
BEGIN
  SELECT organisation_id, status INTO v_org, v_status
    FROM warehouse_pick_lists WHERE id = p_pick_list_id;

  IF v_org IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Pick list not found');
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM user_organisations
     WHERE organisation_id = v_org AND user_id = auth.uid() AND status = 'active'
  ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Not a member of this organisation');
  END IF;
  IF v_status NOT IN ('queued','picking') THEN
    RETURN jsonb_build_object('ok', false, 'error',
      'Cannot complete a pick list in status ' || v_status);
  END IF;

  FOR v_row IN
    SELECT i.id, i.item_id, i.source_bin_id, i.quantity_requested, i.quantity_picked, i.status
      FROM warehouse_pick_list_items i
     WHERE i.pick_list_id = p_pick_list_id
  LOOP
    -- Already-picked lines were completed by a prior partial run — skip.
    IF v_row.status = 'picked' THEN
      v_skipped := v_skipped + 1;
      CONTINUE;
    END IF;

    IF COALESCE(v_row.quantity_picked, 0) <= 0 THEN
      RETURN jsonb_build_object('ok', false, 'error',
        'Line ' || v_row.id || ' has no picked quantity — set quantity_picked before completing');
    END IF;

    -- Source bin must belong to the caller's org.
    IF NOT EXISTS (
      SELECT 1 FROM warehouse_bins
       WHERE id = v_row.source_bin_id AND organisation_id = v_org AND deleted_at IS NULL
    ) THEN
      RETURN jsonb_build_object('ok', false, 'error', 'Source bin not found in this organisation');
    END IF;

    -- Pick validation: unreserved stock must cover the pick (TAD §5.11).
    SELECT COALESCE(SUM(bi.quantity), 0) - COALESCE(b.reserved_quantity, 0) INTO v_available
      FROM warehouse_bins b
      LEFT JOIN warehouse_bin_items bi
        ON bi.bin_id = b.id AND bi.item_id IS NOT DISTINCT FROM v_row.item_id AND bi.deleted_at IS NULL
     WHERE b.id = v_row.source_bin_id;
    IF v_available < v_row.quantity_picked THEN
      RETURN jsonb_build_object('ok', false, 'error',
        'Insufficient unreserved stock for line ' || v_row.id || ': ' ||
        v_available || ' < ' || v_row.quantity_picked);
    END IF;

    -- Movement Engine: decrement the source bin.
    UPDATE warehouse_bin_items
       SET quantity = GREATEST(0, quantity - v_row.quantity_picked), updated_at = now()
     WHERE bin_id = v_row.source_bin_id AND item_id IS NOT DISTINCT FROM v_row.item_id AND deleted_at IS NULL;
    UPDATE warehouse_bin_items
       SET deleted_at = now(), quantity = 0, updated_at = now()
     WHERE bin_id = v_row.source_bin_id AND item_id IS NOT DISTINCT FROM v_row.item_id
       AND quantity <= 0 AND deleted_at IS NULL;

    -- Audit row — source-side negative, reversal-compatible.
    INSERT INTO warehouse_movements
      (organisation_id, movement_type, reference_type, reference_id, item_id,
       source_bin_id, quantity, operator_id, device, remarks)
    VALUES
      (v_org, 'pick', 'picking', p_pick_list_id::TEXT, v_row.item_id,
       v_row.source_bin_id, -v_row.quantity_picked, p_operator_id, 'web',
       'Picking task ' || p_pick_list_id);

    UPDATE warehouse_pick_list_items
       SET status = 'picked', picked_by = p_operator_id, picked_at = now(), updated_at = now()
     WHERE id = v_row.id;
    v_picked := v_picked + 1;
  END LOOP;

  UPDATE warehouse_pick_lists
     SET status = 'completed', completed_at = now(), updated_at = now()
   WHERE id = p_pick_list_id;

  RETURN jsonb_build_object('ok', true, 'pick_list_id', p_pick_list_id,
                            'picked', v_picked, 'skipped', v_skipped);
END;

DECLARE
  v_stage_1 INTEGER;
  v_stage_2 INTEGER;
  v_stage_3 INTEGER;
  v_stage_4 INTEGER;
  v_age_days NUMERIC;
  v_stage SMALLINT := 0;
BEGIN
  IF p_next_action_at IS NULL THEN
    RETURN 0;
  END IF;

  v_age_days := EXTRACT(EPOCH FROM (p_now - p_next_action_at)) / 86400.0;

  IF v_age_days <= 0 THEN
    RETURN 0;
  END IF;

  SELECT stage_1_days, stage_2_days, stage_3_days, stage_4_days
    INTO v_stage_1, v_stage_2, v_stage_3, v_stage_4
  FROM public.cadence_rules
  WHERE organisation_id = p_organisation_id
    AND applies_to = p_applies_to
    AND is_active = true
  ORDER BY (applies_to = p_applies_to) DESC
  LIMIT 1;

  IF v_stage_1 IS NULL THEN
    -- Fallback if no rule defined
    v_stage_1 := 1; v_stage_2 := 3; v_stage_3 := 7; v_stage_4 := 15;
  END IF;

  IF v_age_days >= v_stage_4 THEN v_stage := 4;
  ELSIF v_age_days >= v_stage_3 THEN v_stage := 3;
  ELSIF v_age_days >= v_stage_2 THEN v_stage := 2;
  ELSIF v_age_days >= v_stage_1 THEN v_stage := 1;
  ELSE v_stage := 0;
  END IF;

  RETURN v_stage;
END;

DECLARE
  v_proforma RECORD; v_item RECORD; v_invoice_id UUID; v_finalize_res JSONB; v_creator_id UUID;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF NOT public.user_can_access_org(p_organisation_id) THEN RAISE EXCEPTION 'Unauthorized organization access'; END IF;

  SELECT id INTO v_creator_id FROM public.user_profiles WHERE user_id = auth.uid() OR id = auth.uid() LIMIT 1;

  SELECT * INTO v_proforma FROM public.proforma_invoices WHERE id = p_proforma_id AND organisation_id = p_organisation_id FOR UPDATE;
  IF v_proforma IS NULL THEN RAISE EXCEPTION 'Proforma invoice not found or does not belong to organization'; END IF;
  IF v_proforma.converted_invoice_id IS NOT NULL THEN
    RETURN jsonb_build_object('status', 'already_converted', 'proforma_id', p_proforma_id, 'converted_invoice_id', v_proforma.converted_invoice_id);
  END IF;

  -- Insert draft Sales Invoice
  INSERT INTO public.invoices (
    organisation_id, client_id, status, invoice_date, proforma_id, po_number, po_date,
    template_type, mode, source_type, subtotal, cgst, sgst, igst, total
  ) VALUES (
    p_organisation_id, v_proforma.client_id, 'draft', CURRENT_DATE, p_proforma_id, v_proforma.po_number, v_proforma.po_date,
    'standard', 'itemized', 'quotation', 0, 0, 0, 0, 0
  ) RETURNING id INTO v_invoice_id;

  FOR v_item IN SELECT item_id, description, qty, rate, discount_percent, tax_percent FROM public.proforma_items WHERE proforma_id = p_proforma_id LOOP
    INSERT INTO public.invoice_items (
      invoice_id, organisation_id, description, qty, rate, amount, meta_json
    ) VALUES (
      v_invoice_id, p_organisation_id, COALESCE(v_item.description, 'Line Item'), v_item.qty, v_item.rate, ROUND((v_item.qty * v_item.rate)::NUMERIC, 2), jsonb_build_object('tax_percent', v_item.tax_percent)
    );
  END LOOP;

  v_finalize_res := public.finalize_sales_invoice(v_invoice_id, p_organisation_id);
  UPDATE public.proforma_invoices SET converted_invoice_id = v_invoice_id, status = 'accepted', updated_at = NOW() WHERE id = p_proforma_id;

  RETURN jsonb_build_object('status', 'success', 'proforma_id', p_proforma_id, 'converted_invoice_id', v_invoice_id, 'finalize_details', v_finalize_res);
END;

DECLARE
  v_emp_name TEXT;
  v_existing_id UUID;
  v_tx_no TEXT;
  v_ae_id UUID;
  v_valid_payout_method TEXT;
  v_valid_request_type TEXT;
BEGIN
  IF auth.uid() IS NOT NULL AND NOT public.user_can_access_org(p_organisation_id) THEN
    RAISE EXCEPTION 'Unauthorized organization access';
  END IF;

  IF p_amount <= 0 THEN
    RAISE EXCEPTION 'Advance/Expense amount must be greater than zero';
  END IF;

  IF p_type NOT IN ('ADVANCE', 'EXPENSE', 'REIMBURSEMENT') THEN
    RAISE EXCEPTION 'Invalid advance/expense type: %', p_type;
  END IF;

  -- Validate employee belongs to organization
  IF p_employee_id IS NOT NULL THEN
    IF NOT EXISTS (
      SELECT 1 FROM public.user_profiles WHERE id = p_employee_id AND organisation_id = p_organisation_id
      UNION
      SELECT 1 FROM public.employees WHERE id = p_employee_id AND organisation_id = p_organisation_id
    ) THEN
      RAISE EXCEPTION 'Employee does not belong to the specified organisation';
    END IF;
  END IF;

  v_valid_payout_method := CASE WHEN p_payout_method IN ('IMMEDIATE', 'WITH_SALARY') THEN p_payout_method ELSE 'IMMEDIATE' END;
  v_valid_request_type  := CASE WHEN p_request_type IN ('REIMBURSEMENT', 'PRE_APPROVAL') THEN p_request_type ELSE 'PRE_APPROVAL' END;

  IF p_idempotency_key IS NOT NULL THEN
    SELECT id INTO v_existing_id
    FROM public.advances_expenses
    WHERE organisation_id = p_organisation_id AND idempotency_key = p_idempotency_key;

    IF v_existing_id IS NOT NULL THEN
      SELECT transaction_no, amount, status
      INTO v_tx_no, p_amount, p_type
      FROM public.advances_expenses WHERE id = v_existing_id;

      RETURN jsonb_build_object(
        'status', 'success',
        'idempotent_replayed', true,
        'ae_id', v_existing_id,
        'transaction_no', v_tx_no,
        'amount', p_amount,
        'doc_status', p_type
      );
    END IF;
  END IF;

  SELECT full_name INTO v_emp_name
  FROM public.user_profiles
  WHERE id = p_employee_id OR user_id = p_employee_id
  LIMIT 1;

  IF v_emp_name IS NULL THEN
    SELECT name INTO v_emp_name
