DECLARE
  v_wo RECORD;
  v_existing_id UUID;
  v_sheet_id UUID;
  v_item JSONB;
  v_contract_qty NUMERIC(15,4);
  v_actual_qty NUMERIC(15,4);
  v_rate NUMERIC(15,2);
  v_contract_val NUMERIC(15,2) := 0;
  v_actual_val NUMERIC(15,2) := 0;
  v_diff_val NUMERIC(15,2) := 0;
  v_sheet_no TEXT;
BEGIN
  IF auth.uid() IS NOT NULL AND NOT public.user_can_access_org(p_organisation_id) THEN
    RAISE EXCEPTION 'Unauthorized organization access';
  END IF;

  IF p_idempotency_key IS NOT NULL THEN
    SELECT id INTO v_existing_id
    FROM public.subcontractor_measurement_sheets
    WHERE organisation_id = p_organisation_id AND idempotency_key = p_idempotency_key;

    IF v_existing_id IS NOT NULL THEN
      SELECT sheet_no, contract_value, actual_value, difference
      INTO v_sheet_no, v_contract_val, v_actual_val, v_diff_val
      FROM public.subcontractor_measurement_sheets WHERE id = v_existing_id;

      RETURN jsonb_build_object(
        'status', 'success',
        'idempotent_replayed', true,
        'sheet_id', v_existing_id,
        'sheet_no', v_sheet_no,
        'contract_value', v_contract_val,
        'actual_value', v_actual_val,
        'difference', v_diff_val
      );
    END IF;
  END IF;

  SELECT * INTO v_wo
  FROM public.subcontractor_work_orders
  WHERE id = p_work_order_id AND organisation_id = p_organisation_id
  FOR UPDATE;

  IF v_wo IS NULL THEN
    RAISE EXCEPTION 'Work order not found or does not belong to organization';
  END IF;

  -- Authoritatively calculate totals from line items
  IF p_line_items IS NOT NULL AND jsonb_typeof(p_line_items) = 'array' THEN
    FOR v_item IN SELECT * FROM jsonb_array_elements(p_line_items) LOOP
      v_contract_qty := COALESCE((v_item->>'contract_qty')::NUMERIC, (v_item->>'contractQty')::NUMERIC, 0);
      v_actual_qty   := COALESCE((v_item->>'actual_qty')::NUMERIC, (v_item->>'actualQty')::NUMERIC, 0);
      v_rate         := COALESCE((v_item->>'rate')::NUMERIC, 0);

      IF v_contract_qty < 0 OR v_actual_qty < 0 OR v_rate < 0 THEN
        RAISE EXCEPTION 'Quantities and rates in measurement sheet cannot be negative';
      END IF;

      v_contract_val := v_contract_val + ROUND((v_contract_qty * v_rate)::NUMERIC, 2);
      v_actual_val   := v_actual_val + ROUND((v_actual_qty * v_rate)::NUMERIC, 2);
    END LOOP;
  END IF;

  v_diff_val := v_actual_val - v_contract_val;
  v_sheet_no := COALESCE(NULLIF(TRIM(p_sheet_no), ''), 'MS-' || TO_CHAR(NOW(), 'YYYYMMDD-HH24MISS'));

  INSERT INTO public.subcontractor_measurement_sheets (
    organisation_id, work_order_id, sheet_no, measurement_date,
    measured_by, description, line_items, contract_value, actual_value,
    difference, amendment_created, status, notes, idempotency_key, created_by
  ) VALUES (
    p_organisation_id, p_work_order_id, v_sheet_no, p_measurement_date,
    p_measured_by, p_description, p_line_items, v_contract_val, v_actual_val,
    v_diff_val, false, 'Draft', p_notes, p_idempotency_key, COALESCE(auth.uid(), v_wo.subcontractor_id)
  ) RETURNING id INTO v_sheet_id;

  RETURN jsonb_build_object(
    'status', 'success',
    'sheet_id', v_sheet_id,
    'sheet_no', v_sheet_no,
    'contract_value', v_contract_val,
    'actual_value', v_actual_val,
    'difference', v_diff_val,
    'doc_status', 'Draft'
  );
END;

DECLARE
