DECLARE
  v_client RECORD;
  v_org RECORD;
  v_existing_inv RECORD;
  v_effective_idempotency_key TEXT;
  v_invoice_id UUID;
  v_invoice_no TEXT;
  v_invoice_date DATE;
  v_status TEXT;
  v_source_type TEXT;
  v_item RECORD;
  v_line_qty NUMERIC(15,3);
  v_line_rate NUMERIC(15,2);
  v_line_tax_pct NUMERIC(5,2);
  v_line_taxable NUMERIC(15,2);
  v_line_cgst NUMERIC(15,2) := 0;
  v_line_sgst NUMERIC(15,2) := 0;
  v_line_igst NUMERIC(15,2) := 0;

  v_subtotal NUMERIC(15,2) := 0;
  v_total_cgst NUMERIC(15,2) := 0;
  v_total_sgst NUMERIC(15,2) := 0;
  v_total_igst NUMERIC(15,2) := 0;
  v_grand_total NUMERIC(15,2) := 0;

  v_is_intrastate BOOLEAN := TRUE;
  v_ar_account_id UUID;
  v_sales_account_id UUID;
  v_cgst_account_id UUID;
  v_sgst_account_id UUID;
  v_igst_account_id UUID;
  v_journal_id UUID;
  v_has_insufficient BOOLEAN := FALSE;
  r_deduct RECORD;
BEGIN
  IF auth.uid() IS NOT NULL AND NOT public.user_can_access_org(p_organisation_id) THEN
    RAISE EXCEPTION 'Unauthorized organization access';
  END IF;

  IF p_client_id IS NULL THEN
    RAISE EXCEPTION 'Client ID is required';
  END IF;

  SELECT * INTO v_client
  FROM public.clients
  WHERE id = p_client_id AND (organisation_id = p_organisation_id OR org_id = p_organisation_id);

  IF v_client IS NULL THEN
    RAISE EXCEPTION 'Client not found or does not belong to organization';
  END IF;

  v_effective_idempotency_key := NULLIF(TRIM(p_idempotency_key), '');
  IF v_effective_idempotency_key IS NOT NULL THEN
    SELECT id, invoice_no, total, status INTO v_existing_inv
    FROM public.invoices
    WHERE (organisation_id = p_organisation_id OR org_id = p_organisation_id)
      AND idempotency_key = v_effective_idempotency_key
      AND status != 'cancelled'
    LIMIT 1;

    IF v_existing_inv.id IS NOT NULL THEN
      SELECT id INTO v_journal_id
      FROM public.journal_entries
      WHERE (company_id = p_organisation_id OR organisation_id = p_organisation_id)
        AND voucher_no = v_existing_inv.invoice_no
        AND voucher_type = 'Sales'
      LIMIT 1;

      RETURN jsonb_build_object(
        'status', 'success',
        'invoice_id', v_existing_inv.id,
        'invoice_no', v_existing_inv.invoice_no,
        'total', v_existing_inv.total,
        'doc_status', v_existing_inv.status,
        'journal_id', v_journal_id,
        'idempotent_replayed', true
      );
    END IF;
  END IF;

  IF p_items IS NULL OR jsonb_array_length(p_items) = 0 THEN
    RAISE EXCEPTION 'Invoice must contain at least one line item';
  END IF;

  -- GST Jurisdiction
  SELECT * INTO v_org FROM public.organisations WHERE id = p_organisation_id;
  IF v_client.state IS NOT NULL AND v_org.state IS NOT NULL AND LOWER(TRIM(v_client.state)) != LOWER(TRIM(v_org.state)) THEN
    v_is_intrastate := FALSE;
  END IF;

  -- Calculate Line Items & Totals
  FOR v_item IN SELECT * FROM jsonb_to_recordset(p_items) AS x(
    item_id uuid, material_id uuid, variant_id uuid, warehouse_id uuid,
    description text, hsn_code text, qty numeric, rate numeric, tax_percent numeric, is_service boolean
  ) LOOP
    v_line_qty := COALESCE(v_item.qty, 0);
    v_line_rate := COALESCE(v_item.rate, 0);
    v_line_tax_pct := COALESCE(v_item.tax_percent, 18.0);

    IF v_line_qty <= 0 OR v_line_rate < 0 THEN
      RAISE EXCEPTION 'Line item quantity and rate must be valid non-negative numbers';
    END IF;

    v_line_taxable := ROUND(v_line_qty * v_line_rate, 2);

    IF v_is_intrastate THEN
      v_line_cgst := ROUND(v_line_taxable * (v_line_tax_pct / 200.0), 2);
      v_line_sgst := ROUND(v_line_taxable * (v_line_tax_pct / 200.0), 2);
      v_line_igst := 0;
    ELSE
      v_line_igst := ROUND(v_line_taxable * (v_line_tax_pct / 100.0), 2);
      v_line_cgst := 0;
      v_line_sgst := 0;
    END IF;

    v_subtotal := v_subtotal + v_line_taxable;
    v_total_cgst := v_total_cgst + v_line_cgst;
    v_total_sgst := v_total_sgst + v_line_sgst;
    v_total_igst := v_total_igst + v_line_igst;
  END LOOP;

  v_grand_total := v_subtotal + v_total_cgst + v_total_sgst + v_total_igst;
  v_invoice_date := COALESCE((NULLIF(p_invoice_data->>'invoice_date', ''))::DATE, CURRENT_DATE);
  v_invoice_no := NULLIF(TRIM(p_invoice_data->>'invoice_no'), '');

  IF v_invoice_no IS NULL THEN
    v_invoice_no := 'INV-' || TO_CHAR(CURRENT_DATE, 'YYYY') || '-' || LPAD((
      SELECT COUNT(*) + 1 FROM public.invoices WHERE organisation_id = p_organisation_id OR org_id = p_organisation_id
    )::TEXT, 4, '0');
  END IF;

  v_source_type := CASE 
    WHEN LOWER(COALESCE(p_invoice_data->>'source_type', 'direct')) IN ('dc', 'challan', 'delivery_challan') THEN 'challan'
    WHEN LOWER(COALESCE(p_invoice_data->>'source_type', 'direct')) IN ('quote', 'quotation') THEN 'quotation'
    WHEN LOWER(COALESCE(p_invoice_data->>'source_type', 'direct')) IN ('po', 'purchase_order') THEN 'po'
