  v_to_warehouse_id := (NULLIF(p_transfer_data->>'to_warehouse_id', ''))::UUID;

  IF v_from_warehouse_id IS NULL THEN
    v_from_warehouse_id := (NULLIF(p_transfer_data->>'source_warehouse_id', ''))::UUID;
  END IF;
  IF v_to_warehouse_id IS NULL THEN
    v_to_warehouse_id := (NULLIF(p_transfer_data->>'destination_warehouse_id', ''))::UUID;
  END IF;

  IF v_from_warehouse_id IS NULL THEN RAISE EXCEPTION 'Source warehouse (from_warehouse_id) is required'; END IF;
  IF v_to_warehouse_id IS NULL THEN RAISE EXCEPTION 'Destination warehouse (to_warehouse_id) is required'; END IF;
  IF v_from_warehouse_id = v_to_warehouse_id THEN RAISE EXCEPTION 'Source and destination warehouses cannot be the same'; END IF;

  v_effective_idempotency_key := NULLIF(TRIM(p_idempotency_key), '');
