    SELECT id, transfer_no, status INTO v_existing_transfer
    FROM public.stock_transfers
    WHERE organisation_id = v_org_id AND idempotency_key = v_effective_idempotency_key
    LIMIT 1;

    IF v_existing_transfer.id IS NOT NULL THEN
      RETURN jsonb_build_object(
        'status', 'success',
        'transfer_id', v_existing_transfer.id,
        'transfer_no', v_existing_transfer.transfer_no,
        'doc_status', v_existing_transfer.status,
        'idempotent_replayed', true
      );
    END IF;
  END IF;

  IF p_items IS NULL OR jsonb_array_length(p_items) = 0 THEN
    RAISE EXCEPTION 'Stock Transfer must contain at least one item';
