DECLARE
  v_entry RECORD;
  v_entry_item RECORD;
  v_main_store_id UUID;
  v_wip_store_id UUID;
  v_fg_store_id UUID;
  v_stock RECORD;
  v_job_card_id UUID;
  v_product_id UUID;
  v_consumed_wastage NUMERIC;
  v_remaining_qty NUMERIC;
  v_planned_qty NUMERIC;
BEGIN
  SELECT * INTO v_entry
  FROM production_entries
  WHERE id = p_entry_id;

  IF v_entry.id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Entry not found');
  END IF;

  IF v_entry.organisation_id != p_org_id THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Organisation mismatch');
  END IF;

  v_job_card_id := v_entry.job_card_id;

  IF NOT EXISTS (
    SELECT 1 FROM user_organisations
    WHERE organisation_id = p_org_id AND user_id = auth.uid() AND status = 'active'
  ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Not a member of this organisation');
  END IF;

  SELECT id INTO v_main_store_id
  FROM warehouses
  WHERE organisation_id = p_org_id AND warehouse_purpose = 'main' AND is_active = true
  LIMIT 1;

  IF v_main_store_id IS NULL THEN
    SELECT id INTO v_main_store_id
    FROM warehouses
    WHERE organisation_id = p_org_id AND is_default = true AND is_active = true
    LIMIT 1;
  END IF;

  SELECT id INTO v_wip_store_id
  FROM warehouses
  WHERE organisation_id = p_org_id AND warehouse_purpose = 'wip' AND is_active = true
  LIMIT 1;

  IF v_wip_store_id IS NULL THEN
    SELECT id INTO v_wip_store_id
    FROM warehouses
    WHERE organisation_id = p_org_id AND is_active = true AND id != v_main_store_id
    LIMIT 1;
  END IF;

  SELECT id INTO v_fg_store_id
  FROM warehouses
  WHERE organisation_id = p_org_id AND warehouse_purpose = 'fg' AND is_active = true
  LIMIT 1;

  IF v_fg_store_id IS NULL THEN
    SELECT id INTO v_fg_store_id
    FROM warehouses
    WHERE organisation_id = p_org_id AND is_active = true
      AND id != v_main_store_id AND id != v_wip_store_id
    LIMIT 1;
  END IF;

  IF v_main_store_id IS NULL OR v_wip_store_id IS NULL OR v_fg_store_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Required warehouses (Main Store / WIP / FG Store) not found');
  END IF;

  IF v_entry.actual_qty > 0 THEN
    SELECT bom_headers.product_id INTO v_product_id
    FROM job_cards
    JOIN bom_headers ON bom_headers.id = job_cards.bom_id
    WHERE job_cards.id = v_job_card_id;

    IF v_product_id IS NOT NULL THEN
      SELECT id, current_stock INTO v_stock
      FROM item_stock
      WHERE item_id = v_product_id
        AND warehouse_id = v_fg_store_id
        AND organisation_id = p_org_id
      FOR UPDATE;

      IF v_stock.id IS NOT NULL THEN
        UPDATE item_stock
        SET current_stock = GREATEST(0, current_stock - v_entry.actual_qty),
            updated_at = NOW()
        WHERE id = v_stock.id;
      END IF;
    END IF;
  END IF;

  FOR v_entry_item IN
    SELECT * FROM production_entry_items
    WHERE production_entry_id = p_entry_id
  LOOP
    v_consumed_wastage := COALESCE(v_entry_item.consumed_qty, 0) + COALESCE(v_entry_item.wastage_qty, 0);

    IF v_consumed_wastage > 0 THEN
      SELECT id, current_stock INTO v_stock
      FROM item_stock
      WHERE item_id = v_entry_item.material_id
        AND warehouse_id = v_wip_store_id
        AND organisation_id = p_org_id
      FOR UPDATE;

      IF v_stock.id IS NOT NULL THEN
        UPDATE item_stock
        SET current_stock = current_stock + v_consumed_wastage,
            updated_at = NOW()
        WHERE id = v_stock.id;
      END IF;
    END IF;

    IF COALESCE(v_entry_item.return_qty, 0) > 0 THEN
      SELECT id, current_stock INTO v_stock
      FROM item_stock
      WHERE item_id = v_entry_item.material_id
        AND warehouse_id = v_main_store_id
        AND organisation_id = p_org_id
      FOR UPDATE;

      IF v_stock.id IS NOT NULL THEN
        UPDATE item_stock
        SET current_stock = GREATEST(0, current_stock - v_entry_item.return_qty),
            updated_at = NOW()
        WHERE id = v_stock.id;
      END IF;
    END IF;

    UPDATE job_card_materials
    SET consumed_qty = GREATEST(0, COALESCE(consumed_qty, 0) - COALESCE(v_entry_item.consumed_qty, 0)),
        wastage_qty = GREATEST(0, COALESCE(wastage_qty, 0) - COALESCE(v_entry_item.wastage_qty, 0)),
        return_qty = GREATEST(0, COALESCE(return_qty, 0) - COALESCE(v_entry_item.return_qty, 0)),
        updated_at = NOW()
    WHERE id = v_entry_item.job_card_material_id;
  END LOOP;

  DELETE FROM production_entry_items WHERE production_entry_id = p_entry_id;
  DELETE FROM production_entries WHERE id = p_entry_id;

  SELECT COALESCE(SUM(actual_qty), 0) INTO v_remaining_qty
  FROM production_entries
  WHERE job_card_id = v_job_card_id;

  SELECT planned_qty INTO v_planned_qty
  FROM job_cards
  WHERE id = v_job_card_id;

  IF v_remaining_qty >= v_planned_qty THEN
    UPDATE job_cards

DECLARE
  v_transfer RECORD;
  v_org_id UUID;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;

  SELECT * INTO v_transfer
  FROM public.stock_transfers
  WHERE id = p_transfer_id;

  IF v_transfer IS NULL THEN
    RETURN jsonb_build_object('status', 'success', 'deleted', false);
  END IF;

  v_org_id := v_transfer.organisation_id;
  IF NOT public.user_can_access_org(v_org_id) THEN
    RAISE EXCEPTION 'Unauthorized organization access';
  END IF;

  IF UPPER(COALESCE(v_transfer.status, 'DRAFT')) != 'DRAFT' THEN
    RAISE EXCEPTION 'Cannot delete Stock Transfer % with status %. Only DRAFT transfers can be deleted.', 
      v_transfer.transfer_no, v_transfer.status;
  END IF;

  DELETE FROM public.stock_transfer_items WHERE transfer_id = p_transfer_id;
  DELETE FROM public.stock_transfers WHERE id = p_transfer_id;

  RETURN jsonb_build_object(
    'status', 'success',
    'deleted', true,
    'transfer_id', p_transfer_id
  );
END;

DECLARE
  v_ae RECORD;
  v_float RECORD;
  v_expense_account_id UUID;
  v_advance_account_id UUID;
  v_bank_account_id UUID;
  v_petty_cash_account_id UUID;
  v_journal_id UUID;
  v_ref_no TEXT;
  v_creator_id UUID;
  v_total_debit NUMERIC(15,2);
  v_total_credit NUMERIC(15,2);
BEGIN
  SELECT * INTO v_ae
  FROM public.advances_expenses
  WHERE id = p_ae_id
  FOR UPDATE;

  IF v_ae IS NULL THEN
    RAISE EXCEPTION 'Advance/Expense record not found';
  END IF;

  IF auth.uid() IS NOT NULL AND NOT public.user_can_access_org(v_ae.organisation_id) THEN
    RAISE EXCEPTION 'Unauthorized organization access';
  END IF;

  IF v_ae.status = 'PAID' THEN
    RETURN jsonb_build_object(
      'status', 'success',
      'already_paid', true,
      'ae_id', p_ae_id,
      'transaction_no', v_ae.transaction_no,
      'amount', v_ae.amount
    );
  END IF;

  IF v_ae.status = 'CANCELLED' THEN
    RAISE EXCEPTION 'Cannot disburse a cancelled advance/expense';
  END IF;

  SELECT id INTO v_creator_id
  FROM public.user_profiles WHERE user_id = auth.uid() OR id = auth.uid() LIMIT 1;

  -- GL Account Configuration / Auto-provision
  v_bank_account_id := public.ensure_gl_account_exists(v_ae.organisation_id, '1200', 'Bank Account', 'Asset');
  v_petty_cash_account_id := public.ensure_gl_account_exists(v_ae.organisation_id, '1301', 'Petty Cash Float', 'Asset');
  v_advance_account_id := public.ensure_gl_account_exists(v_ae.organisation_id, '1400', 'Employee Advances', 'Asset');
  v_expense_account_id := public.ensure_gl_account_exists(v_ae.organisation_id, '4100', 'Operational Expenses', 'Expense');

  -- If petty cash float is used, lock float and enforce balance sufficiency
  IF v_ae.float_id IS NOT NULL THEN
    SELECT * INTO v_float
    FROM public.petty_cash_floats
    WHERE id = v_ae.float_id
    FOR UPDATE;

    IF v_float IS NULL THEN
      RAISE EXCEPTION 'Petty cash float record not found';
    END IF;

    IF v_float.current_balance < v_ae.amount THEN
      RAISE EXCEPTION 'Insufficient petty cash float balance (Current: %, Required: %)', v_float.current_balance, v_ae.amount;
    END IF;

    UPDATE public.petty_cash_floats
    SET current_balance = current_balance - v_ae.amount,
        updated_at = NOW()
    WHERE id = v_ae.float_id;
  END IF;

  v_ref_no := COALESCE(p_reference_no, v_ae.transaction_no);

  -- Post Balanced Double-Entry GL Journal
  INSERT INTO public.journal_entries (
    company_id, voucher_no, voucher_date, voucher_type, narration, status, created_by
  ) VALUES (
    v_ae.organisation_id, v_ref_no, CURRENT_DATE, 'Payment',
    'Disbursement of ' || v_ae.type || ' ' || v_ae.transaction_no || ' (' || COALESCE(v_ae.employee_name, 'Employee') || ')',
    'Posted', v_creator_id
  ) RETURNING id INTO v_journal_id;

  -- Debit Line:
  -- Advance -> Dr 1400 (Employee Advance Asset)
  -- Expense/Reimbursement -> Dr 4100 (Expense)
  IF v_ae.type = 'ADVANCE' THEN
    INSERT INTO public.journal_entry_lines (journal_id, account_id, party_type, party_id, debit, credit, narration)
    VALUES (v_journal_id, v_advance_account_id, 'employee', v_ae.employee_id, v_ae.amount, 0.00, 'Employee Advance Disbursement');
  ELSE
    INSERT INTO public.journal_entry_lines (journal_id, account_id, party_type, party_id, debit, credit, narration)
    VALUES (v_journal_id, v_expense_account_id, 'employee', v_ae.employee_id, v_ae.amount, 0.00, 'Operational Expense Settlement');
  END IF;

  -- Credit Line:
  -- If float -> Cr 1301 (Petty Cash Float)
  -- Else -> Cr 1200 (Bank)
  IF v_ae.float_id IS NOT NULL THEN
    INSERT INTO public.journal_entry_lines (journal_id, account_id, party_type, party_id, debit, credit, narration)
    VALUES (v_journal_id, v_petty_cash_account_id, 'employee', v_ae.employee_id, 0.00, v_ae.amount, 'Petty Cash Float Outflow');
  ELSE
    INSERT INTO public.journal_entry_lines (journal_id, account_id, party_type, party_id, debit, credit, narration)
    VALUES (v_journal_id, v_bank_account_id, 'employee', v_ae.employee_id, 0.00, v_ae.amount, 'Bank Account Disbursement');
  END IF;

  SELECT SUM(COALESCE(debit,0)), SUM(COALESCE(credit,0))
  INTO v_total_debit, v_total_credit
  FROM public.journal_entry_lines WHERE journal_id = v_journal_id;

  IF ABS(v_total_debit - v_total_credit) > 0.01 THEN
    RAISE EXCEPTION 'GL imbalance: debit=% credit=%. Transaction rolled back.', v_total_debit, v_total_credit;
  END IF;

  PERFORM set_config('app.allow_financial_mutation', 'true', true);
  UPDATE public.advances_expenses
  SET status = 'PAID',
      journal_id = v_journal_id,
      disbursed_at = NOW(),
      disbursed_by = auth.uid(),
      updated_at = NOW()
  WHERE id = p_ae_id;
  PERFORM set_config('app.allow_financial_mutation', 'false', true);

  RETURN jsonb_build_object(
    'status', 'success',
    'ae_id', p_ae_id,
    'transaction_no', v_ae.transaction_no,
    'amount', v_ae.amount,
    'journal_id', v_journal_id,
    'gl_debit', v_total_debit,
    'gl_credit', v_total_credit,
    'doc_status', 'PAID'
  )

DECLARE
  v_order RECORD;
  v_org_id UUID;
  v_user_id UUID;
  v_fg_wh UUID := p_fg_warehouse_id;
  r_item RECORD;
  v_stock_id UUID;
  v_current_stock NUMERIC;
BEGIN
  v_user_id := auth.uid();

  SELECT * INTO v_order
  FROM public.dispatch_orders
  WHERE id = p_dispatch_order_id
  FOR UPDATE;

  IF v_order IS NULL THEN
    RAISE EXCEPTION 'Dispatch order not found';
  END IF;

  v_org_id := v_order.organisation_id;
  IF v_user_id IS NOT NULL AND NOT public.user_can_access_org(v_org_id) THEN
    RAISE EXCEPTION 'Unauthorized organization access';
  END IF;

  IF v_order.status = 'dispatched' THEN
    RETURN jsonb_build_object('status', 'success', 'already_processed', true, 'dispatch_order_id', p_dispatch_order_id);
  END IF;

  IF v_fg_wh IS NULL THEN
    SELECT id INTO v_fg_wh FROM public.warehouses WHERE organisation_id = v_org_id AND (warehouse_purpose = 'fg' OR warehouse_purpose = 'finished_goods') LIMIT 1;
    IF v_fg_wh IS NULL THEN SELECT id INTO v_fg_wh FROM public.warehouses WHERE organisation_id = v_org_id AND (warehouse_purpose = 'main' OR is_default = TRUE) LIMIT 1; END IF;
  END IF;

  IF v_fg_wh IS NULL THEN
    RAISE EXCEPTION 'Finished Goods warehouse not found';
  END IF;

  IF p_items IS NOT NULL AND jsonb_array_length(p_items) > 0 THEN
    FOR r_item IN SELECT * FROM jsonb_to_recordset(p_items) AS x(
      material_id uuid,
      variant_id uuid,
      dispatched_qty numeric
    )
    LOOP
      IF r_item.material_id IS NOT NULL AND r_item.dispatched_qty > 0 THEN
        SELECT id, current_stock INTO v_stock_id, v_current_stock
        FROM public.item_stock
        WHERE item_id = r_item.material_id
          AND warehouse_id = v_fg_wh
          AND ((r_item.variant_id IS NULL AND company_variant_id IS NULL) OR company_variant_id = r_item.variant_id)
        FOR UPDATE;

        IF v_stock_id IS NULL OR v_current_stock < r_item.dispatched_qty THEN
          RAISE EXCEPTION 'Insufficient stock in Finished Goods Warehouse for material %: available %, requested %',
            r_item.material_id, COALESCE(v_current_stock, 0), r_item.dispatched_qty;
        END IF;

        UPDATE public.item_stock
        SET current_stock = current_stock - r_item.dispatched_qty, updated_at = NOW()
        WHERE id = v_stock_id;

        INSERT INTO public.material_logs (
          organisation_id, item_id, variant_id,
          qty_received, qty_used, type, invoice_number, received_by, remarks, created_at
        ) VALUES (
          v_org_id, r_item.material_id, r_item.variant_id,
          0, r_item.dispatched_qty, 'OUT', v_order.dispatch_no, v_user_id,
          'Manufacturing Dispatch: ' || COALESCE(v_order.dispatch_no, v_order.id::TEXT), NOW()
        );
      END IF;
    END LOOP;
  END IF;

  UPDATE public.dispatch_orders
  SET status = 'dispatched', actual_dispatch_date = CURRENT_DATE, updated_at = NOW()
  WHERE id = p_dispatch_order_id;

  RETURN jsonb_build_object('status', 'success', 'dispatch_order_id', p_dispatch_order_id);
END;

DECLARE
  v_account_id UUID;
  v_typed_root public.account_root_type;
BEGIN
  SELECT id INTO v_account_id
  FROM public.accounts
  WHERE (organisation_id = p_organisation_id OR company_id = p_organisation_id)
    AND account_code = p_account_code
  LIMIT 1;

  IF v_account_id IS NULL THEN
    v_typed_root := p_root_type::public.account_root_type;
    INSERT INTO public.accounts (
      organisation_id, company_id, account_code, name, root_type, is_group
    ) VALUES (
      p_organisation_id, p_organisation_id, p_account_code, p_name, v_typed_root, false
    ) RETURNING id INTO v_account_id;
  END IF;

  RETURN v_account_id;
END;

DECLARE
  v_given_org_id UUID;
  v_client_org_id UUID;
  v_json JSONB;
BEGIN
  v_json := to_jsonb(NEW);
  v_given_org_id := COALESCE((v_json->>'org_id')::UUID, (v_json->>'organisation_id')::UUID);

  IF v_given_org_id IS NULL THEN
    RAISE EXCEPTION 'organisation_id / org_id is required.';
  END IF;

  IF NEW.client_id IS NULL THEN
    RAISE EXCEPTION 'client_id is required.';
  END IF;

  SELECT COALESCE(c.organisation_id, c.org_id) INTO v_client_org_id
  FROM public.clients c
  WHERE c.id = NEW.client_id
  LIMIT 1;

  IF v_client_org_id IS NULL THEN
    RAISE EXCEPTION 'Selected client is not linked to any organisation.';
  END IF;

  IF v_client_org_id <> v_given_org_id THEN
    RAISE EXCEPTION 'Selected client does not belong to the provided organisation.';
  END IF;

  RETURN NEW;
END;

DECLARE
  v_org UUID;
  v_item_id UUID;
  v_qty NUMERIC;
  v_src UUID;
  v_status TEXT;
  v_reserved NUMERIC;
  v_bin_reserved NUMERIC;
BEGIN
  SELECT organisation_id, item_id, quantity, source_bin_id, status, reserved_qty
    INTO v_org, v_item_id, v_qty, v_src, v_status, v_reserved
    FROM warehouse_dispatches WHERE id = p_dispatch_id;

  IF v_org IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Dispatch not found');
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM user_organisations
     WHERE organisation_id = v_org AND user_id = auth.uid() AND status = 'active'
  ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Not a member of this organisation');
  END IF;
  -- TAD §3.13: Loading must precede Shipment Confirmation. Only a LOADED
  -- dispatch may execute (movement posting) — matches the UI lifecycle
  -- (Ship & Complete is only rendered at status 'loaded').
  IF v_status <> 'loaded' THEN
    RETURN jsonb_build_object('ok', false, 'error',
      'Cannot dispatch from status ' || v_status || ' — must be loaded');
  END IF;

  -- Bin must belong to the org. COALESCE + NOT FOUND: a bin whose
  -- reserved_quantity is NULL (never reserved) is still a valid source bin.
  SELECT COALESCE(reserved_quantity, 0) INTO v_bin_reserved
    FROM warehouse_bins WHERE id = v_src AND organisation_id = v_org AND deleted_at IS NULL;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Source bin not found in this organisation');
  END IF;

  -- Decrement the source bin (Movement Engine). Only live rows count.
  UPDATE warehouse_bin_items
     SET quantity = GREATEST(0, quantity - v_qty), updated_at = now()
   WHERE bin_id = v_src AND item_id IS NOT DISTINCT FROM v_item_id AND deleted_at IS NULL;
  UPDATE warehouse_bin_items
     SET deleted_at = now(), quantity = 0, updated_at = now()
   WHERE bin_id = v_src AND item_id IS NOT DISTINCT FROM v_item_id
     AND quantity <= 0 AND deleted_at IS NULL;

  -- Release the reservation on the bin.
  UPDATE warehouse_bins
     SET reserved_quantity = GREATEST(0, COALESCE(reserved_quantity, 0) - COALESCE(v_reserved, 0)),
         updated_at = now()
   WHERE id = v_src;

  -- Audit row (PRD §9.23): dispatch movement.
  INSERT INTO warehouse_movements
    (organisation_id, movement_type, reference_type, reference_id, item_id,
     source_bin_id, quantity, operator_id, device, remarks)
  VALUES
    (v_org, 'dispatch', 'dispatch', p_dispatch_id::TEXT, v_item_id,
     v_src, -v_qty, p_operator_id, 'web',
     'Shipment ' || COALESCE(p_vehicle_no, '') || ' ' || COALESCE(p_driver_name, ''));

  UPDATE warehouse_dispatches
     SET status = 'completed',
         completed_at = now(),
         vehicle_no = COALESCE(p_vehicle_no, vehicle_no),
         driver_name = COALESCE(p_driver_name, driver_name),
         updated_at = now()
   WHERE id = p_dispatch_id;

  RETURN jsonb_build_object('ok', true, 'dispatch_id', p_dispatch_id);
END;

DECLARE
  v_org UUID;
  v_item_id UUID;
  v_qty NUMERIC;
  v_src UUID;
  v_dst UUID;
  v_src_qty NUMERIC;
  v_dst_max NUMERIC;
  v_ok BOOLEAN;
  v_row RECORD;
BEGIN
  SELECT organisation_id, item_id, quantity, source_bin_id, destination_bin_id, status
    INTO v_org, v_item_id, v_qty, v_src, v_dst, v_row.status
    FROM warehouse_transfers WHERE id = p_transfer_id;

  IF v_org IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Transfer not found');
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM user_organisations
     WHERE organisation_id = v_org AND user_id = auth.uid() AND status = 'active'
  ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Not a member of this organisation');
  END IF;
  IF v_row.status NOT IN ('requested','approved','picking','in_transit') THEN
    RETURN jsonb_build_object('ok', false, 'error',
      'Transfer status ' || v_row.status || ' cannot be executed');
  END IF;

  -- BOTH bins must belong to the caller's org (SECURITY DEFINER bypasses RLS).
  SELECT COUNT(*) = 2 INTO v_ok
    FROM warehouse_bins
   WHERE id IN (v_src, v_dst) AND organisation_id = v_org AND deleted_at IS NULL;
  IF NOT v_ok THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Source/destination bin not found in this organisation');
  END IF;

  -- Available = quantity minus reserved (reserved stock cannot be moved).
  SELECT COALESCE(SUM(bi.quantity), 0) - COALESCE(b.reserved_quantity, 0) INTO v_src_qty
    FROM warehouse_bins b
    LEFT JOIN warehouse_bin_items bi
      ON bi.bin_id = b.id AND bi.item_id IS NOT DISTINCT FROM v_item_id AND bi.deleted_at IS NULL
   WHERE b.id = v_src;
  IF v_src_qty < v_qty THEN
    RETURN jsonb_build_object('ok', false, 'error',
      'Insufficient unreserved stock in source bin: ' || v_src_qty || ' < ' || v_qty);
  END IF;

  SELECT max_quantity INTO v_dst_max FROM warehouse_bins WHERE id = v_dst;
  IF v_dst_max IS NOT NULL AND v_dst_max > 0 THEN
    SELECT COALESCE(SUM(quantity), 0) INTO v_src_qty
      FROM warehouse_bin_items WHERE bin_id = v_dst AND deleted_at IS NULL;
    IF v_src_qty + v_qty > v_dst_max THEN
      RETURN jsonb_build_object('ok', false, 'error',
        'Destination bin capacity exceeded: ' || v_src_qty || ' + ' || v_qty || ' > ' || v_dst_max);
    END IF;
  END IF;

  UPDATE warehouse_bin_items
     SET quantity = GREATEST(0, quantity - v_qty), updated_at = now()
   WHERE bin_id = v_src AND item_id IS NOT DISTINCT FROM v_item_id AND deleted_at IS NULL;
  UPDATE warehouse_bin_items
     SET deleted_at = now(), quantity = 0, updated_at = now()
   WHERE bin_id = v_src AND item_id IS NOT DISTINCT FROM v_item_id
     AND quantity <= 0 AND deleted_at IS NULL;

  INSERT INTO warehouse_bin_items (organisation_id, bin_id, item_id, quantity, is_primary, created_at, updated_at)
  VALUES (v_org, v_dst, v_item_id, v_qty, false, now(), now())
  ON CONFLICT (bin_id, item_id)
  DO UPDATE SET quantity = warehouse_bin_items.quantity + EXCLUDED.quantity,
                deleted_at = NULL,
                updated_at = now();

  INSERT INTO warehouse_movements
    (organisation_id, movement_type, reference_type, reference_id, item_id,
     source_bin_id, destination_bin_id, quantity, operator_id, device, remarks)
  VALUES
    (v_org, 'transfer_out', 'transfer', p_transfer_id::TEXT, v_item_id,
     v_src, v_dst, -v_qty, p_operator_id, p_device, p_remarks),
    (v_org, 'transfer_in', 'transfer', p_transfer_id::TEXT, v_item_id,
     v_src, v_dst, v_qty, p_operator_id, p_device, p_remarks);

  UPDATE warehouse_transfers
     SET status = 'received',
         received_by = COALESCE(p_operator_id, received_by),
         received_at = now(),
         updated_at = now()
   WHERE id = p_transfer_id;

  RETURN jsonb_build_object('ok', true, 'transfer_id', p_transfer_id);
END;

DECLARE
  v_payroll RECORD;
  v_existing_id UUID;
  v_salary_exp_id UUID;
  v_pf_payable_id UUID;
  v_esi_payable_id UUID;
  v_tds_payable_id UUID;
  v_adv_recovery_id UUID;
  v_salary_payable_id UUID;
  v_journal_id UUID;
  v_creator_id UUID;
  v_total_debit NUMERIC(15,2);
  v_total_credit NUMERIC(15,2);
  v_computed_net NUMERIC(15,2);
BEGIN
  IF auth.uid() IS NOT NULL AND NOT public.user_can_access_org(p_organisation_id) THEN
    RAISE EXCEPTION 'Unauthorized organization access';
  END IF;

  IF p_gross_salary <= 0 THEN
    RAISE EXCEPTION 'Gross salary must be greater than zero';
  END IF;

  v_computed_net := p_gross_salary - (p_total_pf + p_total_esi + p_total_advances + p_total_tds);
  IF v_computed_net < 0 THEN
    RAISE EXCEPTION 'Deductions cannot exceed gross salary';
  END IF;

