    IF OLD.status IN ('accepted', 'converted') THEN
      RAISE EXCEPTION 'Cannot delete an accepted or converted proforma invoice (ID: %).', OLD.id;
    END IF;
    RETURN OLD;
  ELSIF TG_OP = 'UPDATE' THEN
    IF OLD.status IN ('accepted', 'converted') THEN
      IF NEW.grand_total IS DISTINCT FROM OLD.grand_total OR
         NEW.subtotal IS DISTINCT FROM OLD.subtotal OR
         NEW.cgst IS DISTINCT FROM OLD.cgst OR
         NEW.sgst IS DISTINCT FROM OLD.sgst OR
         NEW.igst IS DISTINCT FROM OLD.igst OR
         NEW.client_id IS DISTINCT FROM OLD.client_id OR
         NEW.organisation_id IS DISTINCT FROM OLD.organisation_id OR
         NEW.pi_number IS DISTINCT FROM OLD.pi_number THEN
        RAISE EXCEPTION 'Cannot modify financial snapshot or identity fields of an accepted/converted proforma invoice (ID: %).', OLD.id;
      END IF;
    END IF;
    RETURN NEW;
  END IF;
  RETURN NEW;
END;

