  IF current_setting('app.allow_financial_mutation', true) = 'true' THEN
    IF TG_OP = 'DELETE' THEN
      RETURN OLD;
    ELSE
      RETURN NEW;
    END IF;
  END IF;

  IF TG_OP = 'UPDATE' THEN
    IF OLD.status = 'PAID' AND NEW.status != 'PAID' THEN
      RAISE EXCEPTION 'Cannot directly modify or un-pay paid advance/expense transactions. Use cancel_advance_expense_atomic.';
    END IF;
    IF OLD.status = 'PAID' AND (OLD.amount != NEW.amount OR OLD.employee_id != NEW.employee_id OR OLD.float_id != NEW.float_id) THEN
      RAISE EXCEPTION 'Cannot modify financial properties of a paid advance/expense.';
    END IF;
    RETURN NEW;
  ELSIF TG_OP = 'DELETE' THEN
    IF OLD.status = 'PAID' THEN
      RAISE EXCEPTION 'Cannot hard-delete paid advance/expense records. Use cancel_advance_expense_atomic.';
    END IF;
    RETURN OLD;
  END IF;

  RETURN NEW;
END;

