    v_next_val INT;
    v_seq_name TEXT;
    v_cn_no TEXT;
BEGIN
    IF auth.uid() IS NOT NULL AND NOT public.user_can_access_org(p_org_id) THEN
        RAISE EXCEPTION 'Unauthorized organization access';
    END IF;

    v_year_prefix := to_char(CURRENT_DATE, 'YY') || to_char(CURRENT_DATE + interval '1 year', 'YY');
    v_seq_name := 'cn_seq_' || replace(p_org_id::text, '-', '_');

    EXECUTE format('CREATE SEQUENCE IF NOT EXISTS %I START WITH 1', v_seq_name);
    EXECUTE format('SELECT nextval(%L)', v_seq_name) INTO v_next_val;

    v_cn_no := 'CN/' || v_year_prefix || '/' || lpad(v_next_val::text, 4, '0');
