  SELECT COALESCE(MAX(
    CASE 
      WHEN pi_number ~ ('^PI-' || v_year || '-[0-9]+$') 
      THEN (regexp_match(pi_number, '^PI-' || v_year || '-([0-9]+)$'))[1]::INT
