  SELECT COALESCE(MAX(
    CASE 
      WHEN quotation_no ~ ('^QT-' || v_year || '-[0-9]+$') 
      THEN (regexp_match(quotation_no, '^QT-' || v_year || '-([0-9]+)$'))[1]::INT
      ELSE 0
    END
  ), 0) + 1 INTO v_count
  FROM public.quotation_header
  WHERE organisation_id = p_org_id;

  v_next_no := 'QT-' || v_year || '-' || LPAD(v_count::TEXT, 4, '0');
  RETURN v_next_no;
END;

