DECLARE
  next_num INTEGER;
  new_no VARCHAR;
BEGIN
  SELECT COALESCE(MAX(CAST(SUBSTRING(entry_no FROM 4) AS INTEGER)), 0) + 1
  INTO next_num
  FROM production_entries
  WHERE organisation_id = org_id;
  
  new_no := 'PE-' || LPAD(next_num::TEXT, 4, '0');
  RETURN new_no;
