DECLARE
  prefix TEXT;
  next_num INTEGER;
  result TEXT;
BEGIN
  prefix := 'PI/' || year || '/';
  
  SELECT COALESCE(MAX(
    CASE 
      WHEN substring(pi_number FROM 1 FOR length(prefix)) = prefix 
      THEN substring(pi_number FROM length(prefix) + 1 FOR 6)::INTEGER 
      ELSE 0 
    END
  ), 0) + 1 INTO next_num
  FROM proforma_invoices
  WHERE organisation_id = org_id AND pi_number LIKE prefix || '%';
  
  result := prefix || lpad(next_num::TEXT, 6, '0');
  RETURN result;
END;

DECLARE
  year_part TEXT;
  max_num INTEGER;
  candidate_code TEXT;
  code_exists BOOLEAN;
BEGIN
  IF NEW.project_code IS NOT NULL AND TRIM(NEW.project_code) <> '' THEN
    NEW.project_code := TRIM(NEW.project_code);
    RETURN NEW;
  END IF;

  year_part := EXTRACT(YEAR FROM CURRENT_DATE)::TEXT;

  SELECT COALESCE(MAX(SUBSTRING(project_code FROM 10)::INTEGER), 0) INTO max_num
  FROM projects
  WHERE project_code ~ ('^PRJ-' || year_part || '-[0-9]+$');

  LOOP
    max_num := max_num + 1;
    candidate_code := 'PRJ-' || year_part || '-' || LPAD(max_num::TEXT, 4, '0');

    SELECT EXISTS(
      SELECT 1 FROM projects WHERE project_code = candidate_code
    ) INTO code_exists;

    IF NOT code_exists THEN
      NEW.project_code := candidate_code;
      EXIT;
    END IF;
  END LOOP;

  RETURN NEW;
END;

