DECLARE
  v_prefix TEXT;
  v_next_number INTEGER;
  v_financial_year TEXT;
  v_voucher_no TEXT;
BEGIN
  -- Determine prefix from voucher type
  v_prefix := CASE p_voucher_type
    WHEN 'Receipt' THEN 'RCP'
    WHEN 'Payment' THEN 'PAY'
    WHEN 'Sales' THEN 'INV'
    WHEN 'Purchase' THEN 'PO'
    WHEN 'Journal' THEN 'JRNL'
    WHEN 'Contra' THEN 'CNTR'
    WHEN 'Credit Note' THEN 'CN'
    WHEN 'Debit Note' THEN 'DN'
    ELSE 'JE'
  END;

  -- Calculate financial year (April-March)
  IF EXTRACT(MONTH FROM p_date) >= 4 THEN
    v_financial_year := TO_CHAR(p_date, 'YYYY') || '-' || TO_CHAR(p_date + INTERVAL '1 year', 'YY');
  ELSE
    v_financial_year := TO_CHAR(p_date - INTERVAL '1 year', 'YYYY') || '-' || TO_CHAR(p_date, 'YY');
  END IF;

  -- Get next sequence number
  SELECT COALESCE(MAX(
    CAST(SUBSTRING(voucher_no FROM '[0-9]+$') AS INTEGER)
  ), 0) + 1
  INTO v_next_number
  FROM journal_entries
  WHERE organisation_id = p_organisation_id
    AND voucher_type::TEXT = p_voucher_type
    AND voucher_no LIKE v_prefix || '-' || v_financial_year || '-%';

  -- Format voucher number
  v_voucher_no := v_prefix || '-' || v_financial_year || '-' || LPAD(v_next_number::TEXT, 4, '0');

  RETURN v_voucher_no;
END;

DECLARE
  v_created_count INTEGER := 0;
  v_rack_idx INTEGER;
  v_col_idx INTEGER;
  v_lvl_idx INTEGER;
  v_bin_code VARCHAR(50);
  v_level_str VARCHAR(20);
  v_x NUMERIC(8,2) := 0;
  v_y NUMERIC(8,2) := 0;
  v_base_x NUMERIC(8,2);
  v_base_y NUMERIC(8,2);
  v_col_spacing NUMERIC(8,2) := 1.5;
  v_lvl_spacing NUMERIC(8,2) := 1.5;
BEGIN
  IF auth.uid() IS NOT NULL AND NOT public.user_can_access_org(p_organisation_id) THEN
    RAISE EXCEPTION 'Unauthorized organization access';
  END IF;

  FOR v_rack_idx IN 1..array_length(p_rack_names, 1) LOOP
    v_base_x := COALESCE(p_pos_x[v_rack_idx], (v_rack_idx - 1) * 10.0);
    v_base_y := COALESCE(p_pos_y[v_rack_idx], 0);

    FOR v_col_idx IN 1..p_columns[v_rack_idx] LOOP
      FOR v_lvl_idx IN 1..p_levels[v_rack_idx] LOOP
        v_level_str := replace(p_level_format, '{n}', v_lvl_idx::text);

        v_bin_code := CASE WHEN p_bin_prefix <> '' THEN p_bin_prefix || p_separator ELSE '' END
                   || p_rack_names[v_rack_idx] || p_separator
                   || lpad(v_col_idx::text, p_padding, '0') || p_separator
                   || v_level_str;

        v_x := v_base_x + (v_col_idx - 1) * v_col_spacing;
        v_y := v_base_y + (v_lvl_idx - 1) * v_lvl_spacing;

        INSERT INTO warehouse_bins (
          organisation_id, layout_id, bin_code,
          rack_name, column_number, level_number,
          rack_type, max_quantity,
          position_x, position_y, position_z,
          status, is_active
        )
        VALUES (
          p_organisation_id, p_layout_id, v_bin_code,
          p_rack_names[v_rack_idx], v_col_idx, v_lvl_idx,
          p_rack_type, p_max_qty,
          v_x, v_y, (v_lvl_idx - 1) * v_lvl_spacing,
          'empty', true
        )
        ON CONFLICT (layout_id, bin_code) DO NOTHING;

        v_created_count := v_created_count + 1;
      END LOOP;
    END LOOP;
  END LOOP;

  RETURN v_created_count;
END;

