DECLARE
  v_price DECIMAL(12,2);
BEGIN
  -- 1. Try: Name + Variant + Make
  IF p_variant_id IS NOT NULL AND p_make IS NOT NULL AND p_make <> '' THEN
    IF p_price_type = 'sale' THEN
      SELECT sale_price INTO v_price FROM item_variant_pricing
      WHERE item_id = p_item_id AND company_variant_id = p_variant_id AND make = p_make AND is_active = true;
    ELSE
      SELECT purchase_price INTO v_price FROM item_variant_pricing
      WHERE item_id = p_item_id AND company_variant_id = p_variant_id AND make = p_make AND is_active = true;
    END IF;
  END IF;

  -- 2. Try: Name + Make (ignore Variant if not found or empty)
  IF v_price IS NULL AND p_make IS NOT NULL AND p_make <> '' THEN
    IF p_price_type = 'sale' THEN
      -- Try with any variant or no variant but with this make
      SELECT sale_price INTO v_price FROM item_variant_pricing
      WHERE item_id = p_item_id AND make = p_make AND is_active = true
      ORDER BY (company_variant_id = p_variant_id) DESC, created_at DESC LIMIT 1;
    ELSE
      SELECT purchase_price INTO v_price FROM item_variant_pricing
      WHERE item_id = p_item_id AND make = p_make AND is_active = true
      ORDER BY (company_variant_id = p_variant_id) DESC, created_at DESC LIMIT 1;
    END IF;
  END IF;

  -- 3. Try: Name + Variant (if make not found)
  IF v_price IS NULL AND p_variant_id IS NOT NULL THEN
    IF p_price_type = 'sale' THEN
      SELECT sale_price INTO v_price FROM item_variant_pricing
      WHERE item_id = p_item_id AND company_variant_id = p_variant_id AND (make IS NULL OR make = '') AND is_active = true;
    ELSE
      SELECT purchase_price INTO v_price FROM item_variant_pricing
      WHERE item_id = p_item_id AND company_variant_id = p_variant_id AND (make IS NULL OR make = '') AND is_active = true;
    END IF;
  END IF;

  -- 4. Fallback: Name only (backward compatibility)
  IF v_price IS NULL THEN
    IF p_price_type = 'sale' THEN
      SELECT sale_price INTO v_price FROM materials WHERE id = p_item_id;
    ELSE
      SELECT purchase_price INTO v_price FROM materials WHERE id = p_item_id;
    END IF;
  END IF;

  RETURN COALESCE(v_price, 0);
END;

DECLARE
  v_price DECIMAL(12,2);
  v_uses_variant BOOLEAN;
BEGIN
  SELECT uses_variant INTO v_uses_variant FROM materials WHERE id = p_item_id;

  IF p_variant_id IS NOT NULL AND v_uses_variant = true THEN
    IF p_price_type = 'sale' THEN
      SELECT sale_price INTO v_price FROM item_variant_pricing
      WHERE item_id = p_item_id AND company_variant_id = p_variant_id AND is_active = true;
    ELSE
      SELECT purchase_price INTO v_price FROM item_variant_pricing
      WHERE item_id = p_item_id AND company_variant_id = p_variant_id AND is_active = true;
    END IF;
  END IF;

  IF v_price IS NULL THEN
    IF p_price_type = 'sale' THEN
      SELECT sale_price INTO v_price FROM materials WHERE id = p_item_id;
    ELSE
      SELECT purchase_price INTO v_price FROM materials WHERE id = p_item_id;
    END IF;
  END IF;

  RETURN COALESCE(v_price, 0);
END;

DECLARE
  settings RECORD;
  next_num INTEGER;
  formatted_num TEXT;
BEGIN
  -- Get or create settings
  SELECT * INTO settings FROM document_settings WHERE organisation_id = p_org_id;
  
  IF NOT FOUND THEN
    -- Create default settings
    INSERT INTO document_settings (organisation_id) VALUES (p_org_id)
    ON CONFLICT (organisation_id) DO NOTHING;
    
    settings.vendor_prefix := 'VEN';
    settings.vendor_start_number := 1;
    settings.vendor_suffix := '';
    settings.vendor_padding := 3;
    settings.vendor_current_number := 1;
  END IF;
  
  -- Calculate next number
  next_num := COALESCE(settings.vendor_current_number, settings.vendor_start_number, 1);
  
  -- Format the number
  formatted_num := settings.vendor_prefix || 
                   LPAD(next_num::TEXT, COALESCE(settings.vendor_padding, 3), '0') ||
                   COALESCE(settings.vendor_suffix, '');
  
  -- Increment current number
  UPDATE document_settings 
  SET vendor_current_number = next_num + 1,
      updated_at = NOW()
  WHERE organisation_id = p_org_id;
  
  RETURN formatted_num;
END;

DECLARE
  v_user_id UUID;
  v_org_id UUID;
  v_archived BOOLEAN;
  v_channel project_collaboration_channels;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'not_authenticated';
  END IF;

  -- Verify project exists and caller is in its org.
  SELECT organisation_id, status = 'Closed'
    INTO v_org_id, v_archived
  FROM projects
  WHERE id = p_project_id;
  IF v_org_id IS NULL THEN
    RAISE EXCEPTION 'project_not_found';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM org_members
    WHERE organisation_id = v_org_id AND user_id = v_user_id
  ) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  -- Race lock: same project_id concurrent calls serialise here.
  PERFORM pg_advisory_xact_lock(hashtext('collab:' || p_project_id::text));

  -- Try existing.
  SELECT * INTO v_channel
  FROM project_collaboration_channels
  WHERE organisation_id = v_org_id
    AND project_id = p_project_id
    AND channel_type = 'project';

  IF NOT FOUND THEN
    INSERT INTO project_collaboration_channels (
      organisation_id, project_id, channel_type, name, created_by
    )
