            (SELECT project_name FROM projects WHERE id = p_project_id),
            v_user_id)
    RETURNING * INTO v_channel;
  END IF;

  -- Ensure caller is a member. ON CONFLICT preserves the existing role.
  INSERT INTO project_collaboration_members (organisation_id, channel_id, user_id, role)
  VALUES (v_org_id, v_channel.id, v_user_id, 'member')
  ON CONFLICT (channel_id, user_id) DO NOTHING;

  RETURN v_channel;
END;

