  IF v_user_id IS NOT NULL AND NOT public.user_can_access_org(v_org_id) THEN
    RAISE EXCEPTION 'Unauthorized organization access';
  END IF;

  IF v_req.status = 'issued' THEN
    RETURN jsonb_build_object('status', 'success', 'already_processed', true, 'requisition_id', p_requisition_id);
  END IF;

  IF v_main_wh IS NULL THEN
    SELECT id INTO v_main_wh FROM public.warehouses WHERE organisation_id = v_org_id AND (warehouse_purpose = 'main' OR is_default = TRUE) LIMIT 1;
    IF v_main_wh IS NULL THEN SELECT id INTO v_main_wh FROM public.warehouses WHERE organisation_id = v_org_id LIMIT 1; END IF;
  END IF;

  IF v_wip_wh IS NULL THEN
    SELECT id INTO v_wip_wh FROM public.warehouses WHERE organisation_id = v_org_id AND warehouse_purpose = 'wip' LIMIT 1;
    IF v_wip_wh IS NULL THEN SELECT id INTO v_wip_wh FROM public.warehouses WHERE organisation_id = v_org_id AND id != v_main_wh LIMIT 1; END IF;
    IF v_wip_wh IS NULL THEN v_wip_wh := v_main_wh; END IF;
  END IF;

  -- Verify all items stock and deduct/transfer atomically
  IF p_items IS NOT NULL AND jsonb_array_length(p_items) > 0 THEN
    FOR r_item IN SELECT * FROM jsonb_to_recordset(p_items) AS x(
      item_id uuid,
      material_id uuid,
      variant_id uuid,
      issued_qty numeric
    )
    LOOP
      IF r_item.material_id IS NOT NULL AND r_item.issued_qty > 0 THEN
        SELECT id, current_stock INTO v_main_stock_id, v_main_stock_qty
        FROM public.item_stock
        WHERE item_id = r_item.material_id
          AND warehouse_id = v_main_wh
          AND ((r_item.variant_id IS NULL AND company_variant_id IS NULL) OR company_variant_id = r_item.variant_id)
        FOR UPDATE;

        IF v_main_stock_id IS NULL OR v_main_stock_qty < r_item.issued_qty THEN
          RAISE EXCEPTION 'Insufficient stock in Main Store for material %: available %, requested %',
            r_item.material_id, COALESCE(v_main_stock_qty, 0), r_item.issued_qty;
        END IF;

        UPDATE public.item_stock
        SET current_stock = current_stock - r_item.issued_qty, updated_at = NOW()
        WHERE id = v_main_stock_id;

        INSERT INTO public.material_logs (
          organisation_id, item_id, variant_id,
          qty_received, qty_used, type, invoice_number, received_by, remarks, created_at
        ) VALUES (
          v_org_id, r_item.material_id, r_item.variant_id,
          0, r_item.issued_qty, 'OUT', v_req.requisition_no, v_user_id,
          'Stores Requisition Issue: ' || COALESCE(v_req.requisition_no, v_req.id::TEXT), NOW()
        );

        -- Add to WIP
        SELECT id INTO v_wip_stock_id
        FROM public.item_stock
        WHERE item_id = r_item.material_id
          AND warehouse_id = v_wip_wh
          AND ((r_item.variant_id IS NULL AND company_variant_id IS NULL) OR company_variant_id = r_item.variant_id)
        FOR UPDATE;

        IF v_wip_stock_id IS NOT NULL THEN
          UPDATE public.item_stock
          SET current_stock = current_stock + r_item.issued_qty, updated_at = NOW()
          WHERE id = v_wip_stock_id;
        ELSE
          INSERT INTO public.item_stock (
            organisation_id, item_id, warehouse_id, company_variant_id, current_stock
          ) VALUES (
            v_org_id, r_item.material_id, v_wip_wh, r_item.variant_id, r_item.issued_qty
          );
        END IF;

        INSERT INTO public.material_logs (
          organisation_id, item_id, variant_id,
          qty_received, qty_used, type, invoice_number, received_by, remarks, created_at
        ) VALUES (
          v_org_id, r_item.material_id, r_item.variant_id,
          r_item.issued_qty, 0, 'IN', v_req.requisition_no, v_user_id,
          'Stores Requisition WIP Transfer: ' || COALESCE(v_req.requisition_no, v_req.id::TEXT), NOW()
        );

        IF r_item.item_id IS NOT NULL THEN
          UPDATE public.material_requisition_items
          SET issued_qty = r_item.issued_qty, status = 'issued'
          WHERE id = r_item.item_id;
        END IF;

        IF v_req.job_card_id IS NOT NULL THEN
          UPDATE public.job_card_materials
          SET issued_qty = COALESCE(issued_qty, 0) + r_item.issued_qty
          WHERE job_card_id = v_req.job_card_id AND material_id = r_item.material_id;
        END IF;
      END IF;
    END LOOP;
  ELSE
    FOR r_item IN SELECT id, material_id, issued_qty, required_qty FROM public.material_requisition_items WHERE requisition_id = p_requisition_id LOOP
      DECLARE
