DECLARE
  v_user_id UUID;
  v_channel project_collaboration_channels;
  v_msg project_collaboration_messages;
  v_existing_message_id UUID;
  v_metadata JSONB;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;

  -- Idempotency check: already linked?
  SELECT message_id INTO v_existing_message_id
  FROM daily_report_channel_links
  WHERE daily_report_id = p_daily_report_id;
  IF v_existing_message_id IS NOT NULL THEN
    SELECT * INTO v_msg
    FROM project_collaboration_messages
    WHERE id = v_existing_message_id;
    RETURN v_msg;
  END IF;

  -- Resolve channel via the race-safe RPC.
  v_channel := public.get_or_create_project_channel(p_project_id);

  v_metadata := jsonb_build_object(
    'linked_entities', jsonb_build_array(jsonb_build_object(
      'type', 'daily_report',
      'id', p_daily_report_id,
      'label', 'Daily Report'
    ))
  );

  INSERT INTO project_collaboration_messages (
    organisation_id, channel_id, sender_id, message_type, content, metadata, client_msg_id
  )
  VALUES (
    v_channel.organisation_id, v_channel.id, v_user_id,
    'system', 'Daily Report submitted', v_metadata,
    ('dr:' || p_daily_report_id::text)::uuid
  )
  RETURNING * INTO v_msg;

  INSERT INTO daily_report_channel_links
    (daily_report_id, organisation_id, project_id, channel_id, message_id)
  VALUES
    (p_daily_report_id, v_channel.organisation_id, p_project_id, v_channel.id, v_msg.id);

  RETURN v_msg;
END;

