  FROM project_collaboration_channels WHERE id = p_channel_id;
  IF v_org_id IS NULL THEN RAISE EXCEPTION 'channel_not_found'; END IF;
  IF NOT EXISTS (
    SELECT 1 FROM org_members WHERE organisation_id = v_org_id AND user_id = v_user_id
  ) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  INSERT INTO project_collaboration_read_state
    (channel_id, user_id, last_read_message_id, last_read_at)
  VALUES
    (p_channel_id, v_user_id, p_through_message_id, now())
  ON CONFLICT (channel_id, user_id) DO UPDATE
    SET last_read_message_id = EXCLUDED.last_read_message_id,
        last_read_at = EXCLUDED.last_read_at;

  UPDATE project_collaboration_members
     SET last_read_at = now()
   WHERE channel_id = p_channel_id
     AND user_id = v_user_id;
END;

