DECLARE
  v_journal_id UUID;
  v_total_debit NUMERIC := 0;
  v_total_credit NUMERIC := 0;
  v_line_debit NUMERIC;
  v_line_credit NUMERIC;
  v_account_id UUID;
  v_account_type TEXT;
  v_account_org UUID;
  v_account_active BOOLEAN;
  elem JSONB;
BEGIN
  -- 1. Authentication Check
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  -- 2. Tenant Access Check
  IF NOT public.user_can_access_org(p_organisation_id) THEN
    RAISE EXCEPTION 'Unauthorized organization access';
  END IF;

  -- 3. RBAC Posting Permission Check
  IF NOT EXISTS (
    SELECT 1 FROM org_members 
    WHERE user_id = auth.uid() 
      AND organisation_id = p_organisation_id 
      AND role IN ('admin', 'owner', 'accountant', 'manager')
  ) THEN
    RAISE EXCEPTION 'User lacks permission to post accounting entries in organisation %', p_organisation_id;
  END IF;

  -- 4. Rejection of Empty Journals
  IF p_lines IS NULL OR jsonb_array_length(p_lines) = 0 THEN
    RAISE EXCEPTION 'Journal entry must contain at least one line';
  END IF;

  -- 5. Idempotency Check: check if journal already exists for document
  IF p_document_id IS NOT NULL THEN
    SELECT id INTO v_journal_id
    FROM journal_entries
    WHERE organisation_id = p_organisation_id
      AND document_id = p_document_id
      AND document_type = p_document_type
    LIMIT 1;

    IF v_journal_id IS NOT NULL THEN
      RETURN v_journal_id;
    END IF;
  END IF;

  -- 6. Line Validation Loop
  FOR elem IN SELECT * FROM jsonb_array_elements(p_lines) LOOP
    -- Explicit account_id Presence Check
    IF (elem->>'account_id') IS NULL OR TRIM(elem->>'account_id') = '' THEN
      RAISE EXCEPTION 'Journal line requires non-null account_id';
    END IF;

    v_account_id := (elem->>'account_id')::UUID;
    v_line_debit := COALESCE((elem->>'debit')::NUMERIC, 0.00);
    v_line_credit := COALESCE((elem->>'credit')::NUMERIC, 0.00);

    IF v_line_debit < 0 OR v_line_credit < 0 THEN
      RAISE EXCEPTION 'Debit and Credit amounts must be non-negative';
    END IF;

    IF v_line_debit > 0 AND v_line_credit > 0 THEN
      RAISE EXCEPTION 'A journal line cannot contain both Debit and Credit amounts';
    END IF;

    v_total_debit := v_total_debit + v_line_debit;
    v_total_credit := v_total_credit + v_line_credit;

    SELECT organisation_id, COALESCE(is_active, true), account_type 
    INTO v_account_org, v_account_active, v_account_type
    FROM accounts WHERE id = v_account_id;

    IF v_account_org IS NULL OR v_account_org <> p_organisation_id THEN
      RAISE EXCEPTION 'Account % does not belong to organization %', v_account_id, p_organisation_id;
    END IF;

    IF NOT v_account_active THEN
      RAISE EXCEPTION 'Account % is inactive', v_account_id;
    END IF;

    -- Control Account Party Requirement Enforcement
    IF v_account_type IN ('receivable', 'payable', 'Control Account') THEN
      IF (elem->>'party_id') IS NULL OR (elem->>'party_role') IS NULL THEN
        RAISE EXCEPTION 'Control account % requires party_id and party_role', v_account_id;
      END IF;
    END IF;

    -- Tenant-Aware Party Role Check
    IF (elem->>'party_id') IS NOT NULL THEN
      IF NOT validate_party_role(p_organisation_id, (elem->>'party_id')::UUID, (elem->>'party_role')::party_role_type) THEN
        RAISE EXCEPTION 'Party % does not possess role % in organisation %', elem->>'party_id', elem->>'party_role', p_organisation_id;
      END IF;
    END IF;
  END LOOP;

  -- 7. Zero-Value Rejection
  IF v_total_debit <= 0 THEN
    RAISE EXCEPTION 'Journal entry total amount must be greater than zero';
  END IF;

  -- 8. Mathematical Balance Check
  IF ROUND(v_total_debit, 2) <> ROUND(v_total_credit, 2) THEN
    RAISE EXCEPTION 'Unbalanced journal entry: Total Debit (%) != Total Credit (%)', v_total_debit, v_total_credit;
  END IF;

  -- 9. Explicit ON CONFLICT Header Insert for Deterministic Idempotency
  INSERT INTO journal_entries (
    organisation_id, company_id, document_id, document_type, voucher_no, voucher_date, voucher_type, financial_year, narration, status, created_by
  ) VALUES (
    p_organisation_id, p_organisation_id, p_document_id, p_document_type, p_voucher_no, p_transaction_date, p_voucher_type, p_financial_year, p_narration, 'Posted', auth.uid()
  )
  ON CONFLICT (organisation_id, document_type, document_id) WHERE document_id IS NOT NULL DO NOTHING
  RETURNING id INTO v_journal_id;

  -- If concurrency race occurred and row existed, fetch existing journal ID
  IF v_journal_id IS NULL AND p_document_id IS NOT NULL THEN
    SELECT id INTO v_journal_id
    FROM journal_entries
    WHERE organisation_id = p_organisation_id 
      AND document_id = p_document_id 
      AND document_type = p_document_type;
    RETURN v_journal_id;
  END IF;

  -- 10. Insert Lines
  FOR elem IN SELECT * FROM jsonb_array_elements(p_lines) LOOP
    INSERT INTO journal_entry_lines (
      journal_entry_id, account_id, party_id, party_role, debit, credit, narration
    ) VAL

DECLARE
  v_gr_id uuid;
  v_po_item record;
  v_req_line_id uuid;
  v_total_received numeric;
  v_gr_no text;
BEGIN
  IF auth.uid() IS NOT NULL AND NOT public.user_can_access_org(p_organisation_id) THEN
    RAISE EXCEPTION 'Unauthorized organization access';
  END IF;

  SELECT * INTO v_po_item
  FROM public.purchase_order_items
  WHERE id = p_po_item_id AND organisation_id = p_organisation_id;

  IF v_po_item.id IS NULL THEN
    RAISE EXCEPTION 'PO item not found';
  END IF;

  v_req_line_id := v_po_item.requisition_line_id;
  v_gr_no := 'GR-' || to_char(now(), 'YYMMDD-HH24MISSMS');

  INSERT INTO public.goods_receipts (
    organisation_id, gr_number, po_id, vendor_id, created_by
  )
  VALUES (
    p_organisation_id, v_gr_no, p_po_id, NULL, COALESCE(p_created_by, auth.uid())
  )
  RETURNING id INTO v_gr_id;

  INSERT INTO public.goods_receipt_lines (
    organisation_id, goods_receipt_id, po_item_id, requisition_line_id, received_qty
  )
  VALUES (
    p_organisation_id, v_gr_id, p_po_item_id, v_req_line_id, p_received_qty
  );

  IF v_req_line_id IS NOT NULL THEN
    SELECT COALESCE(SUM(received_qty), 0) INTO v_total_received
    FROM public.goods_receipt_lines
    WHERE requisition_line_id = v_req_line_id
      AND organisation_id = p_organisation_id;

    UPDATE public.purchase_requisition_lines
    SET
      received_qty = v_total_received,
      open_qty = GREATEST(COALESCE(requested_qty, 0) - v_total_received, 0),
      status = CASE
        WHEN v_total_received <= 0 THEN 'Open'
        WHEN v_total_received < COALESCE(requested_qty, 0) THEN 'Partially Fulfilled'
        ELSE 'Fulfilled'
      END
    WHERE id = v_req_line_id;
  END IF;

  RETURN v_gr_id;
END;

DECLARE
  v_journal_id UUID;
  v_total_debit DECIMAL := 0;
  v_total_credit DECIMAL := 0;
  v_line JSONB;
  v_voucher_no TEXT;
  v_account RECORD;
BEGIN
  -- Validate lines exist
  IF jsonb_array_length(p_lines) < 2 THEN
    RAISE EXCEPTION 'At least 2 line items required';
  END IF;

  -- Calculate totals and validate
  FOR v_line IN SELECT * FROM jsonb_array_elements(p_lines)
  LOOP
    v_total_debit := v_total_debit + COALESCE((v_line->>'debit')::DECIMAL, 0);
    v_total_credit := v_total_credit + COALESCE((v_line->>'credit')::DECIMAL, 0);

    -- Validate account exists and is active
    SELECT * INTO v_account FROM accounts WHERE id = (v_line->>'account_id')::UUID;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Account not found: %', v_line->>'account_id';
    END IF;
    IF v_account.status != 'Active' THEN
      RAISE EXCEPTION 'Account is not active: %', v_account.name;
    END IF;
  END LOOP;

  -- Validate double-entry
  IF ABS(v_total_debit - v_total_credit) > 0.01 THEN
    RAISE EXCEPTION 'Total debit (%) must equal total credit (%)', v_total_debit, v_total_credit;
  END IF;

  -- Generate voucher number
  v_voucher_no := generate_voucher_number(p_organisation_id, p_voucher_type, p_voucher_date);

  -- Create journal entry
  INSERT INTO journal_entries (
    organisation_id, company_id, voucher_no, voucher_date,
    voucher_type, narration, status, total_debit, total_credit
  ) VALUES (
    p_organisation_id, p_organisation_id, v_voucher_no, p_voucher_date,
    p_voucher_type::voucher_type, p_narration, 'Posted', v_total_debit, v_total_credit
  ) RETURNING id INTO v_journal_id;

  -- Insert lines
  FOR v_line IN SELECT * FROM jsonb_array_elements(p_lines)
  LOOP
    INSERT INTO journal_entry_lines (
      journal_id, account_id, debit, credit, party_type, party_id, narration
    ) VALUES (
      v_journal_id,
      (v_line->>'account_id')::UUID,
      COALESCE((v_line->>'debit')::DECIMAL, 0),
      COALESCE((v_line->>'credit')::DECIMAL, 0),
      (v_line->>'party_type')::party_type_enum,
      (v_line->>'party_id')::UUID,
      v_line->>'narration'
    );

    -- Update account balance
    PERFORM update_account_balance(
      (v_line->>'account_id')::UUID,
      COALESCE((v_line->>'debit')::DECIMAL, 0),
      COALESCE((v_line->>'credit')::DECIMAL, 0)
    );
  END LOOP;

  RETURN v_journal_id;
END;

declare
  v_org_id uuid;
  v_is_admin boolean;
  v_old_active boolean;
  v_new_active boolean;
  v_new_is_admin boolean;
  v_other_admins int;
begin
  -- Allow test suite bypass
  if current_setting('app.p0_test_running', true) = 'true' then
    if tg_op = 'DELETE' then
      return old;
    else
      return new;
    end if;
  end if;

  v_org_id := coalesce(old.organisation_id, new.organisation_id);
  v_is_admin := lower(coalesce(old.role, '')) = 'admin';
  v_old_active := coalesce(lower(old.status), 'active') = 'active';

  if tg_op = 'DELETE' then
    if v_is_admin and v_old_active then
      select count(*)
        into v_other_admins
      from public.org_members m
      where m.organisation_id = v_org_id
        and m.id <> old.id
        and lower(coalesce(m.role, '')) = 'admin'
        and coalesce(lower(m.status), 'active') = 'active';

      if v_other_admins = 0 then
        raise exception 'Cannot remove the last admin for this organisation.';
      end if;
    end if;
    return old;
  end if;

  v_new_active := coalesce(lower(new.status), 'active') = 'active';
  v_new_is_admin := lower(coalesce(new.role, '')) = 'admin';

  if v_is_admin and v_old_active and (not v_new_is_admin or not v_new_active) then
    select count(*)
      into v_other_admins
    from public.org_members m
    where m.organisation_id = v_org_id
      and m.id <> old.id
      and lower(coalesce(m.role, '')) = 'admin'
      and coalesce(lower(m.status), 'active') = 'active';

    if v_other_admins = 0 then
      raise exception 'Cannot demote/deactivate the last admin for this organisation.';
    end if;
  end if;

  return new;
end;

BEGIN
  IF NEW.pm_status IN ('Approved', 'Reported') THEN
    RAISE EXCEPTION 'Cannot insert site report with locked status: %', NEW.pm_status
      USING ERRCODE = 'check_violation',
            HINT = 'New site reports must start as Draft or Pending.';
  END IF;

  RETURN NEW;
END;

DECLARE
  v_status TEXT;
BEGIN
  -- Get the current status of the report being modified
  IF TG_OP = 'UPDATE' THEN
    v_status := OLD.pm_status;
  ELSIF TG_OP = 'DELETE' THEN
    v_status := OLD.pm_status;
  END IF;

  -- Block mutation of locked reports
  IF v_status IN ('Pending Approval', 'Approved', 'Reported') THEN
    RAISE EXCEPTION 'Cannot modify site report: report is locked (status: %)', v_status
      USING ERRCODE = 'check_violation',
            HINT = 'Approved/reported site reports are immutable. Create an addendum instead.';
  END IF;

  -- Allow the operation for unlocked reports
  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  ELSE
    RETURN NEW;
  END IF;
END;

BEGIN
  -- Block ALL updates to headers that are already in 'approved' or 'published' status
  IF OLD.approval_status IN ('approved', 'published') THEN
    RAISE EXCEPTION 'Published BOM headers are immutable. Create a new revision (e.g. Revision B) to make modifications.';
  END IF;
  RETURN NEW;
END;

DECLARE
  v_status VARCHAR;
BEGIN
  SELECT approval_status INTO v_status
  FROM bom_headers
  WHERE id = COALESCE(OLD.bom_id, NEW.bom_id);

  IF v_status IN ('approved', 'published') THEN
    RAISE EXCEPTION 'Cannot insert, update, or delete items on a published BOM. Create a new revision instead.';
  END IF;
  RETURN COALESCE(NEW, OLD);
END;

