      UPDATE public.credit_notes SET stock_restored = TRUE, updated_at = NOW() WHERE id = p_credit_note_id;
      RETURN jsonb_build_object(
        'status', 'success',
        'credit_note_id', p_credit_note_id,
        'action', v_action,
        'stock_handled_by_return', true,
        'message', 'Stock was already restored by linked Material Return'
      );
    END IF;
