        quantity numeric
      )
      LOOP
        v_mat_id := COALESCE(r_item.material_id, r_item.item_id);
        IF v_mat_id IS NOT NULL AND r_item.warehouse_id IS NOT NULL AND r_item.quantity > 0 THEN
          SELECT id INTO v_stock_id
          FROM public.item_stock
          WHERE item_id = v_mat_id
            AND warehouse_id = r_item.warehouse_id
            AND ((r_item.variant_id IS NULL AND company_variant_id IS NULL) OR company_variant_id = r_item.variant_id)
          FOR UPDATE;

          IF v_stock_id IS NOT NULL THEN
            UPDATE public.item_stock
            SET current_stock = current_stock + r_item.quantity, updated_at = NOW()
            WHERE id = v_stock_id;
          ELSE
            INSERT INTO public.item_stock (
              organisation_id, item_id, warehouse_id, company_variant_id, current_stock
            ) VALUES (
              v_org_id, v_mat_id, r_item.warehouse_id, r_item.variant_id, r_item.quantity
            );
          END IF;

          INSERT INTO public.material_logs (
            organisation_id, item_id, variant_id,
            qty_received, qty_used, type, invoice_number, received_by, remarks, created_at
          ) VALUES (
            v_org_id, v_mat_id, r_item.variant_id,
            r_item.quantity, 0, 'IN', v_dn.dn_number, v_user_id,
            'Debit Note Reversal: ' || COALESCE(v_dn.dn_number, v_dn.id::TEXT), NOW()
          );
        END IF;
      END LOOP;
    END IF;

    UPDATE public.debit_notes SET stock_reversed = FALSE, updated_at = NOW() WHERE id = p_debit_note_id;
  END IF;

  RETURN jsonb_build_object(
    'status', 'success',
    'debit_note_id', p_debit_note_id,
    'action', v_action,
    'stock_reversed', (v_action = 'deduct')
  );
END;

declare
  v_org uuid;
  v_current int;
  v_required int;
begin
  select organisation_id, current_approval_level, required_approval_level
  into v_org, v_current, v_required
  from public.purchase_requisitions
  where id = p_requisition_id;

  if v_org is null then
    raise exception 'Requisition not found';
  end if;

  if upper(p_action) = 'REJECT' then
    update public.purchase_requisitions
    set approval_status = 'Rejected', status = 'Rejected'
    where id = p_requisition_id;

    insert into public.purchase_audit_log(organisation_id, entity_type, entity_id, action, actor_id, details)
    values (v_org, 'REQUISITION', p_requisition_id, 'REJECTED', p_actor_id, jsonb_build_object('comment', p_comment));
    return 'REJECTED';
  end if;

  if v_current + 1 >= v_required then
    update public.purchase_requisitions
    set approval_status = 'Approved', status = 'Approved', current_approval_level = v_required, approved_by = p_actor_id, approved_at = now()
    where id = p_requisition_id;

    perform public.approve_purchase_requisition(p_requisition_id);

    insert into public.purchase_audit_log(organisation_id, entity_type, entity_id, action, actor_id, details)
    values (v_org, 'REQUISITION', p_requisition_id, 'FINAL_APPROVED', p_actor_id, jsonb_build_object('comment', p_comment));
    return 'APPROVED';
  else
    update public.purchase_requisitions
    set current_approval_level = v_current + 1
    where id = p_requisition_id;

    insert into public.purchase_audit_log(organisation_id, entity_type, entity_id, action, actor_id, details)
    values (v_org, 'REQUISITION', p_requisition_id, 'LEVEL_APPROVED', p_actor_id, jsonb_build_object('new_level', v_current + 1, 'comment', p_comment));
    return 'PENDING_APPROVAL';
  end if;
end;

DECLARE
  v_bom RECORD;
  v_self_count INT;
  v_invalid_qty_count INT;
  v_items_count INT;
  v_overlap_count INT;
BEGIN
  -- 1. Validate user membership in organisation
  IF NOT EXISTS (
    SELECT 1 FROM user_organisations
    WHERE organisation_id = p_org_id AND user_id = auth.uid() AND status = 'active'
  ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Not an active member of this organisation');
  END IF;

  -- 2. Lock BOM Header FOR UPDATE
  SELECT * INTO v_bom
  FROM bom_headers
  WHERE id = p_bom_id
  FOR UPDATE;

  IF v_bom.id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'BOM not found');
  END IF;

  IF v_bom.organisation_id != p_org_id THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Organisation mismatch');
  END IF;

  -- 3. Idempotency Check: if already approved/published, return success
  IF v_bom.approval_status IN ('approved', 'published') THEN
    RETURN jsonb_build_object(
      'ok', true,
      'already_processed', true,
      'message', 'BOM is already published and immutable.',
      'bom_id', p_bom_id
    );
  END IF;

  -- 4. Validate component presence
  SELECT COUNT(*) INTO v_items_count
  FROM bom_items
  WHERE bom_id = p_bom_id;

  IF v_items_count = 0 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Cannot publish a BOM with zero components');
  END IF;

  -- 5. Validate non-self-reference (Finished product cannot be listed as its own component)
  SELECT COUNT(*) INTO v_self_count
  FROM bom_items
  WHERE bom_id = p_bom_id AND material_id = v_bom.product_id;

  IF v_self_count > 0 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Finished product cannot be listed as a component of itself');
  END IF;

  -- 6. Validate positive quantities
  SELECT COUNT(*) INTO v_invalid_qty_count
  FROM bom_items
  WHERE bom_id = p_bom_id AND (required_qty IS NULL OR required_qty <= 0);

  IF v_invalid_qty_count > 0 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'All BOM components must have a required quantity greater than 0');
  END IF;

  -- 7. Validate Date Range Effectivity Overlap against existing published revisions for same product
  SELECT COUNT(*) INTO v_overlap_count
  FROM bom_headers
  WHERE organisation_id = p_org_id
    AND product_id = v_bom.product_id
    AND id != p_bom_id
    AND is_active = true
    AND approval_status IN ('approved', 'published')
    AND daterange(
          COALESCE(effective_date, '1970-01-01'::date),
          COALESCE(valid_to, '9999-12-31'::date),
          '[]'
        ) && daterange(
          COALESCE(v_bom.effective_date, '1970-01-01'::date),
          COALESCE(v_bom.valid_to, '9999-12-31'::date),
          '[]'
        );

  IF v_overlap_count > 0 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Overlapping active published BOM revision exists for this product in the specified effective date range');
  END IF;

  -- 8. Update status from 'draft' to 'approved'.
  -- Trigger remains fully active; OLD.approval_status = 'draft' passes check naturally.
  UPDATE bom_headers
  SET approval_status = 'approved',
      updated_at = NOW()
  WHERE id = p_bom_id;

  -- 9. Log activity
  INSERT INTO manufacturing_activity_log (
    entity_type, entity_id, action, action_details, user_id, organisation_id
  ) VALUES (
    'bom', p_bom_id, 'completed',
    jsonb_build_object(
      'bom_code', v_bom.bom_code,
      'revision', v_bom.revision,
      'product_name', v_bom.product_name
    ),
    auth.uid(), p_org_id
  );

  RETURN jsonb_build_object(
    'ok', true,
    'already_processed', false,
    'bom_id', p_bom_id,
    'revision', v_bom.revision
  );
END;

BEGIN
  IF EXISTS (SELECT 1 FROM pg_proc WHERE proname = 'recalc_subcontractor_balances') THEN
    PERFORM public.recalc_subcontractor_balances(p_subcontractor_id, p_organisation_id);
  END IF;
END;

DECLARE
    v_total_billed NUMERIC(15,2) := 0;
    v_total_paid NUMERIC(15,2) := 0;
    v_total_retention_held NUMERIC(15,2) := 0;
    v_total_retention_released NUMERIC(15,2) := 0;
    v_balance NUMERIC(15,2) := 0;
BEGIN
    IF auth.uid() IS NOT NULL AND NOT public.user_can_access_org(p_organisation_id) THEN
        RAISE EXCEPTION 'Unauthorized organization access';
    END IF;

    -- Sum approved subcontractor bills
    SELECT COALESCE(SUM(amount), 0) INTO v_total_billed
    FROM public.subcontractor_invoices
    WHERE subcontractor_id = p_subcontractor_id AND organisation_id = p_organisation_id
      AND LOWER(COALESCE(status, '')) IN ('approved', 'posted', 'paid');

    -- Sum payments
    SELECT COALESCE(SUM(amount), 0) INTO v_total_paid
    FROM public.subcontractor_payments
    WHERE subcontractor_id = p_subcontractor_id AND organisation_id = p_organisation_id
      AND is_deleted = false
      AND (LOWER(COALESCE(workflow_step, '')) = 'released' OR LOWER(COALESCE(approval_status, '')) IN ('approved', 'released', 'posted', 'final'));

    -- Sum retention held
    SELECT COALESCE(SUM(retention_amount), 0) INTO v_total_retention_held
    FROM public.subcontractor_retention
    WHERE subcontractor_id = p_subcontractor_id AND organisation_id = p_organisation_id
      AND LOWER(COALESCE(status, '')) != 'cancelled';

    -- Sum retention released
    SELECT COALESCE(SUM(COALESCE(released_amount, retention_amount)), 0) INTO v_total_retention_released
    FROM public.subcontractor_retention
    WHERE subcontractor_id = p_subcontractor_id AND organisation_id = p_organisation_id
      AND LOWER(COALESCE(status, '')) = 'released';

    v_balance := v_total_billed - v_total_paid - (v_total_retention_held - v_total_retention_released);
END;

DECLARE
    v_total_bills NUMERIC(15,2) := 0;
    v_total_debits NUMERIC(15,2) := 0;
    v_total_paid NUMERIC(15,2) := 0;
    v_opening_bal NUMERIC(15,2) := 0;
    v_balance NUMERIC(15,2) := 0;
BEGIN
    IF auth.uid() IS NOT NULL AND NOT public.user_can_access_org(p_organisation_id) THEN
        RAISE EXCEPTION 'Unauthorized organization access';
    END IF;

    SELECT COALESCE(opening_balance, 0) INTO v_opening_bal
    FROM public.purchase_vendors
    WHERE id = p_vendor_id AND organisation_id = p_organisation_id;

    -- Sum approved bills
    SELECT COALESCE(SUM(total_amount), 0) INTO v_total_bills
    FROM public.purchase_bills
    WHERE vendor_id = p_vendor_id AND organisation_id = p_organisation_id
      AND LOWER(COALESCE(approval_status, '')) NOT IN ('cancelled', 'draft');

    -- Sum approved debit notes
    SELECT COALESCE(SUM(total_amount), 0) INTO v_total_debits
    FROM public.debit_notes
    WHERE vendor_id = p_vendor_id AND organisation_id = p_organisation_id
      AND LOWER(COALESCE(approval_status, '')) IN ('approved', 'posted', 'final');

    -- Sum released payments
    SELECT COALESCE(SUM(amount), 0) INTO v_total_paid
    FROM public.purchase_payments
    WHERE vendor_id = p_vendor_id AND organisation_id = p_organisation_id
      AND is_deleted = false
      AND (LOWER(COALESCE(workflow_step, '')) = 'released' OR LOWER(COALESCE(approval_status, '')) IN ('approved', 'released', 'posted', 'final'));

    v_balance := v_opening_bal + v_total_bills - v_total_debits - v_total_paid;
END;

DECLARE
  v_remaining_qty NUMERIC;
  v_planned_qty NUMERIC;
BEGIN
  IF auth.uid() IS NOT NULL AND NOT public.user_can_access_org(p_org_id) THEN
    RAISE EXCEPTION 'Unauthorized organization access';
  END IF;

  SELECT COALESCE(SUM(actual_qty), 0) INTO v_remaining_qty
  FROM production_entries
  WHERE job_card_id = p_job_card_id;

  SELECT planned_qty INTO v_planned_qty
  FROM job_cards
  WHERE id = p_job_card_id;

  IF v_remaining_qty >= v_planned_qty THEN
    UPDATE job_cards
    SET status = 'completed', completed_at = NOW(), updated_at = NOW()
    WHERE id = p_job_card_id;
  ELSIF v_remaining_qty > 0 THEN
    UPDATE job_cards
    SET status = 'in_progress', updated_at = NOW()
    WHERE id = p_job_card_id;
  END IF;
END;

DECLARE
  v_transfer RECORD;
  v_org_id UUID;
  v_user_id UUID;
  r_item RECORD;
  v_stock_id UUID;
  v_received_qty NUMERIC;
BEGIN
  v_user_id := auth.uid();

  SELECT * INTO v_transfer
  FROM public.stock_transfers
  WHERE id = p_transfer_id
  FOR UPDATE;

  IF v_transfer IS NULL THEN RAISE EXCEPTION 'Stock Transfer not found'; END IF;

  v_org_id := v_transfer.organisation_id;
  IF v_user_id IS NOT NULL AND NOT public.user_can_access_org(v_org_id) THEN
    RAISE EXCEPTION 'Unauthorized organization access';
  END IF;

  IF UPPER(COALESCE(v_transfer.status, '')) = 'RECEIVED' THEN
    RETURN jsonb_build_object('status', 'success', 'already_processed', true, 'transfer_id', p_transfer_id);
  END IF;

  FOR r_item IN SELECT * FROM public.stock_transfer_items WHERE transfer_id = p_transfer_id LOOP
    v_received_qty := r_item.quantity;

    SELECT id INTO v_stock_id
    FROM public.item_stock
    WHERE item_id = r_item.item_id
      AND warehouse_id = v_transfer.to_warehouse_id
      AND ((r_item.company_variant_id IS NULL AND company_variant_id IS NULL) OR company_variant_id = r_item.company_variant_id)
    FOR UPDATE;

    IF v_stock_id IS NOT NULL THEN
      UPDATE public.item_stock
      SET current_stock = current_stock + v_received_qty, updated_at = NOW()
      WHERE id = v_stock_id;
    ELSE
      INSERT INTO public.item_stock (
        organisation_id, item_id, warehouse_id, company_variant_id, current_stock
      ) VALUES (
        v_org_id, r_item.item_id, v_transfer.to_warehouse_id, r_item.company_variant_id, v_received_qty
      );
    END IF;

    INSERT INTO public.material_logs (
      organisation_id, item_id, variant_id,
      qty_received, qty_used, type, invoice_number, received_by, remarks, created_at
    ) VALUES (
      v_org_id, r_item.item_id, r_item.company_variant_id,
      v_received_qty, 0, 'IN', v_transfer.transfer_no, v_user_id,
      'Stock Transfer Receipt: ' || COALESCE(v_transfer.transfer_no, v_transfer.id::TEXT), NOW()
    );

    UPDATE public.stock_transfer_items
    SET received_qty = v_received_qty
    WHERE id = r_item.id;
  END LOOP;

  UPDATE public.stock_transfers
  SET status = 'RECEIVED', received_by_user_id = v_user_id, received_at = NOW(), updated_at = NOW()
  WHERE id = p_transfer_id;

  RETURN jsonb_build_object('status', 'success', 'transfer_id', p_transfer_id, 'doc_status', 'RECEIVED');
END;

DECLARE
  v_max NUMERIC;
  v_cur NUMERIC;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM user_organisations
     WHERE organisation_id = p_organisation_id AND user_id = auth.uid() AND status = 'active'
  ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Not a member of this organisation');
  END IF;
  IF p_quantity <= 0 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Quantity must be positive');
  END IF;

  -- Bin must belong to the caller's org. (max_quantity may legitimately be
  -- NULL — uncapped — so existence is checked separately.)
  SELECT max_quantity INTO v_max
    FROM warehouse_bins
   WHERE id = p_bin_id AND organisation_id = p_organisation_id AND deleted_at IS NULL;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Bin not found in this organisation');
  END IF;
  v_max := COALESCE(v_max, 0);

  SELECT COALESCE(SUM(quantity), 0) INTO v_cur
    FROM warehouse_bin_items
   WHERE bin_id = p_bin_id AND item_id IS NOT DISTINCT FROM p_item_id AND deleted_at IS NULL;
  IF v_max > 0 AND v_cur + p_quantity > v_max THEN
    RETURN jsonb_build_object('ok', false, 'error',
      'Bin capacity exceeded: ' || v_cur || ' + ' || p_quantity || ' > ' || v_max);
  END IF;

  INSERT INTO warehouse_bin_items (organisation_id, bin_id, item_id, quantity, is_primary, created_at, updated_at)
  VALUES (p_organisation_id, p_bin_id, p_item_id, p_quantity, true, now(), now())
  ON CONFLICT (bin_id, item_id)
  DO UPDATE SET quantity = warehouse_bin_items.quantity + EXCLUDED.quantity,
                deleted_at = NULL,
                updated_at = now();

  INSERT INTO warehouse_movements
    (organisation_id, movement_type, reference_type, reference_id, item_id,
     destination_bin_id, quantity, operator_id, device, remarks)
  VALUES
    (p_organisation_id, 'receive', 'receiving', NULL, p_item_id,
     p_bin_id, p_quantity, p_operator_id, p_device, p_remarks);

  RETURN jsonb_build_object('ok', true, 'bin_id', p_bin_id);
END;

DECLARE
  v_utilized DECIMAL(15,2);
  v_total    DECIMAL(15,2);
BEGIN
  SELECT COALESCE(po_total_value, 0) INTO v_total
  FROM client_purchase_orders
  WHERE id = p_po_id;

  IF v_total IS NULL THEN
    RETURN;
  END IF;

  SELECT COALESCE(SUM(total_amount), 0) INTO v_utilized
  FROM project_invoices
  WHERE po_id = p_po_id
    AND status <> 'Cancelled';

  -- Clamp at the PO total so we never show negative available value from
  -- a bad data entry.
  IF v_utilized < 0 THEN
    v_utilized := 0;
  ELSIF v_utilized > v_total THEN
    v_utilized := v_total;
  END IF;

  UPDATE client_purchase_orders
  SET
    po_utilized_value = v_utilized,
    po_available_value = v_total - v_utilized,
    updated_at = NOW()
  WHERE id = p_po_id;
END;

DECLARE
  v_utilized DECIMAL(15,2);
BEGIN
  PERFORM recompute_po_utilized_from_project_invoices(p_po_id);

  SELECT po_utilized_value INTO v_utilized
  FROM client_purchase_orders
  WHERE id = p_po_id;

  RETURN COALESCE(v_utilized, 0);
END;

DECLARE
  v_invoice RECORD;
  v_client RECORD;
  v_existing_cn RECORD;
  v_effective_idempotency_key TEXT;
  v_cn_id UUID;
  v_cn_number TEXT;
  v_item RECORD;
  v_line_qty NUMERIC(15,3);
  v_line_rate NUMERIC(15,2);
  v_line_tax_pct NUMERIC(5,2);
  v_line_taxable NUMERIC(15,2);
  v_line_cgst NUMERIC(15,2) := 0;
  v_line_sgst NUMERIC(15,2) := 0;
  v_line_igst NUMERIC(15,2) := 0;
  v_line_total NUMERIC(15,2);

  v_total_taxable NUMERIC(15,2) := 0;
  v_total_cgst NUMERIC(15,2) := 0;
  v_total_sgst NUMERIC(15,2) := 0;
  v_total_igst NUMERIC(15,2) := 0;
  v_grand_total NUMERIC(15,2) := 0;

  v_is_intrastate BOOLEAN := TRUE;
  v_org_state TEXT;
  v_client_state TEXT;

  v_sales_return_account_id UUID;
  v_ar_account_id UUID;
  v_journal_id UUID;
  v_remaining NUMERIC(15,2);
  v_result JSONB;
BEGIN
  -- A. Authentication & Tenant Authorization
  IF auth.uid() IS NOT NULL AND NOT public.user_can_access_org(p_organisation_id) THEN
    RAISE EXCEPTION 'Unauthorized organization access';
  END IF;

  IF p_client_id IS NULL THEN
    RAISE EXCEPTION 'Client ID is required';
  END IF;

  -- Validate client belongs to organisation
  SELECT * INTO v_client
  FROM public.clients
  WHERE id = p_client_id AND (organisation_id = p_organisation_id OR org_id = p_organisation_id);

  IF v_client IS NULL THEN
    RAISE EXCEPTION 'Client not found or does not belong to organization';
  END IF;

  -- Determine effective idempotency key
  v_effective_idempotency_key := TRIM(p_idempotency_key);
  IF v_effective_idempotency_key = '' THEN
    v_effective_idempotency_key := NULL;
  END IF;

  -- B. Pre-check Idempotency
  IF v_effective_idempotency_key IS NOT NULL THEN
    SELECT id, cn_number, total_amount, invoice_id INTO v_existing_cn
    FROM public.credit_notes
    WHERE organisation_id = p_organisation_id 
      AND idempotency_key = v_effective_idempotency_key
      AND approval_status IN ('Approved', 'posted', 'Final')
    LIMIT 1;

    IF v_existing_cn.id IS NOT NULL THEN
      SELECT id INTO v_journal_id
      FROM public.journal_entries
      WHERE company_id = p_organisation_id AND voucher_no = v_existing_cn.cn_number
      LIMIT 1;

      RETURN jsonb_build_object(
        'status', 'success',
        'cn_id', v_existing_cn.id,
        'cn_number', v_existing_cn.cn_number,
        'total_amount', v_existing_cn.total_amount,
        'invoice_id', v_existing_cn.invoice_id,
        'journal_id', v_journal_id,
        'idempotent_replayed', true
      );
    END IF;
  END IF;

  -- C. Validate Invoice Allocation (if invoice_id is supplied)
  IF p_invoice_id IS NOT NULL THEN
    SELECT * INTO v_invoice
    FROM public.invoices
    WHERE id = p_invoice_id
      AND (organisation_id = p_organisation_id OR org_id = p_organisation_id)
    FOR UPDATE;

    IF v_invoice IS NULL THEN
      RAISE EXCEPTION 'Invoice not found or does not belong to organization';
    END IF;

    IF v_invoice.client_id != p_client_id THEN
      RAISE EXCEPTION 'Invoice belongs to a different client than the supplied client';
    END IF;

    IF v_invoice.status != 'final' THEN
      RAISE EXCEPTION 'Cannot apply credit note to non-finalized invoice (status: %)', v_invoice.status;
    END IF;
  END IF;

  -- D. State Jurisdiction for Tax Calculation
  SELECT state INTO v_org_state FROM public.organisations WHERE id = p_organisation_id;
  v_client_state := v_client.state;
  IF v_org_state IS NOT NULL AND v_client_state IS NOT NULL AND LOWER(TRIM(v_org_state)) != LOWER(TRIM(v_client_state)) THEN
    v_is_intrastate := FALSE;
  END IF;

  -- E. Server-Side Calculations for Line Items
  IF jsonb_array_length(p_items) = 0 THEN
    RAISE EXCEPTION 'Credit note must contain at least one line item';
  END IF;

  FOR v_item IN SELECT * FROM jsonb_to_recordset(p_items) AS x(
    description TEXT, hsn_code TEXT, quantity NUMERIC, rate NUMERIC, tax_percent NUMERIC
  ) LOOP
    v_line_qty := COALESCE(v_item.quantity, 0);
    v_line_rate := COALESCE(v_item.rate, 0);
    v_line_tax_pct := COALESCE(v_item.tax_percent, 0);

    IF v_line_qty <= 0 OR v_line_rate <= 0 THEN
      RAISE EXCEPTION 'Line item quantity and rate must be greater than zero';
    END IF;

    v_line_taxable := ROUND(v_line_qty * v_line_rate, 2);

    IF v_is_intrastate THEN
      v_line_cgst := ROUND(v_line_taxable * (v_line_tax_pct / 200.0), 2);
      v_line_sgst := ROUND(v_line_taxable * (v_line_tax_pct / 200.0), 2);
      v_line_igst := 0;
    ELSE
      v_line_igst := ROUND(v_line_taxable * (v_line_tax_pct / 100.0), 2);
      v_line_cgst := 0;
      v_line_sgst := 0;
    END IF;

    v_line_total := v_line_taxable + v_line_cgst + v_line_sgst + v_line_igst;

    v_total_taxable := v_total_taxable + v_line_taxable;
    v_total_cgst := v_total_cgst + v_line_cgst;
    v_total_sgst := v_total_sgst + v_line_sgst;
    v_total_igst := v_total_igst + v_line_igst;
  END LOOP;

  v_grand_total := v_total_taxable + v_total_cgst + v_total_sgst + v_total_igst;

  IF v_grand_total <= 0 THEN
    RAISE E

DECLARE
  v_invoice RECORD;
  v_client RECORD;
  v_remaining NUMERIC(15,2);
  v_receipt_id UUID;
  v_receipt_no TEXT;
  v_bank_account_id UUID;
  v_ar_account_id UUID;
  v_journal_id UUID;
  v_new_paid_amount NUMERIC(15,2);
  v_existing_receipt RECORD;
  v_effective_idempotency_key TEXT;
  v_result JSONB;
BEGIN
  -- A. Authentication & Tenant Authorization
  IF auth.uid() IS NOT NULL AND NOT public.user_can_access_org(p_organisation_id) THEN
    RAISE EXCEPTION 'Unauthorized organization access';
  END IF;

  -- B. Parameter Validation
  IF p_amount IS NULL OR p_amount <= 0 THEN
    RAISE EXCEPTION 'Payment amount must be greater than zero';
  END IF;

  IF p_client_id IS NULL THEN
    RAISE EXCEPTION 'Client ID is required';
  END IF;

  -- Validate client belongs to organisation
  SELECT * INTO v_client
  FROM public.clients
  WHERE id = p_client_id AND (organisation_id = p_organisation_id OR org_id = p_organisation_id);

  IF v_client IS NULL THEN
    RAISE EXCEPTION 'Client not found or does not belong to organization';
  END IF;

  -- Determine effective idempotency key (use p_idempotency_key or fallback to p_reference_no if present)
  v_effective_idempotency_key := COALESCE(TRIM(p_idempotency_key), TRIM(p_reference_no));
  IF v_effective_idempotency_key = '' THEN
    v_effective_idempotency_key := NULL;
  END IF;

  -- C. Server-Side Idempotency Check (Pre-check)
  IF v_effective_idempotency_key IS NOT NULL THEN
    SELECT id, receipt_no, amount, invoice_id INTO v_existing_receipt
    FROM public.receipts
    WHERE org_id = p_organisation_id 
      AND idempotency_key = v_effective_idempotency_key
      AND status IN ('paid', 'posted')
    LIMIT 1;

    IF v_existing_receipt.id IS NOT NULL THEN
      IF p_invoice_id IS NOT NULL THEN
        SELECT COALESCE(paid_amount, 0) INTO v_new_paid_amount
        FROM public.invoices
        WHERE id = p_invoice_id;
      END IF;

      SELECT id INTO v_journal_id
      FROM public.journal_entries
      WHERE company_id = p_organisation_id AND voucher_no = v_existing_receipt.receipt_no
      LIMIT 1;

      RETURN jsonb_build_object(
        'status', 'success',
        'receipt_id', v_existing_receipt.id,
        'receipt_no', v_existing_receipt.receipt_no,
        'amount', v_existing_receipt.amount,
        'invoice_id', v_existing_receipt.invoice_id,
        'new_paid_amount', v_new_paid_amount,
        'journal_id', v_journal_id,
        'idempotent_replayed', true
      );
    END IF;
  END IF;

  -- D. Invoice Allocation Validation (if invoice_id is provided)
  IF p_invoice_id IS NOT NULL THEN
    SELECT * INTO v_invoice
    FROM public.invoices
    WHERE id = p_invoice_id
      AND (organisation_id = p_organisation_id OR org_id = p_organisation_id)
    FOR UPDATE;

    IF v_invoice IS NULL THEN
      RAISE EXCEPTION 'Invoice not found or does not belong to organization';
    END IF;

    -- Cross-client IDOR validation: Invoice client must match payment client
    IF v_invoice.client_id != p_client_id THEN
      RAISE EXCEPTION 'Invoice belongs to a different client than the payment client';
    END IF;

    -- Invoice status check: Invoice must be finalized
    IF v_invoice.status != 'final' THEN
      RAISE EXCEPTION 'Cannot record payments against non-finalized invoices (status: %)', v_invoice.status;
    END IF;

    -- Overpayment Check
    v_remaining := ROUND((v_invoice.total - COALESCE(v_invoice.paid_amount, 0))::NUMERIC, 2);
    IF p_amount > v_remaining THEN
      RAISE EXCEPTION 'Payment amount (₹%) exceeds invoice remaining balance (₹%)', p_amount, v_remaining;
    END IF;
  END IF;

  -- E. Set Transaction-Local Session Flag for Trigger Bypass
  PERFORM set_config('app.allow_posted_receipt_creation', 'true', true);

  -- F. Generate Receipt Number
  v_receipt_no := public.generate_next_receipt_number(p_organisation_id);

  -- G. Insert Receipt Record with Unique Constraint Protection
  BEGIN
    INSERT INTO public.receipts (
      org_id, client_id, invoice_id, receipt_no, amount,
      receipt_date, payment_type, payment_mode, reference_no,
      remarks, status, idempotency_key, created_by
    ) VALUES (
      p_organisation_id, p_client_id, p_invoice_id, v_receipt_no, p_amount,
      COALESCE(p_receipt_date, CURRENT_DATE), 'Payment', COALESCE(p_payment_mode, 'bank'), p_reference_no,
      p_remarks, 'paid', v_effective_idempotency_key, auth.uid()
    ) RETURNING id INTO v_receipt_id;
  EXCEPTION WHEN unique_violation THEN
    IF v_effective_idempotency_key IS NOT NULL THEN
      SELECT id, receipt_no, amount, invoice_id INTO v_existing_receipt
      FROM public.receipts
      WHERE org_id = p_organisation_id AND idempotency_key = v_effective_idempotency_key
      LIMIT 1;

      IF v_existing_receipt.id IS NOT NULL THEN
        IF p_invoice_id IS NOT NULL THEN
          SELECT COALESCE(paid_amount, 0) INTO v_new_paid_amount FROM public.invoices WHERE id = p_invoice_id;
        END IF;
        SELECT id INTO v_journal_id FROM public.journ

DECLARE
  v_bill RECORD;
  v_vendor RECORD;
  v_existing_dn RECORD;
  v_effective_idempotency_key TEXT;
  v_dn_id UUID;
  v_dn_number TEXT;
  v_item RECORD;
  v_line_qty NUMERIC(15,3);
  v_line_rate NUMERIC(15,2);
  v_line_tax_pct NUMERIC(5,2);
  v_line_taxable NUMERIC(15,2);
  v_line_cgst NUMERIC(15,2) := 0;
  v_line_sgst NUMERIC(15,2) := 0;
  v_line_igst NUMERIC(15,2) := 0;
  v_line_total NUMERIC(15,2);

  v_total_taxable NUMERIC(15,2) := 0;
  v_total_cgst NUMERIC(15,2) := 0;
  v_total_sgst NUMERIC(15,2) := 0;
  v_total_igst NUMERIC(15,2) := 0;
  v_grand_total NUMERIC(15,2) := 0;

  v_is_intrastate BOOLEAN := TRUE;
  v_org_state TEXT;
  v_vendor_state TEXT;

  v_ap_account_id UUID;
  v_purchase_return_account_id UUID;
  v_journal_id UUID;
  v_result JSONB;
BEGIN
  -- A. Authentication & Tenant Authorization
  IF auth.uid() IS NOT NULL AND NOT public.user_can_access_org(p_organisation_id) THEN
    RAISE EXCEPTION 'Unauthorized organization access';
  END IF;

  IF p_vendor_id IS NULL THEN
    RAISE EXCEPTION 'Vendor ID is required';
  END IF;

  -- Validate vendor belongs to organization
  SELECT * INTO v_vendor
  FROM public.purchase_vendors
  WHERE id = p_vendor_id AND organisation_id = p_organisation_id;

  IF v_vendor IS NULL THEN
    RAISE EXCEPTION 'Vendor not found or does not belong to organization';
  END IF;

  -- Determine effective idempotency key
  v_effective_idempotency_key := TRIM(p_idempotency_key);
  IF v_effective_idempotency_key = '' THEN
    v_effective_idempotency_key := NULL;
  END IF;

  -- B. Pre-check Idempotency
  IF v_effective_idempotency_key IS NOT NULL THEN
    SELECT id, dn_number, total_amount, bill_id INTO v_existing_dn
    FROM public.debit_notes
    WHERE organisation_id = p_organisation_id
      AND idempotency_key = v_effective_idempotency_key
      AND approval_status IN ('Approved', 'posted', 'Final')
    LIMIT 1;

    IF v_existing_dn.id IS NOT NULL THEN
      SELECT id INTO v_journal_id
      FROM public.journal_entries
      WHERE company_id = p_organisation_id AND voucher_no = v_existing_dn.dn_number
      LIMIT 1;

      RETURN jsonb_build_object(
        'status', 'success',
        'dn_id', v_existing_dn.id,
        'dn_number', v_existing_dn.dn_number,
        'total_amount', v_existing_dn.total_amount,
        'bill_id', v_existing_dn.bill_id,
        'journal_id', v_journal_id,
        'idempotent_replayed', true
      );
    END IF;
  END IF;

  -- C. Validate Bill Allocation (if bill_id is supplied)
  IF p_bill_id IS NOT NULL THEN
    SELECT * INTO v_bill
    FROM public.purchase_bills
    WHERE id = p_bill_id
      AND organisation_id = p_organisation_id
    FOR UPDATE;

    IF v_bill IS NULL THEN
      RAISE EXCEPTION 'Purchase bill not found or does not belong to organization';
    END IF;

    IF v_bill.vendor_id != p_vendor_id THEN
      RAISE EXCEPTION 'Purchase bill belongs to a different vendor than the supplied vendor';
    END IF;
  END IF;

  -- D. State Jurisdiction for Tax Calculation
  SELECT state INTO v_org_state FROM public.organisations WHERE id = p_organisation_id;
  v_vendor_state := v_vendor.state;
  IF v_org_state IS NOT NULL AND v_vendor_state IS NOT NULL AND LOWER(TRIM(v_org_state)) != LOWER(TRIM(v_vendor_state)) THEN
    v_is_intrastate := FALSE;
  END IF;

  -- E. Server-Side Calculations for Line Items
  IF jsonb_array_length(p_items) = 0 THEN
    RAISE EXCEPTION 'Debit note must contain at least one line item';
  END IF;

  FOR v_item IN SELECT * FROM jsonb_to_recordset(p_items) AS x(
    item_name TEXT, hsn_code TEXT, quantity NUMERIC, rate NUMERIC, tax_percent NUMERIC
  ) LOOP
    v_line_qty := COALESCE(v_item.quantity, 0);
    v_line_rate := COALESCE(v_item.rate, 0);
    v_line_tax_pct := COALESCE(v_item.tax_percent, 0);

    IF v_line_qty <= 0 OR v_line_rate <= 0 THEN
      RAISE EXCEPTION 'Line item quantity and rate must be greater than zero';
    END IF;

    v_line_taxable := ROUND(v_line_qty * v_line_rate, 2);

    IF v_is_intrastate THEN
      v_line_cgst := ROUND(v_line_taxable * (v_line_tax_pct / 200.0), 2);
      v_line_sgst := ROUND(v_line_taxable * (v_line_tax_pct / 200.0), 2);
      v_line_igst := 0;
    ELSE
      v_line_igst := ROUND(v_line_taxable * (v_line_tax_pct / 100.0), 2);
      v_line_cgst := 0;
      v_line_sgst := 0;
    END IF;

    v_line_total := v_line_taxable + v_line_cgst + v_line_sgst + v_line_igst;

    v_total_taxable := v_total_taxable + v_line_taxable;
    v_total_cgst := v_total_cgst + v_line_cgst;
    v_total_sgst := v_total_sgst + v_line_sgst;
    v_total_igst := v_total_igst + v_line_igst;
  END LOOP;

  v_grand_total := v_total_taxable + v_total_cgst + v_total_sgst + v_total_igst;

  IF v_grand_total <= 0 THEN
    RAISE EXCEPTION 'Debit note total must be greater than zero';
  END IF;

  -- F. Set Transaction Creation Flag & Generate Number
  PERFORM set_config('app.allow_posted_dn_creation', 'true', true);
  v_dn_number := public.generate_next_dn_number(p_organisation_id);

  -- G.

DECLARE
  v_grn RECORD;
  v_org_id UUID;
  v_user_id UUID;
  v_target_wh UUID := p_warehouse_id;
  r_item RECORD;
  v_stock_id UUID;
  v_qty NUMERIC;
BEGIN
  v_user_id := auth.uid();

  SELECT * INTO v_grn
  FROM public.goods_receipt_notes
  WHERE id = p_grn_id
  FOR UPDATE;

  IF v_grn IS NULL THEN
    RAISE EXCEPTION 'GRN not found';
  END IF;

  v_org_id := v_grn.organisation_id;
  IF v_user_id IS NOT NULL AND NOT public.user_can_access_org(v_org_id) THEN
    RAISE EXCEPTION 'Unauthorized organization access';
  END IF;

  IF v_grn.status = 'accepted' THEN
    RETURN jsonb_build_object('status', 'success', 'already_processed', true, 'grn_id', p_grn_id);
  END IF;

  IF v_target_wh IS NULL THEN
    SELECT id INTO v_target_wh 
    FROM public.warehouses 
    WHERE organisation_id = v_org_id 
      AND (warehouse_purpose = 'main' OR is_default = TRUE)
      AND is_active = TRUE
    ORDER BY is_default DESC, created_at ASC
    LIMIT 1;

    IF v_target_wh IS NULL THEN
      SELECT id INTO v_target_wh 
      FROM public.warehouses 
      WHERE organisation_id = v_org_id AND is_active = TRUE
      LIMIT 1;
    END IF;
  END IF;

  IF v_target_wh IS NULL THEN
    RAISE EXCEPTION 'No active warehouse found for receiving goods';
  END IF;

  -- Process items
  IF p_accepted_items IS NOT NULL AND jsonb_array_length(p_accepted_items) > 0 THEN
    FOR r_item IN SELECT * FROM jsonb_to_recordset(p_accepted_items) AS x(
      item_id uuid,
      material_id uuid,
      variant_id uuid,
      accepted_qty numeric,
      received_qty numeric
    )
    LOOP
      v_qty := COALESCE(r_item.accepted_qty, r_item.received_qty, 0);
      IF r_item.material_id IS NOT NULL AND v_qty > 0 THEN
        SELECT id INTO v_stock_id
        FROM public.item_stock
        WHERE item_id = r_item.material_id
          AND warehouse_id = v_target_wh
          AND ((r_item.variant_id IS NULL AND company_variant_id IS NULL) OR company_variant_id = r_item.variant_id)
        FOR UPDATE;

        IF v_stock_id IS NOT NULL THEN
          UPDATE public.item_stock
          SET current_stock = current_stock + v_qty, updated_at = NOW()
          WHERE id = v_stock_id;
        ELSE
          INSERT INTO public.item_stock (
            organisation_id, item_id, warehouse_id, company_variant_id, current_stock
          ) VALUES (
            v_org_id, r_item.material_id, v_target_wh, r_item.variant_id, v_qty
          );
        END IF;

        INSERT INTO public.material_logs (
          organisation_id, item_id, variant_id,
          qty_received, qty_used, type, invoice_number, received_by, remarks, created_at
        ) VALUES (
          v_org_id, r_item.material_id, r_item.variant_id,
          v_qty, 0, 'IN', v_grn.grn_no, v_user_id,
          'GRN Acceptance: ' || COALESCE(v_grn.grn_no, v_grn.id::TEXT), NOW()
        );

        IF r_item.item_id IS NOT NULL THEN
          UPDATE public.grn_items
          SET accepted_qty = v_qty, status = 'accepted'
          WHERE id = r_item.item_id;
        END IF;
      END IF;
    END LOOP;
  ELSE
    FOR r_item IN SELECT id, material_id, accepted_qty, received_qty FROM public.grn_items WHERE grn_id = p_grn_id LOOP
      v_qty := CASE WHEN r_item.accepted_qty > 0 THEN r_item.accepted_qty ELSE r_item.received_qty END;
      IF r_item.material_id IS NOT NULL AND v_qty > 0 THEN
        SELECT id INTO v_stock_id
        FROM public.item_stock
        WHERE item_id = r_item.material_id
          AND warehouse_id = v_target_wh
          AND company_variant_id IS NULL
        FOR UPDATE;

        IF v_stock_id IS NOT NULL THEN
          UPDATE public.item_stock
          SET current_stock = current_stock + v_qty, updated_at = NOW()
          WHERE id = v_stock_id;
        ELSE
          INSERT INTO public.item_stock (
            organisation_id, item_id, warehouse_id, company_variant_id, current_stock
          ) VALUES (
            v_org_id, r_item.material_id, v_target_wh, NULL, v_qty
          );
        END IF;

        INSERT INTO public.material_logs (
          organisation_id, item_id, variant_id,
          qty_received, qty_used, type, invoice_number, received_by, remarks, created_at
        ) VALUES (
          v_org_id, r_item.material_id, NULL,
          v_qty, 0, 'IN', v_grn.grn_no, v_user_id,
          'GRN Acceptance: ' || COALESCE(v_grn.grn_no, v_grn.id::TEXT), NOW()
        );

        UPDATE public.grn_items
        SET accepted_qty = v_qty, status = 'accepted'
        WHERE id = r_item.id;
      END IF;
    END LOOP;
  END IF;

  UPDATE public.goods_receipt_notes
  SET status = 'accepted', updated_at = NOW()
  WHERE id = p_grn_id;

  RETURN jsonb_build_object('status', 'success', 'grn_id', p_grn_id, 'warehouse_id', v_target_wh);
END;

DECLARE
  v_entry_id UUID;
  v_org_id UUID;
  v_user_id UUID;
  v_product_id UUID;
  v_actual_qty NUMERIC;
  v_entry_no TEXT;
  r_item RECORD;
  v_stock_id UUID;
  v_current_stock NUMERIC;
  v_deduct_wip NUMERIC;
BEGIN
  v_user_id := auth.uid();

  v_org_id := (p_entry_data->>'organisation_id')::UUID;
  IF v_user_id IS NOT NULL AND NOT public.user_can_access_org(v_org_id) THEN
    RAISE EXCEPTION 'Unauthorized organization access';
  END IF;

  v_entry_no := p_entry_data->>'entry_no';
  v_product_id := (p_entry_data->>'product_id')::UUID;
  v_actual_qty := COALESCE((p_entry_data->>'actual_qty')::NUMERIC, 0);

  -- Insert production entry
  INSERT INTO public.production_entries (
    entry_no, job_card_id, entry_date, produced_qty, actual_qty,
