    (p_entry_data->>'yield_pct')::NUMERIC, p_entry_data->>'quality_notes', p_entry_data->>'batch_no',
    COALESCE((p_entry_data->>'production_date')::DATE, CURRENT_DATE), (p_entry_data->>'reported_by')::UUID, v_user_id,
    v_org_id, p_entry_data->>'notes', p_entry_data->>'operator_name', p_entry_data->>'machine_name', 'completed'
  ) RETURNING id INTO v_entry_id;

  -- 1. Deduct consumed materials from WIP & return excess to Store
  IF p_items IS NOT NULL AND jsonb_array_length(p_items) > 0 THEN
    FOR r_item IN SELECT * FROM jsonb_to_recordset(p_items) AS x(
      job_card_material_id uuid,
      material_id uuid,
      variant_id uuid,
      issued_qty numeric,
      consumed_qty numeric,
      wastage_qty numeric,
      return_qty numeric,
      remarks text
    )
    LOOP
      v_deduct_wip := COALESCE(r_item.consumed_qty, 0) + COALESCE(r_item.wastage_qty, 0);

      IF r_item.material_id IS NOT NULL AND v_deduct_wip > 0 THEN
        SELECT id, current_stock INTO v_stock_id, v_current_stock
        FROM public.item_stock
        WHERE item_id = r_item.material_id
          AND warehouse_id = p_wip_wh
          AND ((r_item.variant_id IS NULL AND company_variant_id IS NULL) OR company_variant_id = r_item.variant_id)
        FOR UPDATE;

        IF v_stock_id IS NULL OR v_current_stock < v_deduct_wip THEN
          RAISE EXCEPTION 'Insufficient WIP stock for material %: available %, required %',
            r_item.material_id, COALESCE(v_current_stock, 0), v_deduct_wip;
        END IF;

        UPDATE public.item_stock
        SET current_stock = current_stock - v_deduct_wip, updated_at = NOW()
        WHERE id = v_stock_id;

        INSERT INTO public.material_logs (
          organisation_id, item_id, variant_id,
          qty_received, qty_used, type, invoice_number, received_by, remarks, created_at
        ) VALUES (
          v_org_id, r_item.material_id, r_item.variant_id,
          0, v_deduct_wip, 'OUT', v_entry_no, v_user_id,
          'Production Consumed: ' || v_entry_no, NOW()
        );
      END IF;

      -- Material return from WIP -> Main Store
      IF r_item.material_id IS NOT NULL AND COALESCE(r_item.return_qty, 0) > 0 THEN
        -- Deduct from WIP
        SELECT id, current_stock INTO v_stock_id, v_current_stock
        FROM public.item_stock
        WHERE item_id = r_item.material_id
          AND warehouse_id = p_wip_wh
          AND ((r_item.variant_id IS NULL AND company_variant_id IS NULL) OR company_variant_id = r_item.variant_id)
        FOR UPDATE;

        IF v_stock_id IS NOT NULL AND v_current_stock >= r_item.return_qty THEN
          UPDATE public.item_stock
          SET current_stock = current_stock - r_item.return_qty, updated_at = NOW()
          WHERE id = v_stock_id;
        END IF;

        -- Add to Main Store
        SELECT id INTO v_stock_id
        FROM public.item_stock
        WHERE item_id = r_item.material_id
          AND warehouse_id = p_main_wh
          AND ((r_item.variant_id IS NULL AND company_variant_id IS NULL) OR company_variant_id = r_item.variant_id)
        FOR UPDATE;

        IF v_stock_id IS NOT NULL THEN
          UPDATE public.item_stock
          SET current_stock = current_stock + r_item.return_qty, updated_at = NOW()
          WHERE id = v_stock_id;
        ELSE
          INSERT INTO public.item_stock (
            organisation_id, item_id, warehouse_id, company_variant_id, current_stock
          ) VALUES (
            v_org_id, r_item.material_id, p_main_wh, r_item.variant_id, r_item.return_qty
          );
        END IF;

        INSERT INTO public.material_logs (
          organisation_id, item_id, variant_id,
          qty_received, qty_used, type, invoice_number, received_by, remarks, created_at
        ) VALUES (
          v_org_id, r_item.material_id, r_item.

DECLARE
  v_client RECORD; v_org RECORD; v_is_intra_state BOOLEAN := TRUE; v_item JSONB;
  v_line_qty NUMERIC(15,4); v_line_rate NUMERIC(15,2); v_disc_pct NUMERIC(5,2); v_tax_pct NUMERIC(5,2);
  v_gross NUMERIC(15,2); v_disc_amt NUMERIC(15,2); v_taxable NUMERIC(15,2);
  v_subtotal NUMERIC(15,2) := 0; v_cgst NUMERIC(15,2) := 0; v_sgst NUMERIC(15,2) := 0; v_igst NUMERIC(15,2) := 0; v_total NUMERIC(15,2) := 0;
  v_proforma_id UUID; v_pi_number TEXT; v_existing_id UUID;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF NOT public.user_can_access_org(p_organisation_id) THEN RAISE EXCEPTION 'Unauthorized organization access'; END IF;

  IF p_idempotency_key IS NOT NULL THEN
    SELECT id INTO v_existing_id FROM public.proforma_invoices WHERE organisation_id = p_organisation_id AND idempotency_key = p_idempotency_key;
    IF v_existing_id IS NOT NULL THEN
      SELECT pi_number, total INTO v_pi_number, v_total FROM public.proforma_invoices WHERE id = v_existing_id;
      RETURN jsonb_build_object('status', 'success', 'idempotent_replayed', true, 'proforma_id', v_existing_id, 'pi_number', v_pi_number, 'total', v_total);
    END IF;
  END IF;

  SELECT * INTO v_client FROM public.clients WHERE id = p_client_id AND organisation_id = p_organisation_id;
  IF v_client IS NULL THEN RAISE EXCEPTION 'Client not found or does not belong to organization'; END IF;
  SELECT * INTO v_org FROM public.organisations WHERE id = p_organisation_id;
  IF v_client.state IS NOT NULL AND v_org.state IS NOT NULL THEN
    IF LOWER(TRIM(v_client.state)) != LOWER(TRIM(v_org.state)) THEN v_is_intra_state := FALSE; END IF;
  END IF;

  IF jsonb_array_length(p_items) = 0 THEN RAISE EXCEPTION 'Proforma invoice must contain at least one line item'; END IF;

  v_pi_number := public.generate_next_proforma_number_v2(p_organisation_id);

  PERFORM set_config('app.allow_posted_proforma_creation', 'true', true);
  INSERT INTO public.proforma_invoices (
    pi_number, organisation_id, client_id, status, company_state, client_state, subtotal, cgst, sgst, igst, total, notes, terms, po_number, po_date, idempotency_key
  ) VALUES (
    v_pi_number, p_organisation_id, p_client_id, 'draft', v_org.state, v_client.state, 0, 0, 0, 0, 0, p_notes, p_terms, p_po_number, p_po_date, p_idempotency_key
  ) RETURNING id INTO v_proforma_id;
  PERFORM set_config('app.allow_posted_proforma_creation', 'false', true);

  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items) LOOP
    v_line_qty := COALESCE((v_item->>'qty')::NUMERIC, 1);
    v_line_rate := COALESCE((v_item->>'rate')::NUMERIC, 0);
    v_disc_pct := COALESCE((v_item->>'discount_percent')::NUMERIC, 0);
    v_tax_pct := COALESCE((v_item->>'tax_percent')::NUMERIC, 18);
    IF v_line_qty <= 0 OR v_line_rate < 0 THEN RAISE EXCEPTION 'Line item quantity and rate must be valid non-negative values'; END IF;

    v_gross := ROUND((v_line_qty * v_line_rate)::NUMERIC, 2);
    v_disc_amt := ROUND((v_gross * (v_disc_pct / 100.0))::NUMERIC, 2);
    v_taxable := v_gross - v_disc_amt;
    v_subtotal := v_subtotal + v_taxable;

    IF v_is_intra_state THEN
      v_cgst := v_cgst + ROUND((v_taxable * (v_tax_pct / 2.0 / 100.0))::NUMERIC, 2);
      v_sgst := v_sgst + ROUND((v_taxable * (v_tax_pct / 2.0 / 100.0))::NUMERIC, 2);
    ELSE
      v_igst := v_igst + ROUND((v_taxable * (v_tax_pct / 100.0))::NUMERIC, 2);
    END IF;

    INSERT INTO public.proforma_items (
      proforma_id, organisation_id, item_id, description, qty, rate, amount, discount_percent, discount_amount, tax_percent
    ) VALUES (
      v_proforma_id, p_organisation_id, (v_item->>'item_id')::UUID, COALESCE(v_item->>'description', 'Line Item'), v_line_qty, v_line_rate, v_taxable, v_disc_pct, v_disc_amt, v_tax_pct
    );
  END LOOP;

  v_total := v_subtotal + v_cgst + v_sgst + v_igst;
  UPDATE public.proforma_invoices SET subtotal = v_subtotal, cgst = v_cgst, sgst = v_sgst, igst = v_igst, total = v_total WHERE id = v_proforma_id;

  RETURN jsonb_build_object('status', 'success', 'proforma_id', v_proforma_id, 'pi_number', v_pi_number, 'subtotal', v_subtotal, 'cgst', v_cgst, 'sgst', v_sgst, 'igst', v_igst, 'total', v_total);
END;

