  v_gross_amt := p_amount;
  v_tds_amt   := ROUND((v_gross_amt * (COALESCE(p_tds_percent, 0) / 100.0))::NUMERIC, 2);
  v_net_amt   := v_gross_amt - v_tds_amt;

  IF p_reference_no IS NOT NULL AND p_reference_no != '' THEN
