    'Subcontractor Payment ' || v_ref_no || ' (' || v_sub.company_name || ')', 'Posted', v_creator_id
  ) RETURNING id INTO v_journal_id;

  INSERT INTO public.journal_entry_lines (journal_id, account_id, party_type, party_id, debit, credit, narration)
  VALUES (v_journal_id, v_ap_account_id, 'vendor', p_subcontractor_id, v_gross_amt, 0.00, 'Accounts Payable Settlement');

  INSERT INTO public.journal_entry_lines (journal_id, account_id, party_type, party_id, debit, credit, narration)
  VALUES (v_journal_id, v_bank_account_id, 'vendor', p_subcontractor_id, 0.00, v_net_amt, 'Bank / Cash Disbursement');

  IF v_tds_amt > 0 THEN
    INSERT INTO public.journal_entry_lines (journal_id, account_id, pa

DECLARE
  v_sub RECORD; v_wo_id UUID; v_wo_no TEXT; v_existing_id UUID; v_item JSONB;
  v_qty NUMERIC(15,4); v_rate NUMERIC(15,2); v_subtotal NUMERIC(15,2) := 0; v_total_amount NUMERIC(15,2) := 0;
  v_retention_amount NUMERIC(15,2) := 0; v_tds_amount NUMERIC(15,2) := 0;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF NOT public.user_can_access_org(p_organisation_id) THEN RAISE EXCEPTION 'Unauthorized organization access'; END IF;

  IF p_idempotency_key IS NOT NULL THEN
    SELECT id INTO v_existing_id FROM public.subcontractor_work_orders WHERE organisation_id = p_organisation_id AND idempotency_key = p_idempotency_key;
    IF v_existing_id IS NOT NULL THEN
      SELECT work_order_no, total_amount INTO v_wo_no, v_total_amount FROM public.subcontractor_work_orders WHERE id = v_existing_id;
      RETURN jsonb_build_object('status', 'success', 'idempotent_replayed', true, 'work_order_id', v_existing_id, 'work_order_no', v_wo_no, 'total_amount', v_total_amount);
    END IF;
  END IF;

  SELECT * INTO v_sub FROM public.subcontractors WHERE id = p_subcontractor_id AND organisation_id = p_organisation_id;
  IF v_sub IS NULL THEN RAISE EXCEPTION 'Subcontractor not found or does not belong to organization'; END IF;

  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items) LOOP
    v_qty := COALESCE((v_item->>'quantity')::NUMERIC, (v_item->>'qty')::NUMERIC, 1);
    v_rate := COALESCE((v_item->>'rate')::NUMERIC, 0);
    IF v_qty <= 0 OR v_rate < 0 THEN RAISE EXCEPTION 'Work order item quantity and rate must be valid non-negative numbers'; END IF;
    v_subtotal := v_subtotal + ROUND((v_qty * v_rate)::NUMERIC, 2);
  END LOOP;

  v_total_amount := v_subtotal;
  v_retention_amount := ROUND((v_total_amount * (COALESCE(p_retention_percent, 0) / 100.0))::NUMERIC, 2);
  v_tds_amount := ROUND((v_total_amount * (COALESCE(p_tds_percent, 0) / 100.0))::NUMERIC, 2);
  v_wo_no := public.generate_next_work_order_number(p_organisation_id);

  INSERT INTO public.subcontractor_work_orders (
    work_order_no, organisation_id, subcontractor_id, project_id, status, issue_date, start_date, end_date, work_description, site_location, line_items, subtotal, total_amount, retention_percent, retention_amount, tds_percent, tds_amount, created_by, idempotency_key
  ) VALUES (
    v_wo_no, p_organisation_id, p_subcontractor_id, p_project_id, 'Draft', CURRENT_DATE, p_start_date, p_end_date, p_work_description, p_site_location, p_items, v_subtotal, v_total_amount, p_retention_percent, v_retention_amount, p_tds_percent, v_tds_amount, auth.uid(), p_idempotency_key
  ) RETURNING id INTO v_wo_id;

  RETURN jsonb_build_object('status', 'success', 'work_order_id', v_wo_id, 'work_order_no', v_wo_no, 'subtotal', v_subtotal, 'total_amount', v_total_amount);
END;

DECLARE
  v_vendor RECORD;
  v_existing_payment RECORD;
  v_effective_idempotency_key TEXT;
  v_payment_id UUID;
  v_voucher_no TEXT;
  v_alloc RECORD;
  v_bill RECORD;
  v_alloc_amount NUMERIC(15,2);
  v_total_allocated NUMERIC(15,2) := 0;
  v_remaining_balance NUMERIC(15,2);
  v_new_paid NUMERIC(15,2);
  v_new_balance NUMERIC(15,2);
  v_new_status TEXT;

  v_bank_account_id UUID;
  v_ap_account_id UUID;
  v_journal_id UUID;
  v_result JSONB;
BEGIN
  -- A. Authentication & Tenant Authorization
  IF auth.uid() IS NOT NULL AND NOT public.user_can_access_org(p_organisation_id) THEN
    RAISE EXCEPTION 'Unauthorized organization access';
  END IF;

  IF p_vendor_id IS NULL THEN
    RAISE EXCEPTION 'Vendor ID is required';
  END IF;

  IF p_amount IS NULL OR p_amount <= 0 THEN
    RAISE EXCEPTION 'Payment amount must be greater than zero';
  END IF;

  -- Validate vendor belongs to organization
  SELECT * INTO v_vendor
  FROM public.purchase_vendors
  WHERE id = p_vendor_id AND organisation_id = p_organisation_id;

  IF v_vendor IS NULL THEN
    RAISE EXCEPTION 'Vendor not found or does not belong to organization';
  END IF;

  -- Determine effective idempotency key
  v_effective_idempotency_key := COALESCE(NULLIF(TRIM(p_idempotency_key), ''), NULLIF(TRIM(p_reference_no), ''));

  -- B. Pre-check Idempotency
  IF v_effective_idempotency_key IS NOT NULL THEN
    SELECT id, voucher_no, amount INTO v_existing_payment
    FROM public.purchase_payments
    WHERE organisation_id = p_organisation_id
      AND idempotency_key = v_effective_idempotency_key
      AND (workflow_step = 'released' OR approval_status IN ('Approved', 'Released', 'posted', 'Final'))
    LIMIT 1;

    IF v_existing_payment.id IS NOT NULL THEN
      SELECT id INTO v_journal_id
      FROM public.journal_entries
      WHERE company_id = p_organisation_id AND voucher_no = v_existing_payment.voucher_no
      LIMIT 1;

      RETURN jsonb_build_object(
        'status', 'success',
        'payment_id', v_existing_payment.id,
        'voucher_no', v_existing_payment.voucher_no,
        'amount', v_existing_payment.amount,
        'journal_id', v_journal_id,
        'idempotent_replayed', true
      );
    END IF;
  END IF;

  -- C. Validate Allocations and Lock Bills FOR UPDATE
  IF jsonb_array_length(p_bill_allocations) > 0 THEN
    FOR v_alloc IN SELECT * FROM jsonb_to_recordset(p_bill_allocations) AS x(
      bill_id UUID, adjusted_amount NUMERIC
    ) LOOP
      v_alloc_amount := COALESCE(v_alloc.adjusted_amount, 0);
      IF v_alloc_amount <= 0 THEN
        RAISE EXCEPTION 'Bill allocation amount must be greater than zero';
      END IF;

      -- Lock bill
      SELECT * INTO v_bill
      FROM public.purchase_bills
      WHERE id = v_alloc.bill_id AND organisation_id = p_organisation_id
      FOR UPDATE;

      IF v_bill IS NULL THEN
        RAISE EXCEPTION 'Purchase bill % not found in this organization', v_alloc.bill_id;
      END IF;

      IF v_bill.vendor_id != p_vendor_id THEN
        RAISE EXCEPTION 'Purchase bill % belongs to a different vendor', v_bill.bill_number;
      END IF;

      v_remaining_balance := ROUND(v_bill.total_amount - COALESCE(v_bill.paid_amount, 0), 2);
      IF v_alloc_amount > v_remaining_balance THEN
        RAISE EXCEPTION 'Allocation amount (₹%) exceeds bill % remaining balance (₹%)', v_alloc_amount, v_bill.bill_number, v_remaining_balance;
      END IF;

      v_total_allocated := v_total_allocated + v_alloc_amount;
    END LOOP;

    IF v_total_allocated > p_amount THEN
      RAISE EXCEPTION 'Total allocated amount (₹%) cannot exceed total payment amount (₹%)', v_total_allocated, p_amount;
    END IF;
  END IF;

  -- D. Set Transaction Creation Flag & Generate Voucher Number
  PERFORM set_config('app.allow_posted_purchase_payment_creation', 'true', true);
  v_voucher_no := public.generate_next_payment_voucher_number(p_organisation_id);

  -- E. Insert Payment Record with Race-Safe Unique Violation Handling
  BEGIN
    INSERT INTO public.purchase_payments (
      organisation_id, vendor_id, voucher_no, payment_date, amount,
      net_amount, reference_no, narration, is_advance, advance_remaining,
      payment_mode, workflow_step, approval_status, approved_by, approved_at,
      released_by, released_at, released_amount, idempotency_key, created_at
    ) VALUES (
      p_organisation_id, p_vendor_id, v_voucher_no, COALESCE(p_payment_date, CURRENT_DATE), p_amount,
      p_amount, p_reference_no, p_narration, COALESCE(p_is_advance, false),
      CASE WHEN p_is_advance THEN p_amount - v_total_allocated ELSE 0 END,
      COALESCE(p_payment_mode, 'Bank Transfer'), 'released', 'Released', auth.uid(), NOW(),
      auth.uid(), NOW(), p_amount, v_effective_idempotency_key, NOW()
    ) RETURNING id INTO v_payment_id;
  EXCEPTION WHEN unique_violation THEN
    IF v_effective_idempotency_key IS NOT NULL THEN
      SELECT id, voucher_no, amount INTO v_existing_payment
      FROM public.purchase_payments
      WHERE organisat

