DECLARE
  v_org UUID;
  v_src UUID;
  v_reserved NUMERIC;
  v_status TEXT;
BEGIN
  SELECT organisation_id, source_bin_id, status, reserved_qty
    INTO v_org, v_src, v_status, v_reserved
    FROM warehouse_dispatches WHERE id = p_dispatch_id;
  IF v_org IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Dispatch not found');
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM user_organisations
     WHERE organisation_id = v_org AND user_id = auth.uid() AND status = 'active'
  ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Not a member of this organisation');
  END IF;
  IF v_status NOT IN ('reserved','picking','packing') THEN
    RETURN jsonb_build_object('ok', false, 'error',
      'Cannot release reservation from status ' || v_status);
  END IF;

  -- Release the bin's reservation (never below zero).
  UPDATE warehouse_bins
     SET reserved_quantity = GREATEST(0, COALESCE(reserved_quantity, 0) - COALESCE(v_reserved, 0)),
         updated_at = now()
   WHERE id = v_src;

  UPDATE warehouse_dispatches
     SET status = 'cancelled',
         reserved_qty = 0,
         cancelled_at = now(),
         updated_at = now()
   WHERE id = p_dispatch_id;

  RETURN jsonb_build_object('ok', true);
END;

DECLARE
  v_qc RECORD;
  v_fg_store_id UUID;
  v_rejection_store_id UUID;
  v_wip_store_id UUID;
  v_stock RECORD;
  v_inward_id UUID;
  v_prod_name TEXT;
  v_prod_unit TEXT;
BEGIN
  -- 1. Verify user organisation membership
  IF NOT EXISTS (
    SELECT 1 FROM user_organisations
    WHERE organisation_id = p_org_id AND user_id = auth.uid() AND status = 'active'
  ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Not an active member of this organisation');
  END IF;

  -- 2. Lock QC inspection row FOR UPDATE for thread safety
  SELECT id, inspection_no, product_id, inspection_date, inspection_result,
         accepted_qty, rejected_qty, rework_qty, batch_no, organisation_id
  INTO v_qc
  FROM fg_qc_inspections
  WHERE id = p_inspection_id
  FOR UPDATE;

  IF v_qc.id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'QC Inspection not found');
  END IF;

  IF v_qc.organisation_id != p_org_id THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Organisation mismatch');
  END IF;

  -- 3. Idempotency Check: if already released, return success without duplicating stock
  IF v_qc.inspection_result = 'released' THEN
    RETURN jsonb_build_object(
      'ok', true,
      'already_processed', true,
      'message', 'QC Inspection stock has already been released.',
      'inspection_id', p_inspection_id
    );
  END IF;

  -- Get product name and unit
  SELECT name, unit INTO v_prod_name, v_prod_unit
  FROM materials WHERE id = v_qc.product_id;

  -- 4. Resolve Target Warehouses (FG, Rejection, WIP)
  SELECT id INTO v_fg_store_id
  FROM warehouses
  WHERE organisation_id = p_org_id AND warehouse_purpose = 'fg' AND is_active = true
  LIMIT 1;

  IF v_fg_store_id IS NULL THEN
    SELECT id INTO v_fg_store_id
    FROM warehouses
    WHERE organisation_id = p_org_id AND is_default = true AND is_active = true
    LIMIT 1;
  END IF;

  SELECT id INTO v_rejection_store_id
  FROM warehouses
  WHERE organisation_id = p_org_id AND warehouse_purpose = 'rejection' AND is_active = true
  LIMIT 1;

  SELECT id INTO v_wip_store_id
  FROM warehouses
  WHERE organisation_id = p_org_id AND warehouse_purpose = 'wip' AND is_active = true
  LIMIT 1;

  IF v_fg_store_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Finished Goods (FG) Warehouse not found');
  END IF;

  -- 5. Process Accepted Quantity -> Finished Goods Warehouse
  IF COALESCE(v_qc.accepted_qty, 0) > 0 THEN
    SELECT id, current_stock INTO v_stock
    FROM item_stock
    WHERE item_id = v_qc.product_id
      AND warehouse_id = v_fg_store_id
      AND organisation_id = p_org_id
    FOR UPDATE;

    IF v_stock.id IS NULL THEN
      INSERT INTO item_stock (item_id, warehouse_id, current_stock, organisation_id, is_active)
      VALUES (v_qc.product_id, v_fg_store_id, v_qc.accepted_qty, p_org_id, true)
      RETURNING id INTO v_stock.id;
    ELSE
      UPDATE item_stock
      SET current_stock = current_stock + v_qc.accepted_qty,
          updated_at = NOW()
      WHERE id = v_stock.id;
    END IF;

    -- Audit Log: Material Inward for Accepted FG
    INSERT INTO material_inward (
      inward_date, remarks, organisation_id, supply_type
    ) VALUES (
      COALESCE(v_qc.inspection_date, CURRENT_DATE),
      'QC Inspection ' || v_qc.inspection_no || ' — Finished Goods Accepted',
      p_org_id,
      'MANUFACTURING'
    ) RETURNING id INTO v_inward_id;

    INSERT INTO material_inward_items (
      material_inward_id, material_name, quantity, unit, material_id, warehouse_id, organisation_id
    ) VALUES (
      v_inward_id,
      COALESCE(v_prod_name, ''),
      v_qc.accepted_qty,
      COALESCE(v_prod_unit, 'nos'),
      v_qc.product_id,
      v_fg_store_id,
      p_org_id
    );
  END IF;

  -- 6. Process Rejected Quantity -> Rejection Warehouse
  IF COALESCE(v_qc.rejected_qty, 0) > 0 AND v_rejection_store_id IS NOT NULL THEN
    SELECT id, current_stock INTO v_stock
    FROM item_stock
    WHERE item_id = v_qc.product_id
      AND warehouse_id = v_rejection_store_id
      AND organisation_id = p_org_id
    FOR UPDATE;

    IF v_stock.id IS NULL THEN
      INSERT INTO item_stock (item_id, warehouse_id, current_stock, organisation_id, is_active)
      VALUES (v_qc.product_id, v_rejection_store_id, v_qc.rejected_qty, p_org_id, true)
      RETURNING id INTO v_stock.id;
    ELSE
      UPDATE item_stock
      SET current_stock = current_stock + v_qc.rejected_qty,
          updated_at = NOW()
      WHERE id = v_stock.id;
    END IF;
  END IF;

  -- 7. Process Rework Quantity -> WIP Warehouse
  IF COALESCE(v_qc.rework_qty, 0) > 0 AND v_wip_store_id IS NOT NULL THEN
    SELECT id, current_stock INTO v_stock
    FROM item_stock
    WHERE item_id = v_qc.product_id
      AND warehouse_id = v_wip_store_id
      AND organisation_id = p_org_id
    FOR UPDATE;

    IF v_stock.id IS NULL THEN
      INSERT INTO item_stock (item_id, warehouse_id, current_stock, organisation_id, is_active)
      VALUES (v_qc.product_id, v_wip_store_id, v_qc.

DECLARE
  v_ret RECORD; v_wo RECORD; v_retention_account_id UUID; v_bank_account_id UUID;
  v_journal_id UUID; v_ref_no TEXT; v_creator_id UUID;
  v_total_debit NUMERIC(15,2); v_total_credit NUMERIC(15,2);
BEGIN
  IF auth.uid() IS NOT NULL AND NOT public.user_can_access_org(p_organisation_id) THEN
    RAISE EXCEPTION 'Unauthorized organization access';
  END IF;

  SELECT id INTO v_creator_id FROM public.user_profiles WHERE user_id = auth.uid() OR id = auth.uid() LIMIT 1;

  SELECT * INTO v_ret FROM public.subcontractor_retention WHERE id = p_retention_id FOR UPDATE;
  IF v_ret.id IS NULL THEN RAISE EXCEPTION 'Retention record not found'; END IF;

  SELECT * INTO v_wo FROM public.subcontractor_work_orders WHERE id = v_ret.work_order_id AND organisation_id = p_organisation_id;
  IF v_wo.id IS NULL THEN RAISE EXCEPTION 'Work order for retention does not belong to organization'; END IF;

  IF v_ret.status = 'Released' THEN
    RETURN jsonb_build_object('status', 'already_released', 'retention_id', p_retention_id, 'retention_amount', v_ret.retention_amount);
  END IF;

  SELECT id INTO v_retention_account_id FROM public.accounts WHERE (organisation_id = p_organisation_id OR company_id = p_organisation_id) AND account_code = '2150' LIMIT 1;
  IF LOWER(p_payment_mode) LIKE '%cash%' THEN
    SELECT id INTO v_bank_account_id FROM public.accounts WHERE (organisation_id = p_organisation_id OR company_id = p_organisation_id) AND account_code IN ('1300','1301') ORDER BY account_code DESC LIMIT 1;
  ELSE
    SELECT id INTO v_bank_account_id FROM public.accounts WHERE (organisation_id = p_organisation_id OR company_id = p_organisation_id) AND account_code = '1200' LIMIT 1;
  END IF;

  IF v_retention_account_id IS NULL THEN
    v_retention_account_id := public.ensure_gl_account_exists(p_organisation_id, '2150', 'Retention Payable', 'Liability');
  END IF;
  IF v_bank_account_id IS NULL THEN
    v_bank_account_id := public.ensure_gl_account_exists(p_organisation_id, '1200', 'Bank Account - Primary', 'Asset');
  END IF;

  v_ref_no := COALESCE(p_payment_reference, 'RET-REL-' || p_retention_id::TEXT);

  UPDATE public.subcontractor_retention
  SET status = 'Released', actual_release_date = p_release_date, payment_reference = v_ref_no, idempotency_key = p_idempotency_key
  WHERE id = p_retention_id;

  INSERT INTO public.journal_entries (
    company_id, voucher_no, voucher_date, voucher_type, narration, status, created_by
  ) VALUES (
    p_organisation_id, v_ref_no, p_release_date, 'Payment'::public.voucher_type,
    'Retention Release for Work Order ' || v_wo.work_order_no, 'Posted', v_creator_id
  ) RETURNING id INTO v_journal_id;

  INSERT INTO public.journal_entry_lines (journal_id, account_id, party_type, party_id, debit, credit, narration)
  VALUES (v_journal_id, v_retention_account_id, 'vendor', v_wo.subcontractor_id, v_ret.retention_amount, 0.00, 'Retention Liability Discharge');

  INSERT INTO public.journal_entry_lines (journal_id, account_id, party_type, party_id, debit, credit, narration)
  VALUES (v_journal_id, v_bank_account_id, 'vendor', v_wo.subcontractor_id, 0.00, v_ret.retention_amount, 'Bank Disbursement for Retention');

  SELECT SUM(COALESCE(debit,0)), SUM(COALESCE(credit,0))
  INTO v_total_debit, v_total_credit
  FROM public.journal_entry_lines WHERE journal_id = v_journal_id;

  IF ABS(v_total_debit - v_total_credit) > 0.01 THEN
    RAISE EXCEPTION 'GL imbalance: debit=% credit=%. Transaction rolled back.', v_total_debit, v_total_credit;
  END IF;

  RETURN jsonb_build_object(
    'status', 'success', 'retention_id', p_retention_id,
    'released_amount', v_ret.retention_amount, 'journal_id', v_journal_id,
    'gl_debit', v_total_debit, 'gl_credit', v_total_credit
  );
END;

DECLARE
  v_user_id UUID;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  DELETE FROM project_collaboration_reactions
   WHERE message_id = p_message_id AND user_id = v_user_id AND emoji = p_emoji;
END;

DECLARE
  v_org UUID;
  v_bin UUID;
  v_item UUID;
  v_qty NUMERIC;
BEGIN
  SELECT organisation_id, bin_id, item_id, quantity
    INTO v_org, v_bin, v_item, v_qty
    FROM warehouse_bin_items
   WHERE id = p_row_id AND deleted_at IS NULL;
  IF v_org IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Bin item row not found');
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM user_organisations
     WHERE organisation_id = v_org AND user_id = auth.uid() AND status = 'active'
  ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Not a member of this organisation');
  END IF;

  -- Defense-in-depth: the row is org-scoped, but the bin it references must
  -- also belong to the org (same hardening as the 006 transfer RPC).
  IF NOT EXISTS (
    SELECT 1 FROM warehouse_bins
     WHERE id = v_bin AND organisation_id = v_org AND deleted_at IS NULL
  ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Bin not found in this organisation');
  END IF;

  UPDATE warehouse_bin_items
     SET deleted_at = now(), quantity = 0, updated_by = p_operator_id, updated_at = now()
   WHERE id = p_row_id;

  IF COALESCE(v_qty, 0) <> 0 THEN
    INSERT INTO warehouse_movements
      (organisation_id, movement_type, reference_type, reference_id, item_id,
       source_bin_id, quantity, operator_id, device, remarks)
    VALUES
      (v_org, 'adjust', 'adjustment', p_row_id::TEXT, v_item,
       v_bin, -v_qty, p_operator_id, p_device,
       COALESCE(p_remarks, 'Item removed from bin (Movement Engine)'));
  END IF;

  RETURN jsonb_build_object('ok', true, 'bin_item_id', p_row_id, 'removed_qty', v_qty);
END;

DECLARE
  v_src_qty NUMERIC;
  v_ok BOOLEAN;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM user_organisations
     WHERE organisation_id = p_organisation_id AND user_id = auth.uid() AND status = 'active'
  ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Not a member of this organisation');
  END IF;
  IF p_quantity <= 0 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Quantity must be positive');
  END IF;

  SELECT COUNT(*) = 2 INTO v_ok
    FROM warehouse_bins
   WHERE id IN (p_source_bin_id, p_destination_bin_id)
     AND organisation_id = p_organisation_id AND deleted_at IS NULL;
  IF NOT v_ok THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Source/destination bin not found in this organisation');
  END IF;

  -- Available = quantity minus reserved (reserved stock cannot be consumed).
  SELECT COALESCE(SUM(bi.quantity), 0) - COALESCE(b.reserved_quantity, 0) INTO v_src_qty
    FROM warehouse_bins b
    LEFT JOIN warehouse_bin_items bi
      ON bi.bin_id = b.id AND bi.item_id IS NOT DISTINCT FROM p_item_id AND bi.deleted_at IS NULL
   WHERE b.id = p_source_bin_id;
  IF v_src_qty < p_quantity THEN
    RETURN jsonb_build_object('ok', false, 'error',
      'Insufficient unreserved bulk stock: ' || v_src_qty || ' < ' || p_quantity);
  END IF;

  UPDATE warehouse_bin_items
     SET quantity = GREATEST(0, quantity - p_quantity), updated_at = now()
   WHERE bin_id = p_source_bin_id AND item_id IS NOT DISTINCT FROM p_item_id AND deleted_at IS NULL;
  UPDATE warehouse_bin_items
     SET deleted_at = now(), quantity = 0, updated_at = now()
   WHERE bin_id = p_source_bin_id AND item_id IS NOT DISTINCT FROM p_item_id
     AND quantity <= 0 AND deleted_at IS NULL;

  INSERT INTO warehouse_bin_items (organisation_id, bin_id, item_id, quantity, is_primary, created_at, updated_at)
  VALUES (p_organisation_id, p_destination_bin_id, p_item_id, p_quantity, false, now(), now())
  ON CONFLICT (bin_id, item_id)
  DO UPDATE SET quantity = warehouse_bin_items.quantity + EXCLUDED.quantity,
                deleted_at = NULL,
                updated_at = now();

  INSERT INTO warehouse_movements
    (organisation_id, movement_type, reference_type, reference_id, item_id,
     source_bin_id, destination_bin_id, quantity, operator_id, device, remarks)
  VALUES
    (p_organisation_id, 'replenish', 'replenishment', NULL, p_item_id,
     p_source_bin_id, p_destination_bin_id, p_quantity, p_operator_id, p_device,
     'Bulk → Picking replenishment');

  RETURN jsonb_build_object('ok', true);
END;

DECLARE
  v_org UUID;
  v_item_id UUID;
  v_qty NUMERIC;
  v_src UUID;
  v_reserved NUMERIC;
  v_available NUMERIC;
  v_status TEXT;
BEGIN
  SELECT organisation_id, item_id, quantity, source_bin_id, status
    INTO v_org, v_item_id, v_qty, v_src, v_status
    FROM warehouse_dispatches WHERE id = p_dispatch_id;

  IF v_org IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Dispatch not found');
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM user_organisations
     WHERE organisation_id = v_org AND user_id = auth.uid() AND status = 'active'
  ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Not a member of this organisation');
  END IF;
  IF v_status NOT IN ('draft','reserved') THEN
    RETURN jsonb_build_object('ok', false, 'error',
      'Cannot reserve a dispatch in status ' || v_status);
  END IF;

  -- Bin must belong to the org AND have enough unreserved stock.
  -- COALESCE + NOT FOUND: a bin with a NULL (never-reserved) reserved_quantity
  -- must NOT be reported as "not found" — only a genuinely missing bin may.
  SELECT COALESCE(reserved_quantity, 0) INTO v_reserved
    FROM warehouse_bins
   WHERE id = v_src AND organisation_id = v_org AND deleted_at IS NULL;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Source bin not found in this organisation');
  END IF;

  -- Conservative by design: subtract the bin's TOTAL reserved_quantity
  -- (across all items) from this item's stock. Never over-commits; may
  -- under-count availability for a different item sharing the bin.
  -- (TAD §5.11 — reserved stock is unavailable to every consumer.)

  SELECT COALESCE(SUM(quantity), 0) - COALESCE(v_reserved, 0) INTO v_available
    FROM warehouse_bin_items
   WHERE bin_id = v_src AND item_id IS NOT DISTINCT FROM v_item_id AND deleted_at IS NULL;
  IF v_available < v_qty THEN
    RETURN jsonb_build_object('ok', false, 'error',
      'Insufficient unreserved stock: ' || v_available || ' < ' || v_qty);
  END IF;

  -- Post the reservation on the bin AND the dispatch.
  UPDATE warehouse_bins
     SET reserved_quantity = COALESCE(reserved_quantity, 0) + v_qty,
         updated_at = now()
   WHERE id = v_src;
  UPDATE warehouse_dispatches
     SET status = 'reserved',
         reserved_qty = v_qty,
         reserved_at = COALESCE(reserved_at, now()),
         updated_at = now()
   WHERE id = p_dispatch_id;

  RETURN jsonb_build_object('ok', true, 'dispatch_id', p_dispatch_id, 'reserved_qty', v_qty);
END;

DECLARE
  v_bom_ids UUID[];
  v_count INT;
  v_mat_name VARCHAR;
BEGIN
  SELECT ARRAY_AGG(id) INTO v_bom_ids
  FROM bom_headers
  WHERE product_id = p_material_id
    AND is_active = true
    AND approval_status IN ('approved', 'published')
    AND (effective_date IS NULL OR effective_date <= p_production_date)
    AND (valid_to IS NULL OR valid_to >= p_production_date);

  v_count := COALESCE(CARDINALITY(v_bom_ids), 0);

  IF v_count = 0 THEN
    RETURN NULL; -- Leaf raw material (no subassembly BOM)
  ELSIF v_count = 1 THEN
    RETURN v_bom_ids[1]; -- Single deterministic active BOM
  ELSE
    SELECT name INTO v_mat_name FROM materials WHERE id = p_material_id;
    RAISE EXCEPTION 'Ambiguous BOM revision: Found % active published BOM revisions for material % (%) on date %',
      v_count, COALESCE(v_mat_name, 'Unknown'), p_material_id, p_production_date;
  END IF;
END;

DECLARE
  v_job_card RECORD;
  v_main_store_id UUID;
  v_wip_store_id UUID;
  v_mat_id UUID;
  v_return_qty NUMERIC;
  v_mat RECORD;
  v_wip_stock RECORD;
  v_main_stock RECORD;
  v_inward_id UUID;
BEGIN
  SELECT id, status, organisation_id INTO v_job_card
  FROM job_cards WHERE id = p_job_card_id;

  IF v_job_card.id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Job card not found');
  END IF;

  IF v_job_card.organisation_id != p_org_id THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Organisation mismatch');
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM user_organisations
    WHERE organisation_id = p_org_id AND user_id = auth.uid() AND status = 'active'
  ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Not a member of this organisation');
  END IF;

  SELECT id INTO v_main_store_id
  FROM warehouses
  WHERE organisation_id = p_org_id AND warehouse_purpose = 'main' AND is_active = true
  LIMIT 1;

  IF v_main_store_id IS NULL THEN
    SELECT id INTO v_main_store_id
    FROM warehouses
    WHERE organisation_id = p_org_id AND is_default = true AND is_active = true
    LIMIT 1;
  END IF;

  SELECT id INTO v_wip_store_id
  FROM warehouses
  WHERE organisation_id = p_org_id AND warehouse_purpose = 'wip' AND is_active = true
  LIMIT 1;

  IF v_wip_store_id IS NULL THEN
    SELECT id INTO v_wip_store_id
    FROM warehouses
    WHERE organisation_id = p_org_id AND is_active = true AND id != v_main_store_id
    LIMIT 1;
  END IF;

  IF v_main_store_id IS NULL OR v_wip_store_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Required warehouses (Main Store / WIP) not found');
  END IF;

  INSERT INTO material_inward (inward_date, vendor_name, remarks, organisation_id, supply_type)
  VALUES (CURRENT_DATE, 'Production Return', 'Job Card - materials returned from production', p_org_id, 'WAREHOUSE')
  RETURNING id INTO v_inward_id;

  FOR v_mat_id, v_return_qty IN
    SELECT key, value::NUMERIC
    FROM jsonb_each(p_return_quantities)
  LOOP
    IF v_return_qty IS NULL OR v_return_qty <= 0 THEN
      CONTINUE;
    END IF;

    SELECT id, name, unit INTO v_mat
    FROM materials WHERE id = v_mat_id;

    SELECT id, current_stock INTO v_wip_stock
    FROM item_stock
    WHERE item_id = v_mat_id
      AND warehouse_id = v_wip_store_id
      AND organisation_id = p_org_id
    FOR UPDATE;

    IF v_wip_stock.id IS NULL THEN
      RETURN jsonb_build_object('ok', false, 'error',
        'No WIP stock for material ' || COALESCE(v_mat.name, v_mat_id::text));
    END IF;

    IF v_wip_stock.current_stock < v_return_qty THEN
      RETURN jsonb_build_object('ok', false, 'error',
        'Insufficient stock in WIP for ' || COALESCE(v_mat.name, v_mat_id::text) ||
        ': available ' || v_wip_stock.current_stock || ', attempting to return ' || v_return_qty);
    END IF;

    UPDATE item_stock
    SET current_stock = GREATEST(0, current_stock - v_return_qty),
        updated_at = NOW()
    WHERE id = v_wip_stock.id;

    SELECT id, current_stock INTO v_main_stock
    FROM item_stock
    WHERE item_id = v_mat_id
      AND warehouse_id = v_main_store_id
      AND organisation_id = p_org_id
    FOR UPDATE;

    IF v_main_stock.id IS NULL THEN
      INSERT INTO item_stock (item_id, warehouse_id, current_stock, organisation_id, is_active)
      VALUES (v_mat_id, v_main_store_id, v_return_qty, p_org_id, true)
      RETURNING id INTO v_main_stock.id;
    ELSE
      UPDATE item_stock
      SET current_stock = current_stock + v_return_qty,
          updated_at = NOW()
      WHERE id = v_main_stock.id;
    END IF;

    INSERT INTO material_inward_items (
      material_inward_id, material_name, quantity, unit, material_id, warehouse_id, organisation_id
    ) VALUES (
      v_inward_id,
      COALESCE(v_mat.name, ''),
      v_return_qty,
      COALESCE(v_mat.unit, ''),
      v_mat_id,
      v_main_store_id,
      p_org_id
    );

    UPDATE job_card_materials
    SET return_qty = COALESCE(return_qty, 0) + v_return_qty,
        status = 'returned',
        updated_at = NOW()
    WHERE job_card_id = p_job_card_id AND material_id = v_mat_id;
  END LOOP;

  RETURN jsonb_build_object('ok', true, 'job_card_id', p_job_card_id);
END;

DECLARE
    v_entry RECORD;
    v_job_card RECORD;
    v_mat RECORD;
    v_wh_wip UUID;
    v_wh_fg UUID;
    v_wh_main UUID;
    v_reversal_id UUID;
    v_fg_product_id UUID;
BEGIN
    SELECT * INTO v_entry FROM production_entries WHERE id = p_entry_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Production entry not found';
    END IF;

    IF auth.uid() IS NOT NULL AND NOT public.user_can_access_org(v_entry.organisation_id) THEN
      RAISE EXCEPTION 'Unauthorized organization access';
    END IF;

    IF v_entry.actual_qty < 0 THEN
        RAISE EXCEPTION 'Cannot reverse a reversal entry';
    END IF;

    SELECT * INTO v_job_card FROM job_cards WHERE id = v_entry.job_card_id;

    -- Resolve warehouses
    SELECT id INTO v_wh_wip FROM warehouses WHERE organisation_id = v_entry.organisation_id AND warehouse_purpose = 'wip' AND is_active = true LIMIT 1;
    SELECT id INTO v_wh_fg FROM warehouses WHERE organisation_id = v_entry.organisation_id AND warehouse_purpose = 'fg' AND is_active = true LIMIT 1;
    SELECT id INTO v_wh_main FROM warehouses WHERE organisation_id = v_entry.organisation_id AND (warehouse_purpose = 'main' OR is_default = true) AND is_active = true LIMIT 1;

    INSERT INTO production_entries (
        organisation_id, job_card_id, entry_date, actual_qty, rejected_qty,
        operator_name, shift, remarks, created_by
    ) VALUES (
        v_entry.organisation_id, v_entry.job_card_id, CURRENT_DATE,
        -v_entry.actual_qty, -v_entry.rejected_qty,
        v_entry.operator_name, v_entry.shift,
        'REVERSAL of Entry ' || p_entry_id, auth.uid()
    ) RETURNING id INTO v_reversal_id;

    FOR v_mat IN SELECT * FROM production_entry_materials WHERE production_entry_id = p_entry_id LOOP
        INSERT INTO production_entry_materials (
            production_entry_id, material_id, estimated_qty,
            actual_qty, consumed_qty, wastage_qty, return_qty,
            job_card_material_id
        ) VALUES (
            v_reversal_id, v_mat.material_id, 0,
            0, -v_mat.consumed_qty, -v_mat.wastage_qty, -v_mat.return_qty,
            v_mat.job_card_material_id
        );

        IF v_wh_wip IS NOT NULL THEN
          UPDATE item_stock 
          SET current_stock = current_stock + (v_mat.consumed_qty + v_mat.wastage_qty)
          WHERE item_id = v_mat.material_id AND warehouse_id = v_wh_wip AND organisation_id = v_entry.organisation_id;
        END IF;

        IF v_mat.return_qty > 0 AND v_wh_main IS NOT NULL THEN
            UPDATE item_stock 
            SET current_stock = current_stock - v_mat.return_qty
            WHERE item_id = v_mat.material_id AND warehouse_id = v_wh_main AND organisation_id = v_entry.organisation_id;
        END IF;

        IF v_mat.job_card_material_id IS NOT NULL THEN
            UPDATE job_card_materials
            SET consumed_qty = consumed_qty - v_mat.consumed_qty,
                wastage_qty = wastage_qty - v_mat.wastage_qty,
                return_qty = return_qty - v_mat.return_qty
            WHERE id = v_mat.job_card_material_id;
        END IF;
    END LOOP;

    SELECT id INTO v_fg_product_id FROM materials WHERE name = v_job_card.product_name AND organisation_id = v_entry.organisation_id LIMIT 1;

    IF v_fg_product_id IS NOT NULL AND v_entry.actual_qty > 0 AND v_wh_fg IS NOT NULL THEN
        UPDATE item_stock
        SET current_stock = current_stock - v_entry.actual_qty
        WHERE item_id = v_fg_product_id AND warehouse_id = v_wh_fg AND organisation_id = v_entry.organisation_id;
    END IF;

    UPDATE job_cards
    SET actual_qty = GREATEST(0, actual_qty - v_entry.actual_qty),
        status = 'in_progress'
    WHERE id = v_entry.job_card_id;

    RETURN v_reversal_id;
END;

DECLARE
  v_entry RECORD;
  v_org_id UUID;
  v_user_id UUID;
  v_product_id UUID;
  r_item RECORD;
  v_stock_id UUID;
  v_current_stock NUMERIC;
  v_consumed_wastage NUMERIC;
BEGIN
  v_user_id := auth.uid();

  SELECT * INTO v_entry FROM public.production_entries WHERE id = p_entry_id FOR UPDATE;
  IF v_entry IS NULL THEN RAISE EXCEPTION 'Production entry not found'; END IF;

  v_org_id := v_entry.organisation_id;
  IF v_user_id IS NOT NULL AND NOT public.user_can_access_org(v_org_id) THEN
    RAISE EXCEPTION 'Unauthorized organization access';
  END IF;

  IF v_entry.status = 'reversed' THEN
    RETURN jsonb_build_object('status', 'success', 'already_processed', true, 'entry_id', p_entry_id);
  END IF;

  -- 1. Reverse FG stock
  IF COALESCE(v_entry.actual_qty, 0) > 0 THEN
    -- Try bom_headers product_id first
    SELECT bom_headers.product_id INTO v_product_id
    FROM public.job_cards
    JOIN public.bom_headers ON bom_headers.id = job_cards.bom_id
    WHERE job_cards.id = v_entry.job_card_id;

    -- If null, look up materials by product_name
    IF v_product_id IS NULL THEN
      SELECT m.id INTO v_product_id
      FROM public.job_cards jc
      JOIN public.materials m ON (m.name = jc.product_name AND m.organisation_id = jc.organisation_id)
      WHERE jc.id = v_entry.job_card_id
      LIMIT 1;
    END IF;

    IF v_product_id IS NOT NULL THEN
      SELECT id, current_stock INTO v_stock_id, v_current_stock
      FROM public.item_stock
      WHERE item_id = v_product_id AND warehouse_id = p_fg_wh AND company_variant_id IS NULL
      FOR UPDATE;

      IF v_stock_id IS NOT NULL AND v_current_stock >= v_entry.actual_qty THEN
        UPDATE public.item_stock SET current_stock = current_stock - v_entry.actual_qty, updated_at = NOW() WHERE id = v_stock_id;
        INSERT INTO public.material_logs (
          organisation_id, item_id, variant_id, qty_received, qty_used, type, invoice_number, received_by, remarks, created_at
        ) VALUES (
          v_org_id, v_product_id, NULL, 0, v_entry.actual_qty, 'OUT', v_entry.entry_no, v_user_id, 'Production Reversal FG Deduction: ' || v_entry.entry_no, NOW()
        );
      END IF;
    END IF;
  END IF;

  -- 2. Reverse Materials (Credit back WIP, Deduct from Store if returned)
  FOR r_item IN SELECT * FROM public.production_entry_items WHERE production_entry_id = p_entry_id LOOP
    v_consumed_wastage := COALESCE(r_item.consumed_qty, 0) + COALESCE(r_item.wastage_qty, 0);

    -- Credit WIP
    IF v_consumed_wastage > 0 THEN
      SELECT id INTO v_stock_id
      FROM public.item_stock
      WHERE item_id = r_item.material_id AND warehouse_id = p_wip_wh AND company_variant_id IS NULL
      FOR UPDATE;

      IF v_stock_id IS NOT NULL THEN
        UPDATE public.item_stock SET current_stock = current_stock + v_consumed_wastage, updated_at = NOW() WHERE id = v_stock_id;
      ELSE
        INSERT INTO public.item_stock (organisation_id, item_id, warehouse_id, company_variant_id, current_stock)
        VALUES (v_org_id, r_item.material_id, p_wip_wh, NULL, v_consumed_wastage);
      END IF;

      INSERT INTO public.material_logs (
        organisation_id, item_id, variant_id, qty_received, qty_used, type, invoice_number, received_by, remarks, created_at
      ) VALUES (
        v_org_id, r_item.material_id, NULL, v_consumed_wastage, 0, 'IN', v_entry.entry_no, v_user_id, 'Production Reversal WIP Restored: ' || v_entry.entry_no, NOW()
      );
    END IF;

    -- If returned to Store, reverse from Store
    IF COALESCE(r_item.return_qty, 0) > 0 THEN
      SELECT id, current_stock INTO v_stock_id, v_current_stock
      FROM public.item_stock
      WHERE item_id = r_item.material_id AND warehouse_id = p_main_wh AND company_variant_id IS NULL
      FOR UPDATE;

      IF v_stock_id IS NOT NULL AND v_current_stock >= r_item.return_qty THEN
