  v_p0_7_passed INT := 0; v_p0_7_failed INT := 0;

  v_total_passed INT := 0;
  v_total_failed INT := 0;
  v_total_vectors INT := 0;
  v_overall_rate NUMERIC(5,2);
  v_master_verdict TEXT;
  v_elem JSONB;
BEGIN
  -- Execute P0.3 Suite (Inventory & Multi-warehouse)
  BEGIN
    v_p0_3 := public.run_p0_3_inventory_forensic_verification_suite();
    v_p0_3_passed := COALESCE((v_p0_3->>'passed')::INT, 0);
    v_p0_3_failed := COALESCE((v_p0_3->>'failed')::INT, 0);
  EXCEPTION WHEN OTHERS THEN
    v_p0_3_failed := 28;
    v_p0_3 := jsonb_build_object('error', SQLERRM, 'passed', 0, 'failed', 28, 'total_vectors', 28);
  END;

  -- Execute P0.4 Suite (Financial Core & GL Double-Entry)
  BEGIN
    v_p0_4 := public.run_p0_4_financial_forensic_verification_suite();
    v_p0_4_passed := COALESCE((v_p0_4->>'passed')::INT, 0);
    v_p0_4_failed := COALESCE((v_p0_4->>'failed')::INT, 0);
  EXCEPTION WHEN OTHERS THEN
    v_p0_4_failed := 16;
    v_p0_4 := jsonb_build_object('error', SQLERRM, 'passed', 0, 'failed', 16, 'total_vectors', 16);
  END;

  -- Execute P0.5 Suite (Purchase Orders, GRNs & Invoices)
  BEGIN
    v_p0_5 := public.run_p0_5_purchase_forensic_verification_suite();
    IF jsonb_typeof(v_p0_5) = 'array' THEN
      FOR v_elem IN SELECT * FROM jsonb_array_elements(v_p0_5)
      LOOP
        IF v_elem->>'status' = 'PASS' THEN
          v_p0_5_passed := v_p0_5_passed + 1;
        ELSE
          v_p0_5_failed := v_p0_5_failed + 1;
        END IF;
      END LOOP;
    ELSE
      v_p0_5_passed := COALESCE((v_p0_5->>'passed')::INT, 0);
      v_p0_5_failed := COALESCE((v_p0_5->>'failed')::INT, 0);
    END IF;
  EXCEPTION WHEN OTHERS THEN
    v_p0_5_failed := 32;
    v_p0_5 := jsonb_build_object('error', SQLERRM, 'passed', 0, 'failed', 32, 'total_vectors', 32);
  END;

  -- Execute P0.6 Suite (Sales Orders, Invoices, Delivery & Credit Notes)
  BEGIN
    v_p0_6 := public.run_p0_6_sales_forensic_verification_suite();
    v_p0_6_passed := COALESCE((v_p0_6->>'passed')::INT, 0);
    v_p0_6_failed := COALESCE((v_p0_6->>'failed')::INT, 0);
  EXCEPTION WHEN OTHERS THEN
    v_p0_6_failed := 32;
    v_p0_6 := jsonb_build_object('error', SQLERRM, 'passed', 0, 'failed', 32, 'total_vectors', 32);
  END;

  -- Execute P0.7 Suite (Subcontractor, Advances, Petty Cash & Payroll)
  BEGIN
    v_p0_7 := public.run_p0_7_subcontractor_advances_payroll_forensic_suite();
    v_p0_7_passed := COALESCE((v_p0_7->>'passed')::INT, 0);
    v_p0_7_failed := COALESCE((v_p0_7->>'failed')::INT, 0);
  EXCEPTION WHEN OTHERS THEN
    v_p0_7_failed := 32;
    v_p0_7 := jsonb_build_object('error', SQLERRM, 'passed', 0, 'failed', 32, 'total_vectors', 32);
  END;

