  v_total_passed := v_p0_3_passed + v_p0_4_passed + v_p0_5_passed + v_p0_6_passed + v_p0_7_passed;
  v_total_failed := v_p0_3_failed + v_p0_4_failed + v_p0_5_failed + v_p0_6_failed + v_p0_7_failed;
  v_total_vectors := v_total_passed + v_total_failed;
  v_overall_rate := ROUND((v_total_passed::NUMERIC / NULLIF(v_total_vectors, 0)) * 100, 2);

