DECLARE
  v_user_id UUID;
  v_org_id UUID;
  v_sender UUID;
  v_mtype TEXT;
  v_from TIMESTAMPTZ;
  v_to TIMESTAMPTZ;
  v_eff_limit INT;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;

  SELECT organisation_id INTO v_org_id
  FROM project_collaboration_channels WHERE id = p_channel_id;
  IF v_org_id IS NULL THEN RAISE EXCEPTION 'channel_not_found'; END IF;
  IF NOT EXISTS (
    SELECT 1 FROM org_members WHERE organisation_id = v_org_id AND user_id = v_user_id
  ) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  v_sender := NULLIF(p_filters->>'sender_id','')::UUID;
  v_mtype  := NULLIF(p_filters->>'message_type','');
  v_from   := NULLIF(p_filters->>'date_from','')::TIMESTAMPTZ;
  v_to     := NULLIF(p_filters->>'date_to','')::TIMESTAMPTZ;
  v_eff_limit := COALESCE(NULLIF(p_limit, 0), 50);

  RETURN QUERY
  SELECT m.*
  FROM project_collaboration_messages m
  WHERE m.channel_id = p_channel_id
    AND m.deleted_at IS NULL
    AND (p_term IS NULL OR p_term = '' OR m.content ILIKE '%' || p_term || '%')
    AND (v_sender IS NULL OR m.sender_id = v_sender)
    AND (v_mtype  IS NULL OR m.message_type = v_mtype)
    AND (v_from   IS NULL OR m.created_at >= v_from)
    AND (v_to     IS NULL OR m.created_at <= v_to)
    AND (p_cursor IS NULL OR m.created_at < p_cursor)
  ORDER BY m.created_at DESC
  LIMIT v_eff_limit;
END;

DECLARE
  v_matches JSONB;
  v_in_scope BOOLEAN := false;
BEGIN
  -- Search for matching quotation items under approved/converted quotations
  SELECT COALESCE(JSONB_AGG(
    JSONB_BUILD_OBJECT(
      'item_name', COALESCE(qi.description, m.name, 'Unknown'),
      'quotation_no', qh.quotation_no,
      'rate', qi.rate,
      'approved_date', qh.date::text
    )
  ), '[]'::jsonb) INTO v_matches
  FROM public.quotation_items qi
  JOIN public.quotation_header qh ON qh.id = qi.quotation_id
  LEFT JOIN public.materials m ON m.id = qi.item_id
  WHERE qh.project_id = p_project_id
    AND (LOWER(qh.status) = 'approved' OR LOWER(qh.status) = 'converted')
    AND (
      qi.description ILIKE '%' || p_keyword || '%'
      OR m.name ILIKE '%' || p_keyword || '%'
    );

  IF jsonb_array_length(v_matches) > 0 THEN
    v_in_scope := true;
  END IF;

  RETURN jsonb_build_object(
    'matches', v_matches,
    'in_scope', v_in_scope
  );
END;

