DECLARE
  v_user_id UUID;
  v_org_id UUID;
  v_archived BOOLEAN;
  v_msg project_collaboration_messages;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'not_authenticated';
  END IF;

  SELECT organisation_id, is_archived
    INTO v_org_id, v_archived
  FROM project_collaboration_channels
  WHERE id = p_channel_id;
  IF v_org_id IS NULL THEN
    RAISE EXCEPTION 'channel_not_found';
  END IF;
  IF v_archived THEN
    RAISE EXCEPTION 'channel_archived';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM org_members
    WHERE organisation_id = v_org_id AND user_id = v_user_id
  ) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  -- Idempotent: same (channel, client_msg_id) returns existing row.
  IF p_client_msg_id IS NOT NULL THEN
    SELECT * INTO v_msg
    FROM project_collaboration_messages
    WHERE channel_id = p_channel_id AND client_msg_id = p_client_msg_id;
    IF FOUND THEN
      RETURN v_msg;
    END IF;
  END IF;

  INSERT INTO project_collaboration_messages (
    organisation_id, channel_id, sender_id, parent_message_id,
    message_type, content, metadata, client_msg_id
  )
  VALUES (
    v_org_id, p_channel_id, v_user_id, p_parent_message_id,
    COALESCE(p_message_type, 'text'),
    COALESCE(p_content, ''),
    COALESCE(p_metadata, '{}'::jsonb),
    p_client_msg_id
  )
  RETURNING * INTO v_msg;

  -- Audit (best-effort: a failed audit row must not fail the message).
  BEGIN
    INSERT INTO audit_log (organisation_id, user_id, action, entity_type, entity_id, changes)
    VALUES (v_org_id, v_user_id, 'CREATE', 'collab_message', v_msg.id,
            jsonb_build_object('message_type', v_msg.message_type, 'channel_id', v_msg.channel_id));
  EXCEPTION WHEN OTHERS THEN
    NULL;
  END;

  RETURN v_msg;
END;

