  -- Clean up
  EXECUTE 'ALTER TABLE public.delivery_challans DISABLE TRIGGER USER';
  DELETE FROM public.delivery_challan_items WHERE material_id = v_item_id;
  DELETE FROM public.delivery_challans WHERE organisation_id = v_test_org_id AND dc_number LIKE 'DC-TEST-A1%';
  EXECUTE 'ALTER TABLE public.delivery_challans ENABLE TRIGGER USER';

  DELETE FROM public.material_logs WHERE item_id = v_item_id;
  DELETE FROM public.item_stock WHERE item_id = v_item_id;
  DELETE FROM public.materials WHERE id = v_item_id;
  DELETE FROM public.warehouses WHERE id = v_wh_id;

  RETURN v_results;
