DECLARE
  v_float RECORD;
  v_bank_account_id UUID;
  v_petty_cash_account_id UUID;
  v_journal_id UUID;
  v_ref_no TEXT;
  v_creator_id UUID;
  v_total_debit NUMERIC(15,2);
  v_total_credit NUMERIC(15,2);
  v_new_balance NUMERIC(15,2);
BEGIN
  IF auth.uid() IS NOT NULL AND NOT public.user_can_access_org(p_organisation_id) THEN
    RAISE EXCEPTION 'Unauthorized organization access';
  END IF;

  IF p_amount <= 0 THEN
    RAISE EXCEPTION 'Top up amount must be greater than zero';
  END IF;

  SELECT * INTO v_float
  FROM public.petty_cash_floats
  WHERE id = p_float_id AND organisation_id = p_organisation_id
  FOR UPDATE;

  IF v_float IS NULL THEN
    RAISE EXCEPTION 'Petty cash float not found';
  END IF;

  SELECT id INTO v_creator_id
  FROM public.user_profiles WHERE user_id = auth.uid() OR id = auth.uid() LIMIT 1;

  v_bank_account_id := public.ensure_gl_account_exists(p_organisation_id, '1200', 'Bank Account', 'Asset');
  v_petty_cash_account_id := public.ensure_gl_account_exists(p_organisation_id, '1301', 'Petty Cash Float', 'Asset');

  v_new_balance := v_float.current_balance + p_amount;

  UPDATE public.petty_cash_floats
  SET current_balance = v_new_balance,
      updated_at = NOW()
  WHERE id = p_float_id;

  v_ref_no := COALESCE(p_reference_no, 'TOPUP-' || TO_CHAR(NOW(), 'YYYYMMDD-HH24MISS'));

  -- Post GL: Dr 1301 Petty Cash / Cr 1200 Bank
  INSERT INTO public.journal_entries (
    company_id, voucher_no, voucher_date, voucher_type, narration, status, created_by
  ) VALUES (
    p_organisation_id, v_ref_no, CURRENT_DATE, 'Payment',
    'Petty Cash Float Top-up for ' || COALESCE(v_float.holder_name, 'Holder'),
    'Posted', v_creator_id
  ) RETURNING id INTO v_journal_id;

  INSERT INTO public.journal_entry_lines (journal_id, account_id, party_type, party_id, debit, credit, narration)
  VALUES (v_journal_id, v_petty_cash_account_id, 'employee', v_float.holder_id, p_amount, 0.00, 'Petty Cash Float Inflow');

  INSERT INTO public.journal_entry_lines (journal_id, account_id, party_type, party_id, debit, credit, narration)
  VALUES (v_journal_id, v_bank_account_id, 'employee', v_float.holder_id, 0.00, p_amount, 'Bank Account Outflow for Petty Cash');

  SELECT SUM(COALESCE(debit,0)), SUM(COALESCE(credit,0))
  INTO v_total_debit, v_total_credit
  FROM public.journal_entry_lines WHERE journal_id = v_journal_id;

  IF ABS(v_total_debit - v_total_credit) > 0.01 THEN
    RAISE EXCEPTION 'GL imbalance: debit=% credit=%. Transaction rolled back.', v_total_debit, v_total_credit;
  END IF;

  RETURN jsonb_build_object(
