  END IF;

  v_new_status := UPPER(COALESCE(NULLIF(p_dc_data->>'status', ''), v_dc.status, 'ACTIVE'));
  IF v_new_status NOT IN ('DRAFT', 'ACTIVE', 'NOT SENT') THEN
    v_new_status := 'ACTIVE';
