  v_new_stock_affecting := (v_new_status != 'DRAFT');
  v_warehouse_id := COALESCE((NULLIF(p_dc_data->>'warehouse_id', ''))::UUID, v_dc.warehouse_id);

  -- Direct CTE loop without temp table
  FOR r_delta IN 
    WITH old_summary AS (
      SELECT 
        material_id,
        COALESCE(warehouse_id, v_dc.warehouse_id) AS warehouse_id,
        variant_id,
        material_name,
        SUM(quantity) AS qty
      FROM public.delivery_challan_items
      WHERE delivery_challan_id = p_dc_id
      GROUP BY 1, 2, 3, 4
    ),
    new_summary AS (
      SELECT 
        (elem->>'material_id')::UUID AS material_id,
        COALESCE((NULLIF(elem->>'warehouse_id', ''))::UUID, v_warehouse_id) AS warehouse_id,
        (NULLIF(elem->>'variant_id', ''))::UUID AS variant_id,
        COALESCE(elem->>'material_name', 'Item') AS material_name,
        SUM((elem->>'quantity')::NUMERIC) AS qty
      FROM jsonb_array_elements(p_items) AS elem
      WHERE COALESCE((elem->>'is_service')::BOOLEAN, false) = false
        AND (elem->>'material_id') IS NOT NULL
      GROUP BY 1, 2, 3, 4
    ),
    combined AS (
