DECLARE
  ri RECORD;
  rs RECORD;
  original_qty DECIMAL(10,2);
  total_returned DECIMAL(10,2);
  lock_placeholder INT;
BEGIN
  IF NEW.status = 'completed' AND OLD.status <> 'completed' THEN
    -- Loop through all child items
    FOR ri IN (SELECT id, item_id, variant_id FROM public.return_items WHERE return_id = NEW.id) LOOP
      -- Loop through source mappings
      FOR rs IN (SELECT id, invoice_item_id, delivery_challan_item_id, quantity FROM public.return_sources WHERE return_item_id = ri.id) LOOP
        
        -- Acquire row lock to serialize same-instant completions
        IF rs.invoice_item_id IS NOT NULL THEN
          SELECT 1 INTO lock_placeholder FROM public.invoice_items WHERE id = rs.invoice_item_id FOR UPDATE;
          SELECT qty INTO original_qty FROM public.invoice_items WHERE id = rs.invoice_item_id;
        ELSE
          SELECT 1 INTO lock_placeholder FROM public.delivery_challan_items WHERE id = rs.delivery_challan_item_id FOR UPDATE;
          SELECT quantity INTO original_qty FROM public.delivery_challan_items WHERE id = rs.delivery_challan_item_id;
        END IF;

        IF original_qty IS NULL THEN
          RAISE EXCEPTION 'Original source item not found for source mapping ID %.', rs.id;
        END IF;

        -- Sum already returned quantities (excluding current return document)
        SELECT COALESCE(SUM(rs_other.quantity), 0)
        INTO total_returned
        FROM public.return_sources rs_other
        JOIN public.return_items ri_other ON ri_other.id = rs_other.return_item_id
        JOIN public.returns r_other ON r_other.id = ri_other.return_id
        WHERE (
          (rs_other.invoice_item_id = rs.invoice_item_id AND rs.invoice_item_id IS NOT NULL) OR 
          (rs_other.delivery_challan_item_id = rs.delivery_challan_item_id AND rs.delivery_challan_item_id IS NOT NULL)
        )
          AND r_other.status = 'completed'
          AND r_other.id <> NEW.id;

        IF (total_returned + rs.quantity) > original_qty THEN
          RAISE EXCEPTION 'Cannot complete return. Mapped quantity of % for item % exceeds remaining available supply quantity % (Original: %, Already Returned: %)', 
            rs.quantity, ri.item_id, (original_qty - total_returned), original_qty, total_returned;
        END IF;

      END LOOP;
    END LOOP;
  END IF;

  RETURN NEW;
END;

DECLARE
  original_qty DECIMAL(10,2);
  total_returned DECIMAL(10,2);
BEGIN
  -- Get original quantity
  IF NEW.invoice_item_id IS NOT NULL THEN
    SELECT qty INTO original_qty FROM public.invoice_items WHERE id = NEW.invoice_item_id;
  ELSE
    SELECT quantity INTO original_qty FROM public.delivery_challan_items WHERE id = NEW.delivery_challan_item_id;
  END IF;

  IF original_qty IS NULL THEN
    RAISE EXCEPTION 'Original source item not found.';
  END IF;

  -- Calculate already returned quantity (completed only, excluding current row if update)
  SELECT COALESCE(SUM(rs.quantity), 0)
  INTO total_returned
  FROM public.return_sources rs
  JOIN public.return_items ri ON ri.id = rs.return_item_id
  JOIN public.returns r ON r.id = ri.return_id
  WHERE (
    (rs.invoice_item_id = NEW.invoice_item_id AND NEW.invoice_item_id IS NOT NULL) OR 
    (rs.delivery_challan_item_id = NEW.delivery_challan_item_id AND NEW.delivery_challan_item_id IS NOT NULL)
  )
    AND r.status = 'completed'
    AND rs.id <> COALESCE(NEW.id, '00000000-0000-0000-0000-000000000000'::uuid);

  IF (total_returned + NEW.quantity) > original_qty THEN
    RAISE EXCEPTION 'Return quantity % exceeds remaining available supply quantity % (Original: %, Already Returned: %)', 
      NEW.quantity, (original_qty - total_returned), original_qty, total_returned;
  END IF;

  RETURN NEW;
END;

DECLARE
    v_parent_org uuid;
BEGIN
    -- site_visits -> clients
    IF TG_TABLE_NAME = 'site_visits' THEN
        IF NEW.client_id IS NOT NULL THEN
            SELECT organisation_id INTO v_parent_org FROM public.clients WHERE id = NEW.client_id;
            IF v_parent_org IS NOT NULL AND v_parent_org <> NEW.organisation_id THEN
                RAISE EXCEPTION 'Cross-tenant FK violation: client % belongs to organisation %, not %', NEW.client_id, v_parent_org, NEW.organisation_id;
            END IF;
        END IF;
    END IF;

    -- client_communication -> clients
    IF TG_TABLE_NAME = 'client_communication' THEN
        IF NEW.client_id IS NOT NULL THEN
            SELECT organisation_id INTO v_parent_org FROM public.clients WHERE id = NEW.client_id;
            IF v_parent_org IS NOT NULL AND v_parent_org <> NEW.organisation_id THEN
                RAISE EXCEPTION 'Cross-tenant FK violation: client % belongs to organisation %, not %', NEW.client_id, v_parent_org, NEW.organisation_id;
            END IF;
        END IF;
    END IF;

    -- site_reports -> clients
    IF TG_TABLE_NAME = 'site_reports' THEN
        IF NEW.client_id IS NOT NULL THEN
            SELECT organisation_id INTO v_parent_org FROM public.clients WHERE id = NEW.client_id;
            IF v_parent_org IS NOT NULL AND v_parent_org <> NEW.organisation_id THEN
                RAISE EXCEPTION 'Cross-tenant FK violation: client % belongs to organisation %, not %', NEW.client_id, v_parent_org, NEW.organisation_id;
            END IF;
        END IF;
    END IF;

    -- stock_transfers -> warehouses
    IF TG_TABLE_NAME = 'stock_transfers' THEN
        IF NEW.from_warehouse_id IS NOT NULL THEN
            SELECT organisation_id INTO v_parent_org FROM public.warehouses WHERE id = NEW.from_warehouse_id;
            IF v_parent_org IS NOT NULL AND v_parent_org <> NEW.organisation_id THEN
                RAISE EXCEPTION 'Cross-tenant FK violation: from_warehouse belongs to %, not %', v_parent_org, NEW.organisation_id;
            END IF;
        END IF;
        IF NEW.to_warehouse_id IS NOT NULL THEN
            SELECT organisation_id INTO v_parent_org FROM public.warehouses WHERE id = NEW.to_warehouse_id;
            IF v_parent_org IS NOT NULL AND v_parent_org <> NEW.organisation_id THEN
                RAISE EXCEPTION 'Cross-tenant FK violation: to_warehouse belongs to %, not %', v_parent_org, NEW.organisation_id;
            END IF;
        END IF;
    END IF;

    -- warehouse_transfers -> warehouse_bins
    IF TG_TABLE_NAME = 'warehouse_transfers' THEN
        IF NEW.source_bin_id IS NOT NULL THEN
            SELECT organisation_id INTO v_parent_org FROM public.warehouse_bins WHERE id = NEW.source_bin_id;
            IF v_parent_org IS NOT NULL AND v_parent_org <> NEW.organisation_id THEN
                RAISE EXCEPTION 'Cross-tenant FK violation: source_bin belongs to %, not %', v_parent_org, NEW.organisation_id;
            END IF;
        END IF;
        IF NEW.destination_bin_id IS NOT NULL THEN
            SELECT organisation_id INTO v_parent_org FROM public.warehouse_bins WHERE id = NEW.destination_bin_id;
            IF v_parent_org IS NOT NULL AND v_parent_org <> NEW.organisation_id THEN
                RAISE EXCEPTION 'Cross-tenant FK violation: destination_bin belongs to %, not %', v_parent_org, NEW.organisation_id;
            END IF;
        END IF;
    END IF;

    RETURN NEW;
END;

DECLARE
  v_bill record;
  v_po record;
  v_set record;
  v_received numeric := 0;
  v_qty_variance numeric := 0;
  v_value_variance numeric := 0;
  v_date_variance int := 0;
  v_status text := 'PASSED';
  v_message text := '3-way check passed';
BEGIN
  IF auth.uid() IS NOT NULL AND NOT public.user_can_access_org(p_organisation_id) THEN
    RAISE EXCEPTION 'Unauthorized organization access';
  END IF;

  SELECT * INTO v_bill
  FROM public.purchase_bills
  WHERE id = p_bill_id AND organisation_id = p_organisation_id;
  IF v_bill.id IS NULL THEN
    RAISE EXCEPTION 'Bill not found';
  END IF;

  SELECT * INTO v_po
  FROM public.purchase_orders
  WHERE id = v_bill.po_id AND organisation_id = p_organisation_id;

  SELECT * INTO v_set
  FROM public.purchase_iv_settings
  WHERE organisation_id = p_organisation_id;
  IF v_set.id IS NULL THEN
    INSERT INTO public.purchase_iv_settings(organisation_id) VALUES (p_organisation_id)
    RETURNING * INTO v_set;
  END IF;

  IF v_po.id IS NOT NULL THEN
    SELECT COALESCE(SUM(grl.received_qty), 0) INTO v_received
    FROM public.goods_receipts gr
    JOIN public.goods_receipt_lines grl ON grl.goods_receipt_id = gr.id
    WHERE gr.organisation_id = p_organisation_id
      AND gr.po_id = v_po.id;

    IF COALESCE(v_bill.total_amount,0) > 0 AND COALESCE(v_po.grand_total,0) > 0 THEN
      v_value_variance := ABS((v_bill.total_amount - v_po.grand_total) / NULLIF(v_po.grand_total,0)) * 100;
    END IF;

    IF COALESCE(v_po.po_date, CURRENT_DATE) IS NOT NULL AND COALESCE(v_bill.bill_date, CURRENT_DATE) IS NOT NULL THEN
      v_date_variance := ABS(v_bill.bill_date - v_po.po_date);
    END IF;

    DECLARE v_po_qty NUMERIC := 0;
    BEGIN
      SELECT COALESCE(SUM(quantity),0) INTO v_po_qty
      FROM public.purchase_order_items
      WHERE po_id = v_po.id AND organisation_id = p_organisation_id;
      IF v_po_qty > 0 THEN
        v_qty_variance := ABS((v_po_qty - v_received) / v_po_qty) * 100;
      END IF;
    END;
  ELSE
    v_status := 'WARN';
    v_message := 'PO link missing for 3-way verification';
  END IF;

  IF v_qty_variance > v_set.qty_tolerance_percent
     OR v_value_variance > v_set.value_tolerance_percent
     OR v_date_variance > v_set.date_tolerance_days THEN
    v_status := 'FAILED';
    v_message := 'Tolerance exceeded';
  ELSIF v_status = 'PASSED' AND (v_qty_variance > 0 OR v_value_variance > 0 OR v_date_variance > 0) THEN
    v_status := 'WARN';
    v_message := 'Within tolerance';
  END IF;

  INSERT INTO public.purchase_invoice_verifications(
    organisation_id, bill_id, po_id, verification_status, qty_variance_percent, value_variance_percent, date_variance_days, message
  )
  VALUES (
    p_organisation_id, p_bill_id, v_bill.po_id, v_status, v_qty_variance, v_value_variance, v_date_variance, v_message
  )
  ON CONFLICT (organisation_id, bill_id)
  DO UPDATE SET
    verification_status = EXCLUDED.verification_status,
    qty_variance_percent = EXCLUDED.qty_variance_percent,
    value_variance_percent = EXCLUDED.value_variance_percent,
    date_variance_days = EXCLUDED.date_variance_days,
    message = EXCLUDED.message,
    updated_at = NOW();

  RETURN v_status;
END;

DECLARE
  v_clause JSONB;
BEGIN
  IF p_clauses IS NULL OR jsonb_typeof(p_clauses) <> 'array' OR jsonb_array_length(p_clauses) > 25 THEN
    RETURN FALSE;
  END IF;
  FOR v_clause IN SELECT value FROM jsonb_array_elements(p_clauses) LOOP
    IF jsonb_typeof(v_clause) <> 'string' OR length(v_clause #>> '{}') > 2000 THEN
      RETURN FALSE;
    END IF;
  END LOOP;
  RETURN TRUE;
END;
